def _ensure_favicon(html):
    """تضمين أيقونة التطبيق في رأس الصفحة."""
    if not html or "/favicon.png" in html or 'rel="icon"' in html:
        return html
    if "</head>" in html:
        return html.replace("</head>", _FAVICON_LINK + "</head>", 1)
    return html


_ARABIC_PDF_FONTS_READY = False
_PDF_ARABIC_REG = "PdfArabic"
_PDF_ARABIC_BOLD_REG = "PdfArabic-Bold"
_CC_TAHOMA_FONTS_READY = False
_PDF_TAHOMA_REG = "PdfTahoma"
_PDF_TAHOMA_BOLD_REG = "PdfTahoma-Bold"


def _pdf_font_search_dirs():
    base = _app_base_dir()
    dirs = [
        os.path.join(base, "@Fonts"),
        os.path.join(base, "Fonts"),
        os.path.join(BASE_DIR, "@Fonts"),
        os.path.join(BASE_DIR, "Fonts"),
        "/System/Library/Fonts/Supplemental",
        "/Library/Fonts",
        "/usr/share/fonts/truetype",
        "/usr/share/fonts/truetype/dejavu",
        "/usr/share/fonts/TTF",
    ]
    if sys.platform == "win32":
        win_fonts = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
        dirs.insert(2, win_fonts)
    return [d for d in dirs if d and os.path.isdir(d)]


def _resolve_pdf_arabic_fonts():
    """خط عربي للـ PDF: Tahoma/Arial على Windows/Mac، أو Droid Arabic Kufi من مجلد المشروع (Railway/Linux)."""
    pairs = [
        ("Tahoma.ttf", "Tahoma Bold.ttf"),
        ("arial.ttf", "arialbd.ttf"),
        ("Arial.ttf", "Arial Bold.ttf"),
        ("Arial Unicode.ttf", "Arial Unicode.ttf"),
    ]
    for d in _pdf_font_search_dirs():
        for regular_name, bold_name in pairs:
            regular = os.path.join(d, regular_name)
            if not os.path.isfile(regular):
                continue
            low = regular.lower()
            if "droid" in low or "kufi" in low:
                continue
            bold = os.path.join(d, bold_name)
            if not os.path.isfile(bold):
                bold = regular
            return regular, bold
    # Linux / Railway: خط المشروع المضمّن (ضروري لحاسبة التكاليف وPDF العربي)
    for d in _pdf_font_search_dirs():
        for name in ("Droid Arabic Kufi.ttf", "DroidArabicKufi.ttf"):
            regular = os.path.join(d, name)
            if os.path.isfile(regular):
                return regular, regular
    return None, None


def _arabic_pdf_font_path():
    resolved = _resolve_pdf_arabic_fonts()
    return resolved[0] if resolved else None


def _has_arabic_text(s):
    return bool(re.search(r"[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]", str(s or "")))


def _shape_pdf_text(text):
    s = str(text) if text is not None else ""
    if not s or not _has_arabic_text(s):
        return s
    try:
        import arabic_reshaper
        from bidi.algorithm import get_display
        return get_display(arabic_reshaper.reshape(s))
    except Exception:
        return s


def _pdf_font_path_no_spaces(src_path, cache_name="accounting_app_font.ttf"):
    """نسخ الخط إلى مسار بدون فراغات (أكثر أماناً مع reportlab على Linux)."""
    if not src_path or not os.path.isfile(src_path):
        return src_path
    if " " not in src_path:
        return src_path
    try:
        dest = os.path.join(tempfile.gettempdir(), cache_name)
        if not os.path.isfile(dest) or os.path.getmtime(dest) < os.path.getmtime(src_path):
            shutil.copy2(src_path, dest)
        return dest
    except OSError:
        return src_path


def _resolve_tahoma_pdf_fonts():
    """خط Tahoma لـ PDF حاسبة التكاليف — من مجلد المشروع أولاً ثم النظام."""
    pairs = [
        ("Tahoma.ttf", "Tahoma Bold.ttf"),
        ("Tahoma.ttf", "tahomabd.ttf"),
        ("tahoma.ttf", "Tahoma Bold.ttf"),
        ("tahoma.ttf", "tahomabd.ttf"),
    ]
    for d in _pdf_font_search_dirs():
        for regular_name, bold_name in pairs:
            regular = os.path.join(d, regular_name)
            if not os.path.isfile(regular):
                continue
            bold = os.path.join(d, bold_name)
            if not os.path.isfile(bold):
                bold = regular
            return regular, bold
    return None, None


def register_cost_calculator_pdf_fonts():
    """تسجيل Tahoma لملف PDF حاسبة التكاليف فقط."""
    global _CC_TAHOMA_FONTS_READY
    if _CC_TAHOMA_FONTS_READY:
        return
    resolved = _resolve_tahoma_pdf_fonts()
    if not resolved:
        raise RuntimeError(
            "خط Tahoma غير موجود. أضف Fonts/Tahoma.ttf و Fonts/Tahoma Bold.ttf إلى المشروع "
            "(شغّل package_for_github.py على Mac/Windows لنسخهما تلقائياً)."
        )
    regular, bold = resolved
    regular = _pdf_font_path_no_spaces(regular, "accounting_app_tahoma.ttf")
    bold = _pdf_font_path_no_spaces(bold, "accounting_app_tahoma_bold.ttf")
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    pdfmetrics.registerFont(TTFont(_PDF_TAHOMA_REG, regular))
    pdfmetrics.registerFont(TTFont(_PDF_TAHOMA_BOLD_REG, bold))
    _CC_TAHOMA_FONTS_READY = True


def cost_calculator_pdf_font_names():
    register_cost_calculator_pdf_fonts()
    return _PDF_TAHOMA_REG, _PDF_TAHOMA_BOLD_REG


def register_pdf_arabic_fonts():
    global _ARABIC_PDF_FONTS_READY
    if _ARABIC_PDF_FONTS_READY:
        return
    resolved = _resolve_pdf_arabic_fonts()
    if resolved:
        regular, bold = resolved
        regular = _pdf_font_path_no_spaces(regular, "accounting_app_arabic.ttf")
        bold = _pdf_font_path_no_spaces(bold, "accounting_app_arabic_bold.ttf")
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        pdfmetrics.registerFont(TTFont(_PDF_ARABIC_REG, regular))
        pdfmetrics.registerFont(TTFont(_PDF_ARABIC_BOLD_REG, bold))
    _ARABIC_PDF_FONTS_READY = True


def _pdf_stack_status():
    """حالة مكتبات PDF والخط العربي (للتشخيص على Railway)."""
    parts = []
    try:
        import reportlab  # noqa: F401
        parts.append("reportlab=ok")
    except ImportError as e:
        parts.append(f"reportlab=missing({e})")
    try:
        import PIL  # noqa: F401
        parts.append("pillow=ok")
    except ImportError:
        parts.append("pillow=missing")
    try:
        register_pdf_arabic_fonts()
        fp = _arabic_pdf_font_path()
        parts.append("font=" + (os.path.basename(fp) if fp else "NONE"))
    except Exception as e:
        parts.append(f"font_err={e}")
    try:
        register_cost_calculator_pdf_fonts()
        tp = _resolve_tahoma_pdf_fonts()
        parts.append("tahoma=" + (os.path.basename(tp[0]) if tp else "NONE"))
    except Exception as e:
        parts.append(f"tahoma_err={e}")
    return " ".join(parts)


def pdf_font_names():
    register_pdf_arabic_fonts()
    if _arabic_pdf_font_path():
        return _PDF_ARABIC_REG, _PDF_ARABIC_BOLD_REG
    return "Helvetica", "Helvetica-Bold"


