def _alert_html(msg, msg_type="ok"):
    """تنبيه موحّد مع أيقونة صح/خطأ."""
    if not msg:
        return ""
    mt = "ok" if str(msg_type or "ok") == "ok" else "err"
    icon = "fa-circle-check" if mt == "ok" else "fa-circle-xmark"
    return (
        f'<div class="alert {mt}">'
        f'<i class="fa-solid {icon}" style="margin-left:8px"></i>'
        f"{_fmt_mv_words(msg)}</div>"
    )


def _clean_url_search_term(val):
    """تنظيف نص البحث من بقايا معاملات query."""
    s = str(val or "").strip()
    if not s:
        return None
    if "?" in s:
        s = s.split("?", 1)[0].strip()
    if "&" in s:
        s = s.split("&", 1)[0].strip()
    return s or None


def _session_cookie_header(cookie_val, handler=None):
    """كوكي جلسة — لا يُخزَّن بشكل دائم (يُمسح عند إغلاق المتصفح/التبويب)."""
    parts = [f"{_SESSION_COOKIE_NAME}={cookie_val}", "Path=/", "HttpOnly", "SameSite=Lax"]
    if handler:
        proto = (handler.headers.get("X-Forwarded-Proto") or "").lower()
        if proto == "https" or os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"):
            parts.append("Secure")
    return "; ".join(parts)


def _clear_session_cookie_header(handler=None):
    parts = [f"{_SESSION_COOKIE_NAME}=", "Path=/", "HttpOnly", "Max-Age=0", "SameSite=Lax"]
    if handler:
        proto = (handler.headers.get("X-Forwarded-Proto") or "").lower()
        if proto == "https" or os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"):
            parts.append("Secure")
    return "; ".join(parts)


