_ARABIC_DIGIT_TRANS = str.maketrans({
    ord("٠"): "0", ord("١"): "1", ord("٢"): "2", ord("٣"): "3", ord("٤"): "4",
    ord("٥"): "5", ord("٦"): "6", ord("٧"): "7", ord("٨"): "8", ord("٩"): "9",
    ord("۰"): "0", ord("۱"): "1", ord("۲"): "2", ord("۳"): "3", ord("۴"): "4",
    ord("۵"): "5", ord("۶"): "6", ord("۷"): "7", ord("۸"): "8", ord("۹"): "9",
    ord("٫"): ".", ord("،"): ",", ord("٬"): ",",
})


def _normalize_arabic_digits(value):
    """تحويل الأرقام العربية/الفارسية والفواصل إلى الإنجليزية."""
    if value is None:
        return value
    if not isinstance(value, str):
        value = str(value)
    return value.translate(_ARABIC_DIGIT_TRANS)


_ARABIC_NUMERALS_JS = """<script id="acc-arabic-digits">
(function(){
  if(window.__accArabicDigitsBound)return;
  window.__accArabicDigitsBound=1;
  var map={'٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9',
           '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9',
           '٫':'.','،':'.','٬':'.'};
  var re=/[٠-٩۰-۹٫،٬]/g;
  function normDigits(s){
    if(s==null) return s;
    return String(s).replace(re,function(ch){return map[ch]||ch;});
  }
  window._accNormDigits=normDigits;
  function isTarget(el){
    if(!el||el.disabled||el.readOnly) return false;
    if(el instanceof HTMLInputElement){
      var t=(el.type||'text').toLowerCase();
      return t!=='password'&&t!=='email'&&t!=='url'&&t!=='file'&&t!=='checkbox'&&t!=='radio'&&t!=='hidden'&&t!=='submit'&&t!=='button'&&t!=='reset'&&t!=='image'&&t!=='color'&&t!=='range'&&t!=='date'&&t!=='time'&&t!=='datetime-local'&&t!=='month'&&t!=='week';
    }
    return el instanceof HTMLTextAreaElement;
  }
  function isNumberLike(el){
    if(!(el instanceof HTMLInputElement)) return false;
    if(el.dataset.accDecField==='1') return true;
    var t=(el.type||'').toLowerCase();
    var mode=(el.getAttribute('inputmode')||'').toLowerCase();
    return t==='number'||t==='tel'||mode==='decimal'||mode==='numeric';
  }
  function wantsDecimals(el){
    if(!(el instanceof HTMLInputElement)) return false;
    var step=el.getAttribute('step');
    if(!step) return false;
    if(step==='any') return true;
    var n=parseFloat(step);
    return !isNaN(n) && n>0 && n<1;
  }
  function unlockDecimalField(el){
    /* type=number يسقط النقطة والأصفار أثناء الكتابة — حوّله لنص مع لوحة عشرية */
    if(!(el instanceof HTMLInputElement)) return;
    if((el.type||'').toLowerCase()!=='number') return;
    if(!wantsDecimals(el) && el.dataset.accDecField!=='1') return;
    try{
      el.dataset.accDecField='1';
      el.type='text';
      el.setAttribute('inputmode','decimal');
      if(!el.getAttribute('autocomplete')) el.setAttribute('autocomplete','off');
    }catch(e){}
  }
  function fireInput(el){
    try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){}
    try{el.dispatchEvent(new Event('change',{bubbles:true}));}catch(e){}
  }
  function clearNeedDot(el){
    try{delete el.dataset.accNeedDot;}catch(e){}
  }
  function apply(el){
    if(!isTarget(el)) return;
    var v=el.value;
    if(v==null||v==='') return;
    var nv=normDigits(v);
    if(isNumberLike(el)) nv=nv.replace(/,/g,'.');
    if(v===nv) return;
    var start=null;
    try{start=el.selectionStart;}catch(e){start=null;}
    var before=(typeof start==='number'&&start>=0)?v.slice(0,start):v;
    el.value=nv;
    if(el.type!=='number'){
      var np=normDigits(before).replace(/,/g,'.').length;
      try{if(document.activeElement===el)el.setSelectionRange(np,np);}catch(e){}
    }
  }
  function insertAt(el,text){
    text=normDigits(String(text||'')).replace(/,/g,'.');
    if(!text) return;
    unlockDecimalField(el);
    if(isNumberLike(el)){
      var v=String(el.value||'');
      var canTrailDot=(el.type!=='number');
      if(text==='.'){
        if(v.indexOf('.')>=0) return;
        if(canTrailDot){
          clearNeedDot(el);
          el.value=v+'.';
          fireInput(el);
          try{el.setSelectionRange(el.value.length,el.value.length);}catch(e){}
          return;
        }
        if(el.dataset.accNeedDot==='1') return;
        el.dataset.accNeedDot='1';
        return;
      }
      if(el.dataset.accNeedDot==='1'){
        clearNeedDot(el);
        if(/^[0-9]+$/.test(text)){
          el.value=(v.indexOf('.')>=0?v:((v===''?'0':v)+'.'))+text;
          fireInput(el);
          return;
        }
      }
      if(/[^0-9.\\-]/.test(text)) text=text.replace(/[^0-9.\\-]/g,'');
      if(!text) return;
      if(canTrailDot){
        var start=el.selectionStart==null?v.length:el.selectionStart;
        var end=el.selectionEnd==null?start:el.selectionEnd;
        var next=v.slice(0,start)+text+v.slice(end);
        if((next.match(/\\./g)||[]).length>1) return;
        el.value=next;
        var np=start+text.length;
        try{el.setSelectionRange(np,np);}catch(e){}
      }else{
        el.value=v+text;
      }
      fireInput(el);
      return;
    }
    var start=el.selectionStart==null?el.value.length:el.selectionStart;
    var end=el.selectionEnd==null?start:el.selectionEnd;
    var val=el.value;
    el.value=val.slice(0,start)+text+val.slice(end);
    var np=start+text.length;
    try{el.setSelectionRange(np,np);}catch(e){}
    fireInput(el);
  }
  document.addEventListener('keydown',function(e){
    if(e.isComposing||e.ctrlKey||e.metaKey||e.altKey) return;
    var el=e.target;
    if(!isTarget(el)) return;
    unlockDecimalField(el);
    var ch=e.key;
    if(ch==='Dead') return;
    if(isNumberLike(el)&&(ch==='.'||ch===','||ch==='٫'||ch==='،'||ch==='٬')){
      e.preventDefault();
      insertAt(el,'.');
      return;
    }
    if(isNumberLike(el)&&el.dataset.accNeedDot==='1'&&/^[0-9٠-٩۰-۹]$/.test(ch)){
      e.preventDefault();
      insertAt(el,ch);
      return;
    }
    var converted=map[ch];
    if(!converted) return;
    e.preventDefault();
    insertAt(el,converted);
  },true);
  document.addEventListener('beforeinput',function(e){
    var el=e.target;
    if(!isTarget(el)) return;
    unlockDecimalField(el);
    if(e.inputType!=='insertText'||!e.data) return;
    var raw=String(e.data);
    var converted=normDigits(raw).replace(/,/g,'.');
    if(isNumberLike(el)){
      var needs=
        converted!==raw ||
        converted.indexOf('.')>=0 ||
        el.dataset.accNeedDot==='1' ||
        /[٠-٩۰-۹٫،٬,]/.test(raw);
      if(!needs) return;
      e.preventDefault();
      insertAt(el,converted);
      return;
    }
    if(converted!==raw){
      e.preventDefault();
      insertAt(el,converted);
    }
  },true);
  document.addEventListener('input',function(e){apply(e.target);},true);
  document.addEventListener('paste',function(e){
    var el=e.target;
    if(!isTarget(el)) return;
    unlockDecimalField(el);
    var text=(e.clipboardData||window.clipboardData).getData('text');
    if(!text) return;
    var converted=normDigits(text).replace(/,/g,'.');
    if(converted===text&&!isNumberLike(el)) return;
    if(converted===text&&isNumberLike(el)&&converted===normDigits(text)) return;
    e.preventDefault();
    clearNeedDot(el);
    if(isNumberLike(el)){
      el.value=converted.replace(/[^0-9.\\-]/g,'');
      fireInput(el);
    }else{
      insertAt(el,converted);
    }
  },true);
  document.addEventListener('focusin',function(e){
    unlockDecimalField(e.target);
    apply(e.target);
  },true);
  document.addEventListener('focusout',function(e){
    var el=e.target;
    clearNeedDot(el);
    apply(el);
  },true);
  document.addEventListener('compositionend',function(e){apply(e.target);},true);
})();
</script>"""


def _inject_arabic_numerals_js(html):
    """إدراج سكربت تحويل الأرقام العربية في صفحة HTML."""
    if not html or 'id="acc-arabic-digits"' in html:
        return html
    idx = html.rfind("</body>")
    if idx >= 0:
        return html[:idx] + _ARABIC_NUMERALS_JS + "\n" + html[idx:]
    return html + _ARABIC_NUMERALS_JS


def _html_response_bytes(html):
    """تجهيز HTML للإرسال مع سكربت تحويل الأرقام."""
    if isinstance(html, bytes):
        return html
    return _inject_arabic_numerals_js(html).encode("utf-8")


def _make_session_cookie(username, password_hash):
    """إنشاء قيمة كوكي الجلسة (اسم المستخدم + التجزئة)."""
    raw = (str(username).strip() + ":" + (password_hash or "")).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii")

def _parse_session_cookie(cookie_value):
    """استخراج (username, password_hash) من قيمة الكوكي. يُرجع None إذا فشل."""
    if not cookie_value or not cookie_value.strip():
        return None
    try:
        raw = base64.urlsafe_b64decode(cookie_value.strip().encode("ascii")).decode("utf-8")
        if ":" not in raw:
            return None
        u, h = raw.split(":", 1)
        if not u or not h:
            return None
        return (u.strip(), h)
    except Exception:
        return None

def _get_session_user(handler):
    """التحقق من كوكي الجلسة في الطلب. يُرجع اسم المستخدم إذا الجلسة صالحة، وإلا None."""
    cookie_header = handler.headers.get("Cookie") or ""
    for part in cookie_header.split(";"):
        part = part.strip()
        if part.startswith(_SESSION_COOKIE_NAME + "="):
            val = part[len(_SESSION_COOKIE_NAME) + 1:].strip()
            parsed = _parse_session_cookie(val)
            if not parsed:
                return None
            username, stored_hash = parsed
            if get_app_user_hash(username) == stored_hash:
                return username
            return None
    return None


def _invoice_number_taken(invoice_number, exclude_id=None):
    """هل رقم الفاتورة مستخدم (بما في ذلك الفواتير الملغاة)؟"""
    inv_no = str(invoice_number or "").strip()
    if not inv_no:
        return False
    conn = sqlite3.connect(DB_PATH)
    try:
        if exclude_id:
            row = conn.execute(
                "SELECT id FROM invoices WHERE TRIM(invoice_number) = ? AND id != ? LIMIT 1",
                (inv_no, int(exclude_id)),
            ).fetchone()
        else:
            row = conn.execute(
                "SELECT id FROM invoices WHERE TRIM(invoice_number) = ? LIMIT 1",
                (inv_no,),
            ).fetchone()
    finally:
        conn.close()
    return bool(row)


def insert_invoice(date, inv, customer, total, down, remaining, receipt, payment_method="", notes="", payment_date=""):
    inv_no = str(inv or "").strip()
    if _invoice_number_taken(inv_no):
        raise ValueError(f"رقم الفاتورة {inv_no} مستخدم مسبقاً")
    conn = sqlite3.connect(DB_PATH)
    conn.execute("""INSERT INTO invoices (date, invoice_number, customer_name,
        total_amount, down_payment, remaining, receipt_number, pdf_path, payment_method, payment_date, notes)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""", (date, inv_no, customer, total, down, remaining, receipt, "", payment_method or "", payment_date or "", notes or ""))
    conn.commit()
    conn.close()


def update_invoice_by_number(invoice_number, date, customer, total, down, remaining, receipt, payment_method="", notes="", payment_date=""):
    """تحديث فاتورة موجودة برقمها — يُستخدم عند إعادة استيراد Excel."""
    inv_no = str(invoice_number or "").strip()
    if not inv_no:
        return False
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT id FROM invoices WHERE invoice_number = ?", (inv_no,)).fetchone()
    if not row:
        conn.close()
        return False
    conn.execute(
        """UPDATE invoices SET date = ?, customer_name = ?, total_amount = ?, down_payment = ?,
           remaining = ?, receipt_number = ?, payment_method = ?, payment_date = ?, notes = ? WHERE id = ?""",
        (date, customer, total, down, remaining, receipt, payment_method or "", payment_date or "", notes or "", row[0]),
    )
    conn.commit()
    conn.close()
    return True


def _excel_serial_to_date(serial):
    """تحويل الرقم التسلسلي لـ Excel إلى تاريخ YYYY-MM-DD"""
    try:
        n = float(serial)
        base = datetime(1899, 12, 30)
        d = base + timedelta(days=n)
        return d.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return ""


def _invoice_date_from_cell(val, override_month=None):
    """تحويل قيمة تاريخ من Excel إلى YYYY-MM-DD مع دعم شهر الاستيراد."""
    import calendar
    base = None
    if val is None or (isinstance(val, str) and not str(val).strip()):
        base = datetime.now().date()
    elif isinstance(val, datetime):
        base = val.date()
    elif hasattr(val, "year") and hasattr(val, "month") and hasattr(val, "day"):
        base = val
    elif isinstance(val, (int, float)) or (isinstance(val, str) and str(val).replace(".", "").replace("-", "").isdigit()):
        try:
            base = datetime.strptime(_excel_serial_to_date(val)[:10], "%Y-%m-%d").date()
        except Exception:
            base = datetime.now().date()
    else:
        s = str(val).strip()
        if "/" in s:
            try:
                parts = s.split("/")
                if len(parts) == 3:
                    d, m, y = int(parts[0]), int(parts[1]), int(parts[2])
                    if y < 100:
                        y += 2000
                    base = datetime(y, m, d).date()
            except Exception:
                pass
        if not base:
            try:
                base = datetime.strptime(s[:10], "%Y-%m-%d").date()
            except Exception:
                base = datetime.now().date()
    ym = str(override_month or "").strip()[:7]
    if ym and len(ym) == 7 and "-" in ym:
        try:
            y, m = map(int, ym.split("-"))
            last = calendar.monthrange(y, m)[1]
            day = min(max(1, base.day), last)
            return f"{y:04d}-{m:02d}-{day:02d}"
        except Exception:
            return ym + "-01"
    return base.strftime("%Y-%m-%d")


def _invoice_row_amounts(total_val, down_val, remaining_val):
    try:
        total_f = float(total_val or 0)
        down_f = float(down_val or 0)
        remaining_f = float(remaining_val or 0)
        if remaining_f == 0 and total_f > 0 and down_f == 0:
            remaining_f = total_f
        elif remaining_f == 0 and total_f > 0 and down_f > 0:
            remaining_f = total_f - down_f
    except (ValueError, TypeError):
        total_f, down_f, remaining_f = 0.0, 0.0, 0.0
    return total_f, down_f, remaining_f


def build_revenues_template_workbook():
    """تحميل مصنف النموذج المعتمد من revenues_template.xlsx."""
    import openpyxl
    save_revenues_template_file()
    path = REVENUES_TEMPLATE_PATH if os.path.isfile(REVENUES_TEMPLATE_PATH) else REVENUES_TEMPLATE_SOURCE
    if not os.path.isfile(path):
        raise FileNotFoundError("نموذج الإيرادات غير موجود — ضع revenues_template.xlsx في Downloads أو مجلد التطبيق")
    return openpyxl.load_workbook(path)


def save_revenues_template_file():
    """نسخ النموذج المعتمد من Downloads إلى مجلد التطبيق."""
    src = REVENUES_TEMPLATE_SOURCE if os.path.isfile(REVENUES_TEMPLATE_SOURCE) else REVENUES_TEMPLATE_PATH
    if not os.path.isfile(src):
        return False
    try:
        shutil.copy2(src, REVENUES_TEMPLATE_PATH)
        return True
    except Exception:
        return False


BACKUP_MANIFEST_NAME = "backup_manifest.json"
BACKUP_ARCHIVE_VERSION = 1


def _database_path_candidates():
    """كل مسارات قاعدة البيانات المحتملة (بدون تكرار)."""
    seen = set()
    for p in (
        DB_PATH,
        os.path.join(BASE_DIR, "database.db"),
        os.path.join(_DATA_DIR, "database.db"),
        os.path.join(BASE_DIR, "accounting.db"),
    ):
        p = os.path.normpath(p)
        if p in seen:
            continue
        seen.add(p)
        yield p


def _app_base_dir():
    """مجلد التطبيق — يضمن عدم إرجاع None (مهم على Railway)."""
    if BASE_DIR:
        return BASE_DIR
    return os.getcwd()


def _ensure_db_directory():
    """التأكد من وجود مجلد قاعدة البيانات (مثل /data على Railway)."""
    db_path = DB_PATH or os.path.join(_app_base_dir(), "database.db")
    parent = os.path.dirname(db_path)
    if parent:
        try:
            os.makedirs(parent, exist_ok=True)
        except OSError:
            pass
    return db_path


def _find_database_path():
    """مسار قاعدة البيانات الفعلية — الأكبر حجماً (لتفادي نسخ ملف فارغ من /data)."""
    best_path, best_size = None, 0
    for p in _database_path_candidates():
        if not p or not os.path.isfile(p):
            continue
        try:
            sz = os.path.getsize(p)
        except OSError:
            continue
        if sz > best_size:
            best_size, best_path = sz, p
    return best_path if best_size > 0 else None


def _snapshot_database_file(db_path):
    """نسخة آمنة من قاعدة البيانات (حتى أثناء تشغيل الخادم)."""
    if not db_path or not os.path.isfile(db_path):
        return None
    tmp = tempfile.NamedTemporaryFile(suffix=".db", delete=False)
    tmp_path = tmp.name
    tmp.close()
    if not tmp_path:
        return None
    try:
        src = sqlite3.connect(f"file:{os.path.abspath(db_path)}?mode=ro", uri=True, timeout=60)
        dst = sqlite3.connect(tmp_path)
        with dst:
            src.backup(dst)
        src.close()
        dst.close()
        if os.path.getsize(tmp_path) > 0:
            return tmp_path
    except Exception:
        pass
    try:
        shutil.copy2(db_path, tmp_path)
        if os.path.getsize(tmp_path) > 0:
            return tmp_path
    except Exception:
        pass
    try:
        os.unlink(tmp_path)
    except OSError:
        pass
    return None


def _find_extracted_database(extract_dir):
    """البحث عن database.db داخل مجلد الاستخراج (الجذر أو مجلد فرعي)."""
    if not extract_dir:
        return None
    direct = os.path.join(extract_dir, "database.db")
    if os.path.isfile(direct):
        return direct
    for root, _dirs, files in os.walk(extract_dir):
        if "database.db" in files:
            return os.path.join(root, "database.db")
    return None


def _iter_backup_files():
    """مسارات الملفات المهمة للنسخ الاحتياطي (المسار الكامل، الاسم داخل الأرشيف)."""
    base = _app_base_dir()
    for name in ("revenues_template.xlsx", "salaries_template.xlsx"):
        p = os.path.join(base, name)
        if os.path.isfile(p):
            yield p, name

    for dirname in ("Invoices", "Bank", "Salaries", "Expenses"):
        root_dir = os.path.join(base, dirname)
        if not os.path.isdir(root_dir):
            continue
        for root, _dirs, files in os.walk(root_dir):
            for fname in files:
                if not fname or fname.startswith(".") or fname.endswith((".tmp", ".temp")):
                    continue
                full = os.path.join(root, fname)
                if not full or not os.path.isfile(full):
                    continue
                try:
                    arc = os.path.relpath(full, base).replace("\\", "/")
                except (ValueError, TypeError):
                    continue
                if not arc or arc.startswith(".."):
                    continue
                yield full, arc


def create_app_backup_zip():
    """إنشاء ملف ZIP يحتوي قاعدة البيانات والملفات المهمة. يُرجع None إن لم تُوجد قاعدة بيانات."""
    import json

    db_path = _find_database_path()
    if not db_path:
        return None

    manifest = {
        "app": "AccountingApp",
        "version": BACKUP_ARCHIVE_VERSION,
        "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "database_path": "database.db",
        "database_source": db_path,
        "has_database": True,
        "files": [],
    }
    buf = io.BytesIO()
    snap_path = _snapshot_database_file(db_path)
    if not snap_path or not os.path.isfile(snap_path):
        return None
    try:
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
            zf.write(snap_path, arcname="database.db")
            manifest["files"].append("database.db")
            for full_path, arc_name in _iter_backup_files():
                if not full_path or not arc_name or not os.path.isfile(full_path):
                    continue
                try:
                    zf.write(full_path, arcname=arc_name)
                    manifest["files"].append(arc_name)
                except Exception:
                    pass
            manifest["file_count"] = len(manifest["files"])
            zf.writestr(
                BACKUP_MANIFEST_NAME,
                json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"),
            )
    finally:
        try:
            os.unlink(snap_path)
        except OSError:
            pass
    buf.seek(0)
    return buf.getvalue()


def restore_app_backup_zip(zip_bytes):
    """استعادة بيانات التطبيق من ملف نسخة احتياطية ZIP."""
    import json

    if not zip_bytes or len(zip_bytes) < 64:
        return False, "الملف فارغ أو غير صالح"
    tmp_zip = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    tmp_zip.write(zip_bytes)
    tmp_zip.close()
    extract_dir = tempfile.mkdtemp(prefix="acc_restore_")
    try:
        with zipfile.ZipFile(tmp_zip.name, "r") as zf:
            for name in zf.namelist():
                if ".." in name or name.startswith("/"):
                    return False, "ملف النسخة الاحتياطية غير آمن"
            zf.extractall(extract_dir)

        db_src = _find_extracted_database(extract_dir)
        if not db_src or not os.path.isfile(db_src):
            return False, "النسخة الاحتياطية لا تحتوي على قاعدة البيانات (database.db)"

        manifest_path = os.path.join(extract_dir, BACKUP_MANIFEST_NAME)
        if os.path.isfile(manifest_path):
            try:
                with open(manifest_path, encoding="utf-8") as mf:
                    manifest = json.load(mf)
                if manifest.get("app") and manifest.get("app") != "AccountingApp":
                    return False, "هذا الملف ليس نسخة احتياطية من هذا البرنامج"
            except Exception:
                pass

        db_dest = _ensure_db_directory()
        if os.path.isfile(db_dest):
            try:
                shutil.copy2(db_dest, db_dest + ".bak_before_restore")
            except Exception:
                pass
        shutil.copy2(db_src, db_dest)

        base = _app_base_dir()
        for root, _dirs, files in os.walk(extract_dir):
            for fname in files:
                if not fname or fname in (BACKUP_MANIFEST_NAME, "database.db"):
                    continue
                src = os.path.join(root, fname)
                if not src or not os.path.isfile(src):
                    continue
                try:
                    rel = os.path.relpath(src, extract_dir).replace("\\", "/")
                except (ValueError, TypeError):
                    continue
                if ".." in rel:
                    continue
                dest = os.path.join(base, rel)
                try:
                    os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
                    shutil.copy2(src, dest)
                except Exception:
                    pass

        return True, "تمت استعادة النسخة الاحتياطية بنجاح. يُفضّل إعادة تشغيل التطبيق ثم تسجيل الدخول."
    except zipfile.BadZipFile:
        return False, "الملف ليس أرشيف ZIP صالحاً"
    except Exception as e:
        return False, f"فشل الاستعادة: {e}"
    finally:
        shutil.rmtree(extract_dir, ignore_errors=True)
        try:
            os.unlink(tmp_zip.name)
        except Exception:
            pass


def _parse_revenue_header_map(header_vals):
    """تحليل صف رأس النموذج المعتمد إلى فهارس الأعمدة."""
    aliases = {
        "date": ("التاريخ",),
        "invoice": ("رقم الفاتورة",),
        "total": ("قيمة الفاتورة", "الإجمالي"),
        "paid": ("المدفوع", "المقدم"),
        "remaining": ("المتبقي",),
        "receipt": ("سند القبض",),
        "customer": ("اسم العميل", "العميل"),
        "payment_method": ("طريقة الدفع",),
        "notes": ("ملاحظات",),
    }
    hdr = {}
    for i, raw in enumerate(header_vals):
        h = str(raw or "").strip()
        if not h:
            continue
        for key, names in aliases.items():
            if h in names:
                hdr[key] = i
    if "date" not in hdr or "invoice" not in hdr:
        return None
    return hdr


def _find_revenue_header_in_rows(rows, safe_str):
    for idx, row in enumerate(rows[:10]):
        vals = [safe_str(c) for c in row]
        if "التاريخ" in vals and "رقم الفاتورة" in vals:
            return idx, _parse_revenue_header_map(vals)
    return None, None


def _invoice_cells_from_row(row, hdr):
    def cell(key, default=None):
        i = hdr.get(key)
        if i is None or len(row) <= i:
            return default
        return row[i]

    return (
        cell("date"),
        cell("invoice"),
        cell("customer", ""),
        cell("total", 0),
        cell("paid", 0),
        cell("remaining", 0),
        cell("receipt", ""),
        cell("payment_method", "") or "",
        cell("notes", "") or "",
    )


def import_invoices_from_xlsx(filepath, override_month=None):
    """
    استيراد فواتير الإيرادات من revenues_template.xlsx المعتمد فقط.
    البنية: صف 1 عنوان | صف 2 رأس (التاريخ، رقم الفاتورة، قيمة الفاتورة، …) | صف 3+ بيانات.
    الفواتير الموجودة مسبقاً تُحدَّث (المدفوع، المتبقي، طريقة الدفع، …) بدلاً من تجاهلها.
    """
    if not os.path.isfile(filepath):
        return 0, 0, 0, "الملف غير موجود"
    try:
        import openpyxl
        wb = openpyxl.load_workbook(filepath, data_only=True)
    except Exception as e:
        return 0, 0, 0, f"خطأ في فتح الملف: {e}"

    conn = sqlite3.connect(DB_PATH)
    existing = set(row[0] for row in conn.execute("SELECT invoice_number FROM invoices").fetchall())
    conn.close()

    imported = 0
    updated = 0
    skipped = 0
    errors = []
    month_code = str(override_month or "").strip()[:7] or None

    def _safe_str(v):
        if v is None:
            return ""
        if isinstance(v, datetime):
            return v.strftime("%d/%m/%Y")
        return str(v).strip()

    def _process_row(date_val, inv_no, customer_val, total_val, down_val, remaining_val, receipt_val, payment_method, notes, sheet_month):
        nonlocal imported, updated, skipped
        inv_no = _safe_str(inv_no)
        if not inv_no or inv_no in ("رقم الفاتورة", "الإجمالي", "المجموع"):
            return
        date_str = _invoice_date_from_cell(date_val, sheet_month)
        total_f, down_f, remaining_f = _invoice_row_amounts(total_val, down_val, remaining_val)
        customer_s = _safe_str(customer_val) or ""
        receipt_s = _safe_str(receipt_val) or ""
        pm_s = payment_method or ""
        notes_s = notes or ""
        if inv_no in existing:
            if update_invoice_by_number(
                inv_no, date_str, customer_s, total_f, down_f, remaining_f, receipt_s, pm_s, notes_s
            ):
                updated += 1
            else:
                skipped += 1
            return
        insert_invoice(
            date_str, inv_no, customer_s, total_f, down_f, remaining_f,
            receipt_s, pm_s, notes_s,
        )
        existing.add(inv_no)
        imported += 1

    for sheet_name in wb.sheetnames:
        rows = list(wb[sheet_name].iter_rows(values_only=True))
        if not rows:
            continue

        sheet_month = month_code
        if not sheet_month:
            title = _safe_str(rows[0][0]) if rows[0] else ""
            m = re.search(r"(\d{4}-\d{2})", title) or re.search(r"(\d{4}-\d{2})", sheet_name)
            if m:
                sheet_month = m.group(1)
        if not sheet_month:
            for row in rows[:4]:
                for cell in row:
                    if cell and str(cell).startswith("الشهر (للاستيراد):"):
                        sheet_month = str(cell).split(":", 1)[1].strip()[:7]
                        break
                if sheet_month:
                    break
        if not sheet_month:
            errors.append(f'شيت "{sheet_name}": يجب اختيار شهر الفواتير عند الاستيراد')
            continue

        header_idx, hdr = _find_revenue_header_in_rows(rows, _safe_str)
        if not hdr:
            return 0, 0, 0, (
                "الملف لا يطابق نموذج revenues_template.xlsx المعتمد. "
                "حمّل النموذج من صفحة الاستيراد واملأ البيانات من الصف 3 فما فوق."
            )

        for row in rows[header_idx + 1:]:
            if not row or not any(c is not None and str(c).strip() for c in row):
                continue
            inv_idx = hdr["invoice"]
            if len(row) <= inv_idx or not row[inv_idx]:
                continue
            try:
                cells = _invoice_cells_from_row(row, hdr)
                _process_row(*cells, sheet_month)
            except Exception as e:
                skipped += 1
                errors.append(f"صف ({_safe_str(row[inv_idx])}): {e}")

    err_msg = "; ".join(errors[:5]) if errors else ""
    return imported, updated, skipped, err_msg


def _date_to_excel_serial(date_str):
    """تحويل YYYY-MM-DD إلى رقم تسلسلي لـ Excel"""
    try:
        d = datetime.strptime(date_str[:10], "%Y-%m-%d")
        base = datetime(1899, 12, 30)
        return int((d - base).total_seconds() // 86400)
    except (ValueError, TypeError):
        return 0


def export_invoices_to_xlsx(filepath, month_filter=None):
    """تصدير الفواتير إلى revenues_template.xlsx المعتمد (صف 3+ بيانات)."""
    if not filepath or not str(filepath).strip():
        return False, "مسار الملف فارغ"
    try:
        conn = sqlite3.connect(DB_PATH)
        m = str(month_filter or "").strip()
        if m:
            rows = conn.execute(
                f"""SELECT date, invoice_number, customer_name, total_amount, down_payment,
                remaining, receipt_number FROM invoices
                WHERE substr(date, 1, 7) = ? AND {_INVOICE_ACTIVE_SQL}
                ORDER BY {INVOICES_ORDER_BY}""",
                (m,),
            ).fetchall()
        else:
            rows = conn.execute(
                f"""SELECT date, invoice_number, customer_name, total_amount, down_payment,
                remaining, receipt_number FROM invoices
                WHERE {_INVOICE_ACTIVE_SQL} ORDER BY {INVOICES_ORDER_BY}"""
            ).fetchall()
        conn.close()

        wb = build_revenues_template_workbook()
        ws = wb.active
        if m:
            ws.cell(row=1, column=1, value=f"تقرير الإيرادات - {_month_to_arabic(m)}")
        if ws.max_row >= REVENUE_TEMPLATE_DATA_START_ROW:
            ws.delete_rows(REVENUE_TEMPLATE_DATA_START_ROW, ws.max_row - REVENUE_TEMPLATE_DATA_START_ROW + 1)

        for i, r in enumerate(rows):
            row_num = REVENUE_TEMPLATE_DATA_START_ROW + i
            date_val = None
            if r[0]:
                try:
                    date_val = datetime.strptime(str(r[0]).strip()[:10], "%Y-%m-%d").date()
                except Exception:
                    date_val = str(r[0])[:10]
            ws.cell(row=row_num, column=1, value=date_val)
            ws.cell(row=row_num, column=2, value=str(r[1] or ""))
            ws.cell(row=row_num, column=3, value=float(r[3] or 0))
            ws.cell(row=row_num, column=4, value=float(r[4] or 0))
            ws.cell(row=row_num, column=5, value=float(r[5] or 0))
            ws.cell(row=row_num, column=6, value=str(r[6] or ""))
            ws.cell(row=row_num, column=7, value=str(r[2] or ""))
            if hasattr(date_val, "year"):
                ws.cell(row=row_num, column=1).number_format = "DD/MM/YYYY"

        fd, tmp = tempfile.mkstemp(suffix=".xlsx", dir=os.path.dirname(filepath) or ".")
        try:
            os.close(fd)
            wb.save(tmp)
            shutil.move(tmp, filepath)
        except (PermissionError, OSError):
            if os.path.exists(tmp):
                try:
                    os.unlink(tmp)
                except Exception:
                    pass
            return False, "الملف مفتوح أو غير متاح للكتابة. أغلق Excel ثم حاول مرة أخرى."
        return True, ""
    except Exception as e:
        return False, str(e)


def sync_invoices_with_xlsx(filepath, override_month=None):
    """مزامنة ثنائية: استيراد من Excel ثم تصدير إليه"""
    imp, _upd, sk, err = import_invoices_from_xlsx(filepath, override_month=override_month)
    if err:
        return imp, sk, err
    ok, export_err = export_invoices_to_xlsx(filepath)
    if not ok and export_err:
        return imp, sk, "استيراد OK، تصدير فشل: " + export_err
    return imp, sk, ""


def import_bank_sub_from_xlsx(filepath, replace_all=False):
    """استيراد حركات الحساب الفرعي من Excel.
    replace_all=True: مسح الجدول أولاً ثم استيراد من الملف (الملف يصبح المصدر الوحيد)."""
    if not os.path.isfile(filepath):
        return 0, 0, "الملف غير موجود"
    try:
        conn = sqlite3.connect(DB_PATH)
        if replace_all:
            conn.execute("DELETE FROM bank_sub_movements")
            conn.commit()
            existing_rows = {}  # key -> count
        else:
            existing_rows = {}  # key -> count (لدعم الحركات المتشابهة المتعددة)
            for row in conn.execute("""SELECT date, movement_type, amount, receipt_number, description FROM bank_sub_movements""").fetchall():
                key = (str(row[0] or ""), str(row[1] or ""), float(row[2] or 0), str(row[3] or ""), str(row[4] or ""))
                existing_rows[key] = existing_rows.get(key, 0) + 1
        conn.close()

        with zipfile.ZipFile(filepath, 'r') as z:
            sheet_xml = z.read('xl/worksheets/sheet1.xml')
            shared_strings = _read_shared_strings(z)

        ns = {'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

        def get_cell_val(cell_elem):
            t = cell_elem.get('t', '')
            v_el = cell_elem.find('main:v', ns)
            v = v_el.text if v_el is not None else ''
            if t == 's':
                try:
                    idx = int(float(str(v)))
                    return shared_strings[idx] if 0 <= idx < len(shared_strings) else ''
                except (ValueError, TypeError):
                    return ''
            if t == 'inlineStr':
                is_el = cell_elem.find('main:is', ns)
                if is_el is not None:
                    t_el = is_el.find('main:t', ns)
                    if t_el is not None and t_el.text:
                        return t_el.text
                    return ''.join(r.find('main:t', ns).text or '' for r in is_el.findall('main:r', ns))
                return ''
            return str(v).strip() if v else ''

        root = ET.fromstring(sheet_xml)
        sheet_data = root.find('.//main:sheetData', ns)
        if sheet_data is None:
            return 0, 0, "تعذر قراءة البيانات"

        def row_num(elem):
            m = re.search(r'\d+', elem.get('r', '') or '')
            return int(m.group()) if m else 0

        # --- تحديد تنسيق الملف ---
        header_row_vals_sub = {}
        for row in sheet_data:
            r_ref = row.get('r', '')
            r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
            if r_num == 3:
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    header_row_vals_sub[col] = get_cell_val(c)
                break
        is_accountant_fmt = (
            any('بيان' in str(header_row_vals_sub.get(c, '')) for c in ['A', 'B']) and
            any('تاريخ' in str(header_row_vals_sub.get(c, '')) for c in ['B', 'C'])
        ) or (
            bool(header_row_vals_sub.get('A', '')) and
            'سند' not in str(header_row_vals_sub.get('B', '')) and
            'مورد' not in str(header_row_vals_sub.get('C', ''))
        )

        def _extract_receipt_sub(bayan):
            if not bayan: return ''
            bayan = str(bayan).strip()
            m = re.search(r'سند\s+قبض\s+\d+\s+ف\s+(\d+)', bayan)
            if m: return m.group(1)
            m = re.search(r'سند\s+صرف\s*\(?\s*(\d+)', bayan)
            if m: return m.group(1)
            m = re.search(r'فيزا\s+سند\s+صرف\s*\(?\s*(\d+)', bayan)
            if m: return m.group(1)
            m = re.match(r'^(\d+)\s', bayan)
            if m: return m.group(1)
            return ''

        def _extract_supplier_sub(bayan):
            if not bayan: return ''
            m = re.search(r'\(([^)]+)\)', str(bayan))
            return m.group(1).strip() if m else ''

        def _parse_date_sub(date_val):
            if hasattr(date_val, 'strftime'):
                return date_val.strftime('%Y-%m-%d') if date_val else datetime.now().strftime('%Y-%m-%d')
            date_val_s = str(date_val or '').strip()
            if date_val_s and re.match(r'^\d{4}-\d{2}-\d{2}$', date_val_s):
                return date_val_s
            if date_val_s and re.match(r'^\d{2}/\d{2}/\d{4}$', date_val_s):
                parts = date_val_s.split('/')
                return f'{parts[2]}-{parts[1]}-{parts[0]}'
            if date_val and str(date_val).replace('.', '').replace('-', '').isdigit():
                try:
                    n = float(date_val)
                    return _excel_serial_to_date(date_val) if 1 <= n <= 300000 else (date_val_s or datetime.now().strftime('%Y-%m-%d'))
                except (ValueError, TypeError):
                    pass
            return date_val_s or datetime.now().strftime('%Y-%m-%d')

        imported, skipped = 0, 0
        first_row_opening_stored = False
        incoming_rows_count = {}  # عداد الحركات الواردة من Excel لكل مفتاح

        if is_accountant_fmt:
            # تنسيق المحاسب: A=البيان، B=التاريخ، C=دائن، D=مدين، E=رصيد
            col_map = {'A': 0, 'B': 1, 'C': 2, 'D': 3, 'E': 4}
            for row in sorted(sheet_data, key=row_num):
                r_ref = row.get('r', '')
                r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
                if r_num < 4:
                    continue
                vals = [''] * 5
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    if col in col_map:
                        vals[col_map[col]] = get_cell_val(c)
                bayan_val, date_val, credit_val, debit_val, balance_val = vals
                date_str = _parse_date_sub(date_val)
                try:
                    credit_f = float(str(credit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    credit_f = 0
                try:
                    debit_f = float(str(debit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    debit_f = 0
                if credit_f <= 0 and debit_f <= 0:
                    continue
                movement_type = 'حركات دائنة' if credit_f > 0 else 'حركات مدينة'
                amount = credit_f if credit_f > 0 else debit_f
                if replace_all and not first_row_opening_stored:
                    try:
                        bal_after_v = float(str(balance_val or '').replace(',', '.') or 0)
                        opening = bal_after_v - debit_f + credit_f
                        conn2 = sqlite3.connect(DB_PATH)
                        conn2.execute("INSERT OR REPLACE INTO bank_sub_settings (key, value) VALUES ('opening_balance', ?)", (str(opening),))
                        conn2.commit()
                        conn2.close()
                    except (ValueError, TypeError):
                        pass
                    first_row_opening_stored = True
                receipt_str = _extract_receipt_sub(bayan_val)
                supplier_str = _extract_supplier_sub(bayan_val)
                desc_str = str(bayan_val or '').strip()
                try:
                    bal_after = float(str(balance_val or '').replace(',', '.')) if balance_val else None
                except (ValueError, TypeError):
                    bal_after = None
                key = _bank_movement_row_key(
                    date_str, movement_type, amount, receipt_str, desc_str, supplier_str, "", bal_after
                )
                incoming_count = incoming_rows_count.get(key, 0) + 1
                incoming_rows_count[key] = incoming_count
                if existing_rows.get(key, 0) >= incoming_count:
                    skipped += 1
                    continue
                insert_bank_movement('bank_sub_movements', movement_type, amount, date_str, '', supplier_str, receipt_str, desc_str, balance_after=bal_after)
                imported += 1
        else:
            # التنسيق القديم: B=السند، C=المورد، D=البيان، E=التاريخ، F=دائن، G=مدين، H=رصيد
            col_map = {'B': 0, 'C': 1, 'D': 2, 'E': 3, 'F': 4, 'G': 5, 'H': 6}
            for row in sorted(sheet_data, key=row_num):
                r_ref = row.get('r', '')
                r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
                if r_num < 3:
                    continue
                vals = [''] * 7
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    if col in col_map:
                        vals[col_map[col]] = get_cell_val(c)
                receipt_val, supplier_val, desc_val, date_val, credit_val, debit_val, balance_val = vals[0], vals[1], vals[2], vals[3], vals[4], vals[5], vals[6]
                credit_f = float(credit_val or 0)
                debit_f = float(debit_val or 0)
                if credit_f <= 0 and debit_f <= 0:
                    continue
                movement_type = 'حركات دائنة' if credit_f > 0 else 'حركات مدينة'
                amount = credit_f if credit_f > 0 else debit_f
                if replace_all and not first_row_opening_stored:
                    try:
                        bal_after_v = float(str(balance_val or '').replace(',', '.')) if balance_val else 0
                        opening = bal_after_v - debit_f + credit_f
                        conn2 = sqlite3.connect(DB_PATH)
                        conn2.execute("INSERT OR REPLACE INTO bank_sub_settings (key, value) VALUES ('opening_balance', ?)", (str(opening),))
                        conn2.commit()
                        conn2.close()
                    except (ValueError, TypeError):
                        pass
                    first_row_opening_stored = True
                date_str = _parse_date_sub(date_val)
                receipt_str = str(receipt_val or '').strip()
                supplier_str = (supplier_val or '').strip()
                desc_str = str(desc_val or '').strip()
                try:
                    bal_after = float(str(balance_val or '').replace(',', '.')) if balance_val else None
                except (ValueError, TypeError):
                    bal_after = None
                key = _bank_movement_row_key(
                    date_str, movement_type, amount, receipt_str, desc_str, supplier_str, "", bal_after
                )
                incoming_count = incoming_rows_count.get(key, 0) + 1
                incoming_rows_count[key] = incoming_count
                if existing_rows.get(key, 0) >= incoming_count:
                    skipped += 1
                    continue
                insert_bank_movement('bank_sub_movements', movement_type, amount, date_str, '', supplier_str, receipt_str, desc_str, balance_after=bal_after)
                imported += 1

        return imported, skipped, ""
    except zipfile.BadZipFile:
        return 0, 0, "الملف ليس بصيغة Excel صالحة"
    except Exception as e:
        return 0, 0, str(e)



def import_both_banks_from_xlsx(filepath, replace_all=False):
    """استيراد كلا البنكين من ملف المحاسب الأصلي:
    البنك الفرعي (أعمدة A-E) والبنك الرئيسي (أعمدة H-L) في نفس الورقة.
    replace_all=True: مسح الجدولين أولاً ثم استيراد من الملف."""
    if not os.path.isfile(filepath):
        return 0, 0, 0, 0, "الملف غير موجود"
    try:
        import openpyxl as _oxl
        wb = _oxl.load_workbook(filepath, data_only=True)
        ws = wb.active

        def _parse_date(val):
            if val is None: return datetime.now().strftime('%Y-%m-%d')
            if hasattr(val, 'strftime'): return val.strftime('%Y-%m-%d')
            s = str(val).strip()
            if re.match(r'^\d{4}-\d{2}-\d{2}$', s): return s
            if re.match(r'^\d{2}/\d{2}/\d{4}$', s):
                p = s.split('/')
                return f'{p[2]}-{p[1]}-{p[0]}'
            try:
                n = float(s)
                if 1 <= n <= 300000:
                    return _excel_serial_to_date(n)
            except (ValueError, TypeError):
                pass
            return s or datetime.now().strftime('%Y-%m-%d')

        def _receipt(bayan):
            if not bayan: return ''
            b = str(bayan).strip()
            m = re.search(r'سند\s+قبض\s+\d+\s+ف\s+(\d+)', b)
            if m: return m.group(1)
            m = re.search(r'سند\s+صرف\s*\(?\s*(\d+)', b)
            if m: return m.group(1)
            m = re.search(r'فيزا\s+سند\s+صرف\s*\(?\s*(\d+)', b)
            if m: return m.group(1)
            m = re.match(r'^(\d+)\s', b)
            if m: return m.group(1)
            return ''

        def _supplier(bayan):
            if not bayan: return ''
            m = re.search(r'\(([^)]+)\)', str(bayan))
            return m.group(1).strip() if m else ''

        conn = sqlite3.connect(DB_PATH)
        if replace_all:
            conn.execute("DELETE FROM bank_sub_movements")
            conn.execute("DELETE FROM bank_main_movements")
            conn.commit()
            existing_sub = set()
            existing_main = set()
        else:
            existing_sub = set()
            for row in conn.execute("SELECT date, movement_type, amount, receipt_number FROM bank_sub_movements").fetchall():
                existing_sub.add((str(row[0] or ''), str(row[1] or ''), float(row[2] or 0), str(row[3] or '')))
            existing_main = set()
            for row in conn.execute("SELECT date, movement_type, amount, receipt_number FROM bank_main_movements").fetchall():
                existing_main.add((str(row[0] or ''), str(row[1] or ''), float(row[2] or 0), str(row[3] or '')))
        conn.close()

        sub_imp = sub_sk = main_imp = main_sk = 0
        first_sub_done = False

        for row in ws.iter_rows(min_row=4, values_only=True):
            bayan_s = row[0] if len(row) > 0 else None
            date_s  = row[1] if len(row) > 1 else None
            cred_s  = row[2] if len(row) > 2 else None
            deb_s   = row[3] if len(row) > 3 else None
            bal_s   = row[4] if len(row) > 4 else None
            try: cf = float(cred_s or 0)
            except (ValueError, TypeError): cf = 0
            try: df = float(deb_s or 0)
            except (ValueError, TypeError): df = 0
            if cf > 0 or df > 0:
                mv = 'حركات دائنة' if cf > 0 else 'حركات مدينة'
                amt = cf if cf > 0 else df
                ds = _parse_date(date_s)
                rc = _receipt(bayan_s)
                key = (ds, mv, amt, rc)
                if key not in existing_sub:
                    try: bal_v = float(str(bal_s or '').replace(',', '.')) if bal_s else None
                    except (ValueError, TypeError): bal_v = None
                    if not first_sub_done:
                        try:
                            op = (bal_v or 0) - df + cf
                            c2 = sqlite3.connect(DB_PATH)
                            c2.execute("INSERT OR REPLACE INTO bank_sub_settings (key, value) VALUES ('opening_balance', ?)", (str(op),))
                            c2.commit(); c2.close()
                        except Exception: pass
                        first_sub_done = True
                    insert_bank_movement('bank_sub_movements', mv, amt, ds, '', _supplier(bayan_s), rc, str(bayan_s or '').strip(), balance_after=bal_v)
                    existing_sub.add(key)
                    sub_imp += 1
                else:
                    sub_sk += 1

            bayan_m = row[7]  if len(row) > 7  else None
            date_m  = row[8]  if len(row) > 8  else None
            cred_m  = row[9]  if len(row) > 9  else None
            deb_m   = row[10] if len(row) > 10 else None
            bal_m   = row[11] if len(row) > 11 else None
            try: cfm = float(cred_m or 0)
            except (ValueError, TypeError): cfm = 0
            try: dfm = float(deb_m or 0)
            except (ValueError, TypeError): dfm = 0
            if cfm > 0 or dfm > 0:
                mv = 'حركات دائنة' if cfm > 0 else 'حركات مدينة'
                amt = cfm if cfm > 0 else dfm
                ds = _parse_date(date_m)
                rc = _receipt(bayan_m)
                key = (ds, mv, amt, rc)
                if key not in existing_main:
                    try: bal_v = float(str(bal_m or '').replace(',', '.')) if bal_m else None
                    except (ValueError, TypeError): bal_v = None
                    insert_bank_movement('bank_main_movements', mv, amt, ds, '', _supplier(bayan_m), rc, str(bayan_m or '').strip(), balance_after=bal_v)
                    existing_main.add(key)
                    main_imp += 1
                else:
                    main_sk += 1

        return sub_imp, sub_sk, main_imp, main_sk, ""
    except Exception as e:
        return 0, 0, 0, 0, str(e)


def export_bank_sub_to_xlsx(filepath):
    """تصدير حركات الحساب الفرعي من قاعدة البيانات إلى ملف Excel"""
    if not filepath or not str(filepath).strip():
        return False, "مسار الملف فارغ"
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("""SELECT date, movement_type, amount, invoice_number, customer_name, receipt_number, description, balance_after
            FROM bank_sub_movements ORDER BY date ASC, id ASC""").fetchall()
        conn.close()

        all_strings = ["السند", "المورد / المصدر", "البيان", "التاريخ", "حركات دائنة", "حركات مدينة", "الرصيد"]
        string_to_idx = {s: i for i, s in enumerate(all_strings)}

        def get_str_idx(s):
            s = str(s or "").strip()
            if s not in string_to_idx:
                string_to_idx[s] = len(all_strings)
                all_strings.append(s)
            return string_to_idx[s]

        for r in rows:
            get_str_idx(r[0])  # التاريخ كنص لضمان عرضه صحيح
            get_str_idx(r[4])
            get_str_idx(r[5])
            get_str_idx(_strip_sund_sarf_from_desc(r[6]) if r[6] else "")

        def esc_xml(t):
            return str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")

        shared_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="' + str(len(all_strings)) + '" uniqueCount="' + str(len(all_strings)) + '">'
        for s in all_strings:
            shared_xml += '<si><t>' + esc_xml(s) + '</t></si>'
        shared_xml += '</sst>'

        header_row = '<row r="2"><c r="B2" t="s"><v>0</v></c><c r="C2" t="s"><v>1</v></c><c r="D2" t="s"><v>2</v></c><c r="E2" t="s"><v>3</v></c><c r="F2" t="s"><v>4</v></c><c r="G2" t="s"><v>5</v></c><c r="H2" t="s"><v>6</v></c></row>'
        sheet_rows = header_row
        opening = get_bank_sub_opening_balance()
        if opening is not None:
            balance = opening
        else:
            balance = OPENING_BALANCE_BANK_SUB
        for i, r in enumerate(rows):
            rownum = 3 + i
            date_idx = get_str_idx(r[0] if r[0] else "")  # التاريخ كنص YYYY-MM-DD
            receipt_idx = get_str_idx(r[5] if r[5] else "")
            supplier_idx = get_str_idx(r[4] if r[4] else "")
            desc_idx = get_str_idx(_strip_sund_sarf_from_desc(r[6]) if r[6] else "")
            amt = float(r[2] or 0)
            bal_stored = r[7]  # balance_after من Excel
            if bal_stored is not None:
                try:
                    balance = float(bal_stored)
                except (ValueError, TypeError):
                    balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            else:
                balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            if (r[1] or "").strip() == "حركات مدينة":
                credit_val, debit_val = 0, amt
            else:
                credit_val, debit_val = amt, 0
            sheet_rows += f'<row r="{rownum}"><c r="B{rownum}" t="s"><v>{receipt_idx}</v></c><c r="C{rownum}" t="s"><v>{supplier_idx}</v></c><c r="D{rownum}" t="s"><v>{desc_idx}</v></c><c r="E{rownum}" t="s"><v>{date_idx}</v></c><c r="F{rownum}" t="n"><v>{credit_val}</v></c><c r="G{rownum}" t="n"><v>{debit_val}</v></c><c r="H{rownum}" t="n"><v>{balance:.6f}</v></c></row>'

        sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + sheet_rows + '</sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>'

        with zipfile.ZipFile(filepath, 'r') as z_in:
            other_files = {n: z_in.read(n) for n in z_in.namelist() if n not in ('xl/worksheets/sheet1.xml', 'xl/sharedStrings.xml', 'xl/calcChain.xml')}

        fd, tmp = tempfile.mkstemp(suffix='.xlsx', dir=os.path.dirname(filepath) or '.')
        try:
            os.close(fd)
            with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as z_out:
                for n, data in other_files.items():
                    z_out.writestr(n, data)
                z_out.writestr('xl/sharedStrings.xml', shared_xml.encode('utf-8'))
                z_out.writestr('xl/worksheets/sheet1.xml', sheet_xml.encode('utf-8'))
            shutil.move(tmp, filepath)
        except (PermissionError, OSError) as e:
            if os.path.exists(tmp):
                try:
                    os.unlink(tmp)
                except Exception:
                    pass
            return False, "الملف مفتوح أو غير متاح للكتابة. أغلق Excel ثم حاول مرة أخرى."
        return True, ""
    except Exception as e:
        return False, str(e)


def export_invoices_xlsx_bytes(month_filter, paid_filter=None):
    """تصدير فواتير المبيعات لشهر معين إلى bytes (ملف Excel للتحميل) - باستخدام openpyxl"""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side, numbers
        from openpyxl.utils import get_column_letter
        from datetime import datetime as _dt2

        conn = sqlite3.connect(DB_PATH)
        m = str(month_filter or "").strip()
        conditions, args = [], []
        if m and m != "all":
            conditions.append("substr(date, 1, 7) = ?")
            args.append(m)
        pf = _normalize_paid_filter(paid_filter)
        rem_sql = _invoice_effective_remaining_sql()
        if pf == "paid":
            conditions.append(f"({rem_sql}) <= 0")
        elif pf == "unpaid":
            conditions.append(f"({rem_sql}) > 0")
        conditions.append(_INVOICE_ACTIVE_SQL)
        where = " AND ".join(conditions) if conditions else "1=1"
        rows = conn.execute(
            f"""SELECT date, invoice_number, customer_name, total_amount, down_payment, remaining, receipt_number
                FROM invoices WHERE {where} ORDER BY {INVOICES_ORDER_BY}""",
            args,
        ).fetchall()
        conn.close()

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "الإيرادات"
        ws.sheet_view.rightToLeft = True

        # ألوان التصميم
        header_fill = PatternFill("solid", fgColor="1E3A5F")
        title_fill  = PatternFill("solid", fgColor="2D5A87")
        alt_fill    = PatternFill("solid", fgColor="EEF3F8")
        green_fill  = PatternFill("solid", fgColor="D4EDDA")
        red_fill    = PatternFill("solid", fgColor="F8D7DA")
        thin = Side(style="thin", color="CCCCCC")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)

        # عنوان التقرير
        ws.merge_cells("A1:G1")
        title_cell = ws["A1"]
        month_label = _month_to_arabic(m) if m and m != "all" else "جميع الفواتير"
        paid_suffix = ""
        if pf == "paid":
            paid_suffix = " - مدفوعة"
        elif pf == "unpaid":
            paid_suffix = " - غير مدفوعة"
        title_cell.value = f"تقرير الإيرادات - {month_label}{paid_suffix}"
        title_cell.font = Font(name="Arial", bold=True, size=16, color="FFFFFF")
        title_cell.fill = title_fill
        title_cell.alignment = Alignment(horizontal="center", vertical="center", readingOrder=2)
        ws.row_dimensions[1].height = 32

        # رأس الجدول
        headers = list(REVENUE_XLSX_HEADERS)
        col_widths = [14, 16, 14, 14, 14, 16, 24]
        for col_idx, (hdr, width) in enumerate(zip(headers, col_widths), start=1):
            cell = ws.cell(row=2, column=col_idx, value=hdr)
            cell.font = Font(name="Arial", bold=True, size=12, color="FFFFFF")
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center", vertical="center", readingOrder=2)
            cell.border = border
            ws.column_dimensions[get_column_letter(col_idx)].width = width
        ws.row_dimensions[2].height = 24

        # بيانات الفواتير
        date_fmt = "YYYY-MM-DD"
        num_fmt  = "#,##0.000"
        total_rev = 0.0
        total_paid = 0.0
        total_rem = 0.0
        for i, r in enumerate(rows):
            row_num = 3 + i
            fill = alt_fill if i % 2 == 0 else PatternFill("solid", fgColor="FFFFFF")

            # تاريخ
            date_val = None
            if r[0]:
                try:
                    date_val = _dt2.strptime(str(r[0]).strip()[:10], "%Y-%m-%d").date()
                except Exception:
                    date_val = str(r[0])[:10]
            c_date = ws.cell(row=row_num, column=1, value=date_val)
            if isinstance(date_val, __import__('datetime').date):
                c_date.number_format = date_fmt
            c_date.alignment = Alignment(horizontal="center", readingOrder=2)
            c_date.fill = fill
            c_date.border = border

            # رقم الفاتورة
            c_inv = ws.cell(row=row_num, column=2, value=str(r[1] or ""))
            c_inv.alignment = Alignment(horizontal="center", readingOrder=2)
            c_inv.fill = fill; c_inv.border = border

            # قيمة الفاتورة
            total_val = float(r[3] or 0)
            c_total = ws.cell(row=row_num, column=3, value=total_val)
            c_total.number_format = num_fmt
            c_total.alignment = Alignment(horizontal="center", readingOrder=2)
            c_total.fill = fill; c_total.border = border
            total_rev += total_val

            # المدفوع
            paid_val = float(r[4] or 0)
            c_paid = ws.cell(row=row_num, column=4, value=paid_val)
            c_paid.number_format = num_fmt
            c_paid.alignment = Alignment(horizontal="center", readingOrder=2)
            c_paid.fill = fill; c_paid.border = border
            total_paid += paid_val

            # المتبقي
            rem_val = float(r[5] or 0)
            c_rem = ws.cell(row=row_num, column=5, value=rem_val)
            c_rem.number_format = num_fmt
            c_rem.alignment = Alignment(horizontal="center", readingOrder=2)
            c_rem.fill = red_fill if rem_val > 0 else green_fill
            c_rem.border = border
            total_rem += rem_val

            # سند القبض
            c_rec = ws.cell(row=row_num, column=6, value=str(r[6] or ""))
            c_rec.alignment = Alignment(horizontal="center", readingOrder=2)
            c_rec.fill = fill; c_rec.border = border

            c_cust = ws.cell(row=row_num, column=7, value=str(r[2] or ""))
            c_cust.alignment = Alignment(horizontal="right", readingOrder=2)
            c_cust.fill = fill; c_cust.border = border

            ws.row_dimensions[row_num].height = 18

        # صف المجاميع
        sum_row = 3 + len(rows)
        summary_fill = PatternFill("solid", fgColor="1E3A5F")
        labels = ["المجموع", "", "", total_rev, total_paid, total_rem, "", ""]
        for col_idx, val in enumerate(labels, start=1):
            cell = ws.cell(row=sum_row, column=col_idx, value=val)
            cell.font = Font(name="Arial", bold=True, size=11, color="FFFFFF")
            cell.fill = summary_fill
            cell.border = border
            cell.alignment = Alignment(horizontal="center", readingOrder=2)
            if isinstance(val, float):
                cell.number_format = num_fmt
        ws.row_dimensions[sum_row].height = 22

        output = io.BytesIO()
        wb.save(output)
        return output.getvalue()
    except Exception as e:
        return None

def export_expenses_xlsx_bytes(month_filter, expense_type=None):
    """تصدير المصروفات لشهر معين إلى bytes (ملف Excel للتحميل)"""
    try:
        conn = sqlite3.connect(DB_PATH)
        m = str(month_filter or "").strip()
        conditions, args = [], []
        if m and m != "all":
            conditions.append("substr(date, 1, 7) = ?")
            args.append(m)
        if expense_type:
            conditions.append("COALESCE(expense_type,'') = ?")
            args.append(expense_type)
        where = " AND ".join(conditions) if conditions else "1=1"
        rows = conn.execute(f"""SELECT date, invoice_number, supplier_name, amount, expense_type
            FROM expenses WHERE {where} ORDER BY date ASC, id ASC""", args).fetchall()
        conn.close()

        all_strings = ["التاريخ", "رقم الفاتورة", "المورد", "المبلغ", "النوع"]
        string_to_idx = {s: i for i, s in enumerate(all_strings)}
        def get_str_idx(s):
            s = str(s or "").strip()
            if s not in string_to_idx:
                string_to_idx[s] = len(all_strings)
                all_strings.append(s)
            return string_to_idx[s]
        for r in rows:
            get_str_idx(r[1] if r[1] else "")
            get_str_idx(r[2] if r[2] else "")
            get_str_idx(r[4] if r[4] else "")
        def esc_xml(t):
            return str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
        shared_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="' + str(len(all_strings)) + '" uniqueCount="' + str(len(all_strings)) + '">'
        for s in all_strings:
            shared_xml += '<si><t>' + esc_xml(s) + '</t></si>'
        shared_xml += '</sst>'
        header_row = '<row r="2"><c r="B2" t="s"><v>0</v></c><c r="C2" t="s"><v>1</v></c><c r="D2" t="s"><v>2</v></c><c r="E2" t="s"><v>3</v></c><c r="F2" t="s"><v>4</v></c></row>'
        sheet_rows = header_row
        for i, r in enumerate(rows):
            rownum = 3 + i
            date_ser = _date_to_excel_serial(r[0]) if r[0] else ""
            inv_idx = get_str_idx(r[1] if r[1] else "")
            supplier_idx = get_str_idx(r[2] if r[2] else "")
            amount = float(r[3] or 0)
            type_idx = get_str_idx(r[4] if r[4] else "")
            sheet_rows += f'<row r="{rownum}"><c r="B{rownum}" t="n"><v>{date_ser}</v></c><c r="C{rownum}" t="s"><v>{inv_idx}</v></c><c r="D{rownum}" t="s"><v>{supplier_idx}</v></c><c r="E{rownum}" t="n"><v>{amount}</v></c><c r="F{rownum}" t="s"><v>{type_idx}</v></c></row>'
        sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + sheet_rows + '</sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>'
        template_path = XLSX_PATH if os.path.isfile(XLSX_PATH) else None
        if template_path:
            with zipfile.ZipFile(template_path, 'r') as z_in:
                other_files = {n: z_in.read(n) for n in z_in.namelist() if n not in ('xl/worksheets/sheet1.xml', 'xl/sharedStrings.xml', 'xl/calcChain.xml')}
        else:
            other_files = {}
        output = io.BytesIO()
        with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as z_out:
            for n, data in other_files.items():
                z_out.writestr(n, data)
            z_out.writestr('xl/sharedStrings.xml', shared_xml.encode('utf-8'))
            z_out.writestr('xl/worksheets/sheet1.xml', sheet_xml.encode('utf-8'))
        return output.getvalue()
    except Exception as e:
        return None

def fetch_expense_months(expense_type=None):
    """استرجاع الشهور التي تحتوي على مصروفات - [(year_month, arabic_label), ...]"""
    conn = sqlite3.connect(DB_PATH)
    if expense_type:
        rows = conn.execute(
            """SELECT DISTINCT substr(date, 1, 7) FROM expenses
               WHERE COALESCE(expense_type,'') = ? AND date IS NOT NULL AND length(date) >= 7
               ORDER BY date DESC""",
            (expense_type,),
        ).fetchall()
    else:
        rows = conn.execute(
            """SELECT DISTINCT substr(date, 1, 7) FROM expenses
               WHERE date IS NOT NULL AND length(date) >= 7 ORDER BY date DESC"""
        ).fetchall()
    conn.close()
    result = []
    for (ym,) in rows:
        if not ym:
            continue
        parts = ym.split("-")
        if len(parts) >= 2:
            try:
                year, month = int(parts[0]), int(parts[1])
                if 1 <= month <= 12:
                    label = f"{ARABIC_MONTHS[month - 1]} {year}"
                    result.append((ym, label))
            except (ValueError, IndexError):
                pass
    return result

def fetch_bank_main_months():
    """استرجاع الشهور التي تحتوي على حركات البنك الرئيسي - [(year_month, arabic_label), ...]"""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("""SELECT DISTINCT substr(date, 1, 7) FROM bank_main_movements
        WHERE date IS NOT NULL AND length(date) >= 7 ORDER BY date DESC""").fetchall()
    conn.close()
    result = []
    for (ym,) in rows:
        if not ym:
            continue
        parts = ym.split("-")
        if len(parts) >= 2:
            try:
                year, month = int(parts[0]), int(parts[1])
                if 1 <= month <= 12:
                    label = f"{ARABIC_MONTHS[month - 1]} {year}"
                    result.append((ym, label))
            except (ValueError, IndexError):
                pass
    return result


def _sanitize_month_param(value):
    """تنظيف YYYY-MM إذا دُمجت معاملات query بالخطأ في قيمة month."""
    if not value:
        return ""
    s = str(value).strip()
    for sep in ("?", "&", "#"):
        if sep in s:
            s = s.split(sep, 1)[0].strip()
    return s


def _ym_from_month_year_fields(form_data, month_key, year_key, legacy_key=None):
    """دمج حقول الشهر والسنة إلى YYYY-MM."""
    if legacy_key:
        legacy = _sanitize_month_param((form_data.get(legacy_key) or [""])[0])
        if legacy:
            return legacy
    m = (form_data.get(month_key) or [""])[0].strip()
    y = (form_data.get(year_key) or [""])[0].strip()
    if not m or not y:
        return ""
    try:
        mi, yi = int(m), int(y)
        if 1 <= mi <= 12 and 2000 <= yi <= 2100:
            return f"{yi}-{mi:02d}"
    except (ValueError, TypeError):
        pass
    return ""


def _import_year_values_from_ym_list(ym_pairs):
    """سنوات من قوائم (YYYY-MM, label)."""
    years = set(range(2024, 2028))
    for ym, _ in ym_pairs:
        if ym and len(str(ym)) >= 4:
            try:
                years.add(int(str(ym)[:4]))
            except ValueError:
                pass
    return sorted(years, reverse=True)


def _import_month_year_selects_html(month_key, year_key, years, hint="", bg="#f9f9f9", required=False):
    """قائمتان: الشهر والسنة."""
    req = " required" if required else ""
    month_opts = ['<option value="">–– الشهر ––</option>']
    for i in range(1, 13):
        month_opts.append(f'<option value="{i:02d}">{ARABIC_MONTHS[i - 1]}</option>')
    year_opts = ['<option value="">–– السنة ––</option>']
    for y in years:
        year_opts.append(f'<option value="{y}">{y}</option>')
    hint_html = f'<p style="font-size:12px;color:#888;margin:6px 0 0;">{hint}</p>' if hint else ""
    sel_style = f"background:{bg};" if bg != "#f9f9f9" else ""
    return (
        f'<div class="import-month-year-grid">'
        f'<div class="import-month-year-field">'
        f'<label class="import-month-year-label">الشهر</label>'
        f'<select name="{month_key}" class="import-month-year-select" style="{sel_style}"{req}>'
        + "\n".join(month_opts)
        + f'</select></div>'
        f'<div class="import-month-year-field">'
        f'<label class="import-month-year-label">السنة</label>'
        f'<select name="{year_key}" class="import-month-year-select" style="{sel_style}"{req}>'
        + "\n".join(year_opts)
        + f"</select></div></div>{hint_html}"
    )


