def _salary_import_month_year_selects_html():
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        "SELECT DISTINCT month FROM salaries WHERE month IS NOT NULL AND month != '' ORDER BY month DESC"
    ).fetchall()
    conn.close()
    ym_pairs = []
    for (m,) in rows:
        nm = normalize_salary_month(m) or m
        if nm and len(str(nm)) >= 7:
            parts = str(nm).split("-")
            if len(parts) >= 2:
                try:
                    yi, mi = int(parts[0]), int(parts[1])
                    ym_pairs.append((nm, f"{ARABIC_MONTHS[mi - 1]} {yi}"))
                except (ValueError, IndexError):
                    pass
    years = _import_year_values_from_ym_list(ym_pairs)
    return _import_month_year_selects_html(
        "salary_import_month",
        "salary_import_year",
        years,
        hint="سيُستخدم الشهر والسنة المختاران لتحديد شهر الرواتب في الملف.",
        bg="#fffaf5",
        required=True,
    )


def _bank_table_from_type(bank_type):
    """تحويل main/sub/credit أو اسم الجدول إلى اسم الجدول."""
    mapping = {
        "main": "bank_main_movements",
        "sub": "bank_sub_movements",
        "credit": "bank_credit_movements",
        "bank_main_movements": "bank_main_movements",
        "bank_sub_movements": "bank_sub_movements",
        "bank_credit_movements": "bank_credit_movements",
    }
    return mapping.get(bank_type, "bank_sub_movements")


def _bank_row_as_dict(row):
    if row is None:
        return None
    if isinstance(row, dict):
        return row
    return dict(row)


def _bank_fetch_row_dict(table_name, row_id):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute(f"SELECT * FROM {table_name} WHERE id = ?", (int(row_id),)).fetchone()
    conn.close()
    return _bank_row_as_dict(row)


def _bank_fetch_month_rows_dict(table_name, month_ym):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    if month_ym:
        rows = conn.execute(
            f"SELECT * FROM {table_name} WHERE substr(date, 1, 7) = ? ORDER BY id ASC",
            (month_ym,),
        ).fetchall()
    else:
        rows = conn.execute(f"SELECT * FROM {table_name} ORDER BY id ASC").fetchall()
    conn.close()
    return [_bank_row_as_dict(r) for r in rows]


def _bank_undo_save(table_name, month_ym, action_type, rows):
    import json
    if table_name not in ("bank_main_movements", "bank_sub_movements", "bank_credit_movements"):
        return
    month_key = (month_ym or "").strip()
    payload = json.dumps(rows, ensure_ascii=False)
    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        "DELETE FROM bank_movement_undo WHERE table_name = ? AND month_ym = ?",
        (table_name, month_key),
    )
    conn.execute(
        """INSERT INTO bank_movement_undo (table_name, month_ym, action_type, payload)
           VALUES (?, ?, ?, ?)""",
        (table_name, month_key, action_type, payload),
    )
    conn.commit()
    conn.close()


def _bank_undo_has(table_name, month_ym):
    conn = sqlite3.connect(DB_PATH)
    n = conn.execute(
        "SELECT 1 FROM bank_movement_undo WHERE table_name = ? AND month_ym = ? LIMIT 1",
        (table_name, (month_ym or "").strip()),
    ).fetchone()
    conn.close()
    return bool(n)


def _bank_restore_rows(conn, table_name, rows):
    for r in rows:
        if not r or "id" not in r:
            continue
        keys = list(r.keys())
        placeholders = ",".join("?" * len(keys))
        conn.execute(
            f"INSERT OR REPLACE INTO {table_name} ({','.join(keys)}) VALUES ({placeholders})",
            [r[k] for k in keys],
        )


def _bank_undo_restore(table_name, month_ym):
    import json
    month_key = (month_ym or "").strip()
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT action_type, payload FROM bank_movement_undo WHERE table_name = ? AND month_ym = ?",
        (table_name, month_key),
    ).fetchone()
    if not row:
        conn.close()
        return False, "لا توجد عملية للتراجع عنها"
    action_type, payload = row[0], json.loads(row[1])
    rows = payload if isinstance(payload, list) else [payload]
    try:
        if action_type == "insert":
            for r in rows:
                rid = int(r.get("id") or 0)
                if rid > 0:
                    conn.execute(f"DELETE FROM {table_name} WHERE id = ?", (rid,))
        else:
            _bank_restore_rows(conn, table_name, rows)
        conn.execute(
            "DELETE FROM bank_movement_undo WHERE table_name = ? AND month_ym = ?",
            (table_name, month_key),
        )
        conn.commit()
    except Exception:
        conn.close()
        return False, "تعذّر التراجع عن العملية"
    conn.close()
    if month_key and table_name in ("bank_main_movements", "bank_sub_movements"):
        opener = (
            get_bank_main_opening_balance
            if table_name == "bank_main_movements"
            else get_bank_sub_opening_balance
        )
        _recalc_bank_month_balances(table_name, month_key, opener)
    if table_name == "bank_sub_movements" and os.path.isfile(BANK_SUB_XLSX_PATH):
        export_bank_sub_to_xlsx(BANK_SUB_XLSX_PATH)
    labels = {
        "insert": "إضافة حركة",
        "delete_one": "حذف حركة",
        "clear_month": "مسح الشهر",
    }
    return True, f"تم التراجع عن {labels.get(action_type, 'العملية')} بنجاح"


