def _bank_clear_month_button_html(month_ym, bank_type, back_url):
    """زر مسح شهر محدد أعلى جدول البنك (يسار الشاشة في RTL)."""
    import json
    labels = {"main": "الحساب الرئيسي", "sub": "الحساب الفرعي", "credit": "بطاقة الائتمان"}
    acc = labels.get(bank_type, "الحساب")
    month_label = _month_to_arabic(month_ym)
    confirm_js = json.dumps(
        f"هل أنت متأكد من مسح بيانات {acc} لشهر {month_label}؟\n\nلا يمكن التراجع عن هذا الإجراء.",
        ensure_ascii=False,
    )
    # onsubmit بعلامات اقتباس مفردة — json.dumps يُنتج نصاً بمزدوجة؛ داخل مزدوجة HTML يُلغى confirm()
    return (
        f'<form method="POST" action="/clear-bank-month" style="margin:0;display:inline-block" '
        f"onsubmit='return confirm({confirm_js});'>"
        f'<input type="hidden" name="bank_type" value="{_esc(bank_type)}">'
        f'<input type="hidden" name="month" value="{_esc(month_ym)}">'
        f'<input type="hidden" name="back" value="{_esc(back_url)}">'
        f'<button type="submit" style="display:inline-flex;align-items:center;gap:6px;padding:7px 14px;'
        f"background:#dc3545;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:bold;"
        f'cursor:pointer;font-family:inherit;white-space:nowrap;">'
        f'<i class="fa-solid fa-trash-can"></i> مسح الشهر</button></form>'
    )


def _clear_bank_opening_balance_settings(table_name):
    """حذف الرصيد الافتتاحي المحفوظ للحساب الرئيسي أو الفرعي."""
    if table_name not in ("bank_main_movements", "bank_sub_movements"):
        return
    settings_table = "bank_main_settings" if table_name == "bank_main_movements" else "bank_sub_settings"
    conn = sqlite3.connect(DB_PATH)
    conn.execute(f"DELETE FROM {settings_table} WHERE key = 'opening_balance'")
    conn.commit()
    conn.close()


def _on_bank_month_cleared(table_name, cleared_month_ym=None):
    """بعد مسح شهر: إزالة الرصيد الافتتاحي إن لم تبقَ حركات أو إن مُسح أقدم شهر."""
    if table_name not in ("bank_main_movements", "bank_sub_movements"):
        return
    conn = sqlite3.connect(DB_PATH)
    n = conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
    if n == 0:
        conn.close()
        _clear_bank_opening_balance_settings(table_name)
        return
    if cleared_month_ym:
        min_row = conn.execute(
            f"""SELECT MIN(substr(date, 1, 7)) FROM {table_name}
                WHERE date IS NOT NULL AND length(date) >= 7"""
        ).fetchone()
        min_ym = (min_row[0] or "").strip() if min_row else ""
        if min_ym and cleared_month_ym <= min_ym:
            conn.close()
            _clear_bank_opening_balance_settings(table_name)
            return
    conn.close()


def _clear_bank_movements_for_month(table_name, month_ym):
    """مسح حركات شهر محدد قبل إعادة الاستيراد من Excel."""
    if not month_ym or month_ym == "all":
        return 0
    conn = sqlite3.connect(DB_PATH)
    cur = conn.execute(
        f"DELETE FROM {table_name} WHERE substr(date, 1, 7) = ?",
        (month_ym,),
    )
    deleted = cur.rowcount
    conn.commit()
    conn.close()
    _on_bank_month_cleared(table_name, month_ym)
    return deleted


def fetch_bank_credit_months():
    """استرجاع الشهور التي تحتوي على حركات بنك الائتمان - [(year_month, arabic_label), ...]"""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("""SELECT DISTINCT substr(date, 1, 7) FROM bank_credit_movements
        WHERE date IS NOT NULL AND length(date) >= 7 ORDER BY date DESC""").fetchall()
    conn.close()
    result = []
    for (ym,) in rows:
        if not ym:
            continue
        parts = ym.split("-")
        if len(parts) >= 2:
            try:
                year, month = int(parts[0]), int(parts[1])
                if 1 <= month <= 12:
                    label = f"{ARABIC_MONTHS[month - 1]} {year}"
                    result.append((ym, label))
            except (ValueError, IndexError):
                pass
    return result

def export_bank_credit_xlsx_bytes(month_filter):
    """تصدير حركات بنك الائتمان لشهر معين إلى bytes (ملف Excel للتحميل)"""
    try:
        conn = sqlite3.connect(DB_PATH)
        m = str(month_filter or "").strip()
        if m and m != "all":
            rows = conn.execute("""SELECT date, amount, supplier, description
                FROM bank_credit_movements WHERE substr(date, 1, 7) = ? ORDER BY date ASC, id ASC""",
                (m,)).fetchall()
        else:
            rows = conn.execute("""SELECT date, amount, supplier, description
                FROM bank_credit_movements ORDER BY date ASC, id ASC""").fetchall()
        conn.close()

        all_strings = ["التاريخ", "المبلغ", "المورد", "البيان"]
        string_to_idx = {s: i for i, s in enumerate(all_strings)}
        def get_str_idx(s):
            s = str(s or "").strip()
            if s not in string_to_idx:
                string_to_idx[s] = len(all_strings)
                all_strings.append(s)
            return string_to_idx[s]
        for r in rows:
            get_str_idx(r[0] if r[0] else "")
            get_str_idx(r[2] if r[2] else "")
            get_str_idx(r[3] if r[3] else "")
        def esc_xml(t):
            return str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
        shared_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="' + str(len(all_strings)) + '" uniqueCount="' + str(len(all_strings)) + '">'
        for s in all_strings:
            shared_xml += '<si><t>' + esc_xml(s) + '</t></si>'
        shared_xml += '</sst>'
        header_row = '<row r="2"><c r="B2" t="s"><v>0</v></c><c r="C2" t="s"><v>1</v></c><c r="D2" t="s"><v>2</v></c><c r="E2" t="s"><v>3</v></c></row>'
        sheet_rows = header_row
        for i, r in enumerate(rows):
            rownum = 3 + i
            date_ser = _date_to_excel_serial(r[0]) if r[0] else ""
            amount = float(r[1] or 0)
            supplier_idx = get_str_idx(r[2] if r[2] else "")
            desc_idx = get_str_idx(r[3] if r[3] else "")
            sheet_rows += f'<row r="{rownum}"><c r="B{rownum}" t="n"><v>{date_ser}</v></c><c r="C{rownum}" t="n"><v>{amount}</v></c><c r="D{rownum}" t="s"><v>{supplier_idx}</v></c><c r="E{rownum}" t="s"><v>{desc_idx}</v></c></row>'
        sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + sheet_rows + '</sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>'
        template_path = XLSX_PATH if os.path.isfile(XLSX_PATH) else None
        if template_path and os.path.isfile(template_path):
            with zipfile.ZipFile(template_path, 'r') as z_in:
                skip = ('xl/worksheets/sheet1.xml', 'xl/sharedStrings.xml', 'xl/calcChain.xml')
                other_files = {n: z_in.read(n) for n in z_in.namelist() if n not in skip}
        else:
            other_files = {}
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z_out:
            for n, data in other_files.items():
                z_out.writestr(n, data)
            z_out.writestr('xl/sharedStrings.xml', shared_xml.encode('utf-8'))
            z_out.writestr('xl/worksheets/sheet1.xml', sheet_xml.encode('utf-8'))
        return buf.getvalue()
    except Exception as e:
        return None

