def export_bank_sub_xlsx_bytes(month_filter):
    """تصدير حركات البنك الفرعي لشهر معين إلى bytes (ملف Excel للتحميل)"""
    try:
        conn = sqlite3.connect(DB_PATH)
        m = str(month_filter or "").strip()
        if m and m != "all":
            rows = conn.execute("""SELECT date, movement_type, amount, invoice_number, customer_name, receipt_number, description, balance_after
                FROM bank_sub_movements WHERE substr(date, 1, 7) = ? ORDER BY date ASC, id ASC""",
                (m,)).fetchall()
        else:
            rows = conn.execute("""SELECT date, movement_type, amount, invoice_number, customer_name, receipt_number, description, balance_after
                FROM bank_sub_movements ORDER BY date ASC, id ASC""").fetchall()
        conn.close()

        all_strings = ["السند", "المورد / المصدر", "البيان", "التاريخ", "حركات دائنة", "حركات مدينة", "الرصيد"]
        string_to_idx = {s: i for i, s in enumerate(all_strings)}
        def get_str_idx(s):
            s = str(s or "").strip()
            if s not in string_to_idx:
                string_to_idx[s] = len(all_strings)
                all_strings.append(s)
            return string_to_idx[s]
        for r in rows:
            get_str_idx(r[0])  # التاريخ كنص
            get_str_idx(r[4])
            get_str_idx(r[5])
            get_str_idx(_strip_sund_sarf_from_desc(r[6]) if r[6] else "")
        def esc_xml(t):
            return str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
        shared_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="' + str(len(all_strings)) + '" uniqueCount="' + str(len(all_strings)) + '">'
        for s in all_strings:
            shared_xml += '<si><t>' + esc_xml(s) + '</t></si>'
        shared_xml += '</sst>'
        header_row = '<row r="2"><c r="B2" t="s"><v>0</v></c><c r="C2" t="s"><v>1</v></c><c r="D2" t="s"><v>2</v></c><c r="E2" t="s"><v>3</v></c><c r="F2" t="s"><v>4</v></c><c r="G2" t="s"><v>5</v></c><c r="H2" t="s"><v>6</v></c></row>'
        sheet_rows = header_row
        opening = get_bank_sub_opening_balance()
        if opening is not None:
            balance = opening
        else:
            balance = OPENING_BALANCE_BANK_SUB
        for i, r in enumerate(rows):
            rownum = 3 + i
            date_idx = get_str_idx(r[0] if r[0] else "")
            receipt_idx = get_str_idx(r[5] if r[5] else "")
            supplier_idx = get_str_idx(r[4] if r[4] else "")
            desc_idx = get_str_idx(_strip_sund_sarf_from_desc(r[6]) if r[6] else "")
            amt = float(r[2] or 0)
            bal_stored = r[7] if len(r) > 7 else None  # balance_after من Excel
            if bal_stored is not None:
                try:
                    balance = float(bal_stored)
                except (ValueError, TypeError):
                    balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            else:
                balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            if (r[1] or "").strip() == "حركات مدينة":
                credit_val, debit_val = 0, amt
            else:
                credit_val, debit_val = amt, 0
            sheet_rows += f'<row r="{rownum}"><c r="B{rownum}" t="s"><v>{receipt_idx}</v></c><c r="C{rownum}" t="s"><v>{supplier_idx}</v></c><c r="D{rownum}" t="s"><v>{desc_idx}</v></c><c r="E{rownum}" t="s"><v>{date_idx}</v></c><c r="F{rownum}" t="n"><v>{credit_val}</v></c><c r="G{rownum}" t="n"><v>{debit_val}</v></c><c r="H{rownum}" t="n"><v>{balance:.6f}</v></c></row>'
        sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + sheet_rows + '</sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>'

        template_path = BANK_SUB_XLSX_PATH if os.path.isfile(BANK_SUB_XLSX_PATH) else XLSX_PATH
        with zipfile.ZipFile(template_path, 'r') as z_in:
            skip = ('xl/worksheets/sheet1.xml', 'xl/sharedStrings.xml', 'xl/calcChain.xml')
            other_files = {n: z_in.read(n) for n in z_in.namelist() if n not in skip}

        buf = io.BytesIO()
        with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z_out:
            for n, data in other_files.items():
                z_out.writestr(n, data)
            z_out.writestr('xl/sharedStrings.xml', shared_xml.encode('utf-8'))
            z_out.writestr('xl/worksheets/sheet1.xml', sheet_xml.encode('utf-8'))
        return buf.getvalue()
    except Exception as e:
        return None


def _parse_excel_balance_val(balance_val):
    """تحويل قيمة عمود الرصيد من Excel إلى عدد."""
    if balance_val is None or str(balance_val).strip() == "":
        return None
    try:
        return float(str(balance_val).replace(",", ".").strip())
    except (ValueError, TypeError):
        return None


def _bank_balance_value(val):
    """تحويل قيمة الرصيد إلى عدد (موجب أو سالب)."""
    try:
        return round(float(str(val).replace(",", ".")), 3)
    except (ValueError, TypeError):
        return 0.0


def _balance_before_movement(balance_after, movement_type, amount):
    """الرصيد قبل الحركة إذا كان balance_after من Excel بعدها."""
    bal = _bank_balance_value(balance_after)
    amt = float(amount or 0)
    if (movement_type or "").strip() == "حركات مدينة":
        return round(bal - amt, 3)
    return round(bal + amt, 3)


def _bank_balance_color(balance):
    """لون الرصيد: أسود (أحمر فقط إن كان سالباً)."""
    try:
        return "#c0392b" if float(balance) < -0.0005 else "#000000"
    except (ValueError, TypeError):
        return "#000000"


def _bank_movement_row_key(
    date_s,
    movement_type,
    amount,
    receipt_number,
    description="",
    customer_name="",
    invoice_number="",
    balance_after=None,
):
    """مفتاح الحركة — كل خانات الصف (لا دمج صفوف مختلفة في البيان أو المورد)."""
    bal_key = None
    if balance_after is not None and str(balance_after).strip() != "":
        try:
            bal_key = round(float(str(balance_after).replace(",", ".")), 3)
        except (ValueError, TypeError):
            bal_key = None
    return (
        str(date_s or "").strip(),
        str(movement_type or "").strip(),
        round(float(amount or 0), 3),
        str(receipt_number or "").strip(),
        str(description or "").strip(),
        str(customer_name or "").strip(),
        str(invoice_number or "").strip(),
        bal_key,
    )


def _apply_bank_movement_delta(balance, movement_type, amount):
    """تطبيق حركة على الرصيد الجاري (مدينة +، دائنة -)."""
    amt = float(amount or 0)
    b = _bank_balance_value(balance)
    if (movement_type or "").strip() == "حركات مدينة":
        return round(b + amt, 3)
    return round(b - amt, 3)


def _bank_display_balance_for_row(r, balance_running):
    """رصيد الصف تراكمياً من الرصيد السابق (لا يعتمد على balance_after من Excel)."""
    return _apply_bank_movement_delta(balance_running, r[2], r[3])


def _bank_balance_for_display_row(r, balance_running):
    """عرض الرصيد: من عمود Excel المحفوظ إن وُجد، وإلا تراكمياً."""
    if len(r) > 8 and r[8] is not None and str(r[8]).strip() != "":
        try:
            stored = _bank_balance_value(r[8])
            return stored, stored
        except (ValueError, TypeError):
            pass
    new_run = _bank_display_balance_for_row(r, balance_running)
    return new_run, new_run


def _bank_max_date_in_month(table_name, month_ym):
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        f"SELECT MAX(date) FROM {table_name} WHERE substr(date, 1, 7) = ?",
        (month_ym,),
    ).fetchone()
    conn.close()
    return (row[0] or "").strip()[:10] if row and row[0] else ""


def _bank_default_date_for_month(table_name, month_ym):
    """تاريخ افتراضي لحركة جديدة = آخر تاريخ في الشهر أو آخر يوم في الشهر."""
    max_d = _bank_max_date_in_month(table_name, month_ym)
    if max_d:
        return max_d
    y, m = int(month_ym[:4]), int(month_ym[5:7])
    return f"{month_ym}-{calendar.monthrange(y, m)[1]:02d}"


def _bank_date_for_new_movement(table_name, month_ym, user_date):
    """تاريخ الحركة الجديدة = آخر يوم فيه حركات بالشهر (لتظهر في أسفل الجدول)."""
    user_date = (user_date or "").strip()[:10]
    if month_ym and re.match(r"^\d{4}-\d{2}$", month_ym):
        if user_date[:7] == month_ym:
            return _bank_default_date_for_month(table_name, month_ym)
        return _bank_default_date_for_month(table_name, month_ym)
    return user_date or datetime.now().strftime("%Y-%m-%d")


def _month_ym_from_back(back_url):
    if not back_url or "month=" not in back_url:
        return ""
    try:
        q = urlparse(back_url).query
        return _sanitize_month_param(parse_qs(q).get("month", [""])[0])
    except Exception:
        return ""


def _recalc_bank_month_balances(table_name, month_ym, get_opening_balance):
    """إعادة حساب balance_after لكل حركات الشهر بعد إضافة أو حذف."""
    if not month_ym or table_name not in ("bank_main_movements", "bank_sub_movements"):
        return
    opening = _bank_opening_at_month_start(table_name, month_ym, get_opening_balance)
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        f"""SELECT id, movement_type, amount FROM {table_name}
            WHERE substr(date, 1, 7) = ? ORDER BY date ASC, id ASC""",
        (month_ym,),
    ).fetchall()
    balance = opening
    for row_id, mtype, amount in rows:
        balance = _apply_bank_movement_delta(balance, mtype, amount)
        conn.execute(
            f"UPDATE {table_name} SET balance_after = ? WHERE id = ?",
            (balance, row_id),
        )
    conn.commit()
    conn.close()


def dedupe_bank_movements_table(table_name, month_ym=None):
    """حذف التكرار الحرفي فقط (كل الخانات متطابقة) — لا يدمج صفوفاً مختلفة في البيان."""
    if table_name not in ("bank_main_movements", "bank_sub_movements"):
        return 0
    group_cols = (
        "date, movement_type, amount, COALESCE(receipt_number,''), COALESCE(description,''), "
        "COALESCE(customer_name,''), COALESCE(invoice_number,''), COALESCE(balance_after,'')"
    )
    conn = sqlite3.connect(DB_PATH)
    if month_ym:
        conn.execute(
            f"""DELETE FROM {table_name}
                WHERE substr(date, 1, 7) = ? AND id NOT IN (
                    SELECT MAX(id) FROM {table_name}
                    WHERE substr(date, 1, 7) = ?
                    GROUP BY {group_cols}
                )""",
            (month_ym, month_ym),
        )
    else:
        conn.execute(
            f"""DELETE FROM {table_name} WHERE id NOT IN (
                SELECT MAX(id) FROM {table_name}
                GROUP BY {group_cols}
            )"""
        )
    deleted = conn.total_changes
    conn.commit()
    conn.close()
    return deleted


def _bank_opening_from_excel_row(balance_val, credit_f, debit_f):
    """استخراج الرصيد الافتتاحي من صف Excel.
    إذا كان الصف بلا حركة (دائن/مدين = 0) يُؤخذ عمود الرصيد مباشرة.
    وإلا يُحسب الرصيد قبل الحركة: رصيد بعد الحركة + دائن − مدين (مثل التنسيق القديم)."""
    try:
        h_val = float(str(balance_val or "").replace(",", ".") or 0)
    except (ValueError, TypeError):
        h_val = 0.0
    if credit_f <= 0 and debit_f <= 0:
        return h_val, True
    return h_val + credit_f - debit_f, False


def _save_bank_opening_balance(table_name, ob_val):
    """حفظ الرصيد الافتتاحي في جدول إعدادات البنك المناسب."""
    if ob_val is None:
        return
    try:
        v = float(str(ob_val).replace(",", "."))
    except (ValueError, TypeError):
        return
    if abs(v) < 1e-9:
        return
    settings_table = "bank_main_settings" if table_name == "bank_main_movements" else "bank_sub_settings"
    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        f"INSERT OR REPLACE INTO {settings_table} (key, value) VALUES ('opening_balance', ?)",
        (str(v),),
    )
    conn.commit()
    conn.close()


def _opening_scan_update(state, balance_val, credit_f, debit_f, bayan_val=""):
    """تحديث أفضل رصيد افتتاحي من صف Excel (يتخطى الصفوف الفارغة)."""
    if state.get("saved"):
        return
    bayan = str(bayan_val or "")
    if "افتتاح" in bayan or ("رصيد" in bayan and credit_f <= 0 and debit_f <= 0):
        ob, _ = _bank_opening_from_excel_row(balance_val, credit_f, debit_f)
        if abs(ob) >= 1e-9:
            state["value"] = ob
            state["saved"] = True
            return
    ob, is_opening_only = _bank_opening_from_excel_row(balance_val, credit_f, debit_f)
    if is_opening_only:
        if abs(ob) >= 1e-9:
            state["value"] = ob
            state["saved"] = True


def _commit_opening_scan(table_name, state):
    if state.get("saved") and state.get("value") is not None:
        _save_bank_opening_balance(table_name, state["value"])


def _compute_bank_opening_before(table_name, before_date, get_opening_balance):
    """الرصيد عند بداية يوم before_date = الرصيد الافتتاحي المحفوظ + صافي الحركات قبل ذلك التاريخ."""
    base = get_opening_balance() if get_opening_balance() is not None else 0.0
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        f"""SELECT movement_type, amount FROM {table_name}
            WHERE date < ? ORDER BY date ASC, id ASC""",
        (before_date,),
    ).fetchall()
    conn.close()
    opening = base
    for mt, amt in rows:
        a = float(amt or 0)
        opening += a if (mt or "").strip() == "حركات مدينة" else -a
    return _bank_balance_value(opening)


def _compute_bank_opening_cumulative(table_name, before_month_ym, get_opening_balance):
    """تراكم المبالغ فقط (بدون قفزات balance_after من Excel)."""
    base = get_opening_balance() if get_opening_balance() is not None else 0.0
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        f"""SELECT movement_type, amount FROM {table_name}
            WHERE substr(date, 1, 7) < ? ORDER BY date ASC, id ASC""",
        (before_month_ym,),
    ).fetchall()
    conn.close()
    balance = base
    for mt, amt in rows:
        a = float(amt or 0)
        balance += a if (mt or "").strip() == "حركات مدينة" else -a
    return _bank_balance_value(balance)


def _post_bank_import_finalize(table_name, month_filter=None):
    """بعد الاستيراد: لا إعادة حساب الرصيد — تُحفظ قيم Excel كما في الملف."""
    return


def _prev_calendar_month_ym(month_ym):
    """الشهر السابق تقويمياً (مثل 2026-02 → 2026-01)."""
    y, m = int(month_ym[:4]), int(month_ym[5:7])
    if m == 1:
        return f"{y - 1}-12"
    return f"{y:04d}-{m - 1:02d}"


def _bank_opening_at_month_start(table_name, month_ym, get_opening_balance):
    """رصيد أول الشهر = رصيد نهاية الشهر السابق (آخر حركة)، أو قبل أول حركة في الشهر."""
    first_day = f"{month_ym}-01"
    prev_ym = _prev_calendar_month_ym(month_ym)
    conn = sqlite3.connect(DB_PATH)
    try:
        prior = conn.execute(
            f"""SELECT date, movement_type, amount, balance_after FROM {table_name}
                WHERE substr(date, 1, 7) < ? AND balance_after IS NOT NULL
                ORDER BY date DESC, id DESC LIMIT 1""",
            (month_ym,),
        ).fetchone()
        first_in = conn.execute(
            f"""SELECT movement_type, amount, balance_after FROM {table_name}
                WHERE substr(date, 1, 7) = ? AND balance_after IS NOT NULL
                ORDER BY date ASC, id ASC LIMIT 1""",
            (month_ym,),
        ).fetchone()
        if prior and str(prior[0] or "")[:7] == prev_ym:
            return _bank_balance_value(prior[3])
        if first_in:
            try:
                return _balance_before_movement(first_in[2], first_in[0], first_in[1])
            except (ValueError, TypeError):
                pass
        if prior:
            return _bank_balance_value(prior[3])
        prior_n = conn.execute(
            f"SELECT COUNT(*) FROM {table_name} WHERE substr(date, 1, 7) < ?",
            (month_ym,),
        ).fetchone()[0]
        if not prior_n:
            return _compute_bank_opening_before(table_name, first_day, get_opening_balance)
        return _compute_bank_opening_cumulative(table_name, month_ym, get_opening_balance)
    finally:
        conn.close()


def refresh_bank_opening_from_xlsx(filepath, table_name):
    """تحديث الرصيد الافتتاحي المحفوظ من أول صف في ملف Excel دون استيراد الحركات."""
    return _import_bank_from_xlsx(filepath, table_name, opening_only=True)


def _bank_import_existing_keys(table_name, month_filter=None):
    """مفاتيح الحركات الموجودة. عند استيراد شهر محدد لا يُمنع أي صف من الملف."""
    if month_filter:
        return {}
    existing_rows = {}
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        f"""SELECT date, movement_type, amount, receipt_number, description,
            customer_name, invoice_number, balance_after FROM {table_name}"""
    ).fetchall()
    conn.close()
    for row in rows:
        key = _bank_movement_row_key(
            row[0], row[1], row[2], row[3], row[4], row[5], row[6], row[7]
        )
        existing_rows[key] = existing_rows.get(key, 0) + 1
    return existing_rows


def _bank_parse_date_cell(date_val):
    """تحويل خلية التاريخ من Excel إلى YYYY-MM-DD."""
    if date_val is None:
        return ""
    if hasattr(date_val, "strftime"):
        return date_val.strftime("%Y-%m-%d")
    date_val_s = str(date_val).strip()
    if date_val_s and re.match(r"^\d{4}-\d{2}-\d{2}$", date_val_s):
        return date_val_s
    if date_val_s and re.match(r"^\d{2}/\d{2}/\d{4}$", date_val_s):
        parts = date_val_s.split("/")
        return f"{parts[2]}-{parts[1]}-{parts[0]}"
    if date_val_s and str(date_val).replace(".", "").replace("-", "").isdigit():
        try:
            n = float(date_val)
            if 1 <= n <= 300000:
                return _excel_serial_to_date(date_val)
        except (ValueError, TypeError):
            pass
    return date_val_s


def _bank_extract_receipt_from_bayan(bayan):
    if not bayan:
        return ""
    bayan = str(bayan).strip()
    m = re.search(r"سند\s+قبض\s+\d+\s+ف\s+(\d+)", bayan)
    if m:
        return m.group(1)
    m = re.search(r"سند\s+صرف\s*\(?\s*(\d+)", bayan)
    if m:
        return m.group(1)
    m = re.search(r"فيزا\s+سند\s+صرف\s*\(?\s*(\d+)", bayan)
    if m:
        return m.group(1)
    m = re.match(r"^(\d+)\s", bayan)
    if m:
        return m.group(1)
    return ""


def _bank_extract_supplier_from_bayan(bayan):
    if not bayan:
        return ""
    m = re.search(r"\(([^)]+)\)", str(bayan))
    return m.group(1).strip() if m else ""


def _import_bank_from_xlsx_openpyxl(filepath, table_name, opening_only=False, month_filter=None):
    """استيراد البنك عبر openpyxl — يقرأ كل الصفوف بما فيها آخر الشهر."""
    import openpyxl

    wb = openpyxl.load_workbook(filepath, data_only=True)
    ws = wb.active
    header_row_num = 3
    header_row_vals = {}
    for r in range(1, 6):
        row_vals = {}
        for col_letter, col_idx in zip("ABCDEFGH", range(1, 9)):
            row_vals[col_letter] = str(ws.cell(r, col_idx).value or "")
        if any("بيان" in v for v in row_vals.values()) and any("تاريخ" in v for v in row_vals.values()):
            header_row_vals = row_vals
            header_row_num = r
            break
    is_accountant_format = (
        any("بيان" in str(header_row_vals.get(c, "")) for c in ["A", "B"])
        and any("تاريخ" in str(header_row_vals.get(c, "")) for c in ["B", "C"])
    ) or (
        bool(header_row_vals.get("A", ""))
        and "سند" not in str(header_row_vals.get("B", ""))
        and "مورد" not in str(header_row_vals.get("C", ""))
    )

    existing_rows = {} if opening_only else _bank_import_existing_keys(table_name, month_filter)
    imported, skipped = 0, 0
    incoming_rows_count = {}
    opening_state = {"saved": False, "value": None}
    opening_scan_limit = 25
    opening_scanned = 0
    data_start = header_row_num + 1
    max_row = ws.max_row or data_start

    for r in range(data_start, max_row + 1):
        if is_accountant_format:
            bayan_val = ws.cell(r, 1).value
            date_val = ws.cell(r, 2).value
            credit_val = ws.cell(r, 3).value
            debit_val = ws.cell(r, 4).value
            balance_val = ws.cell(r, 5).value
            receipt_str = _bank_extract_receipt_from_bayan(bayan_val)
            supplier_str = _bank_extract_supplier_from_bayan(bayan_val)
            desc_str = str(bayan_val or "").strip()
        else:
            receipt_val = ws.cell(r, 2).value
            supplier_val = ws.cell(r, 3).value
            desc_val = ws.cell(r, 4).value
            date_val = ws.cell(r, 5).value
            credit_val = ws.cell(r, 6).value
            debit_val = ws.cell(r, 7).value
            balance_val = ws.cell(r, 8).value
            receipt_str = str(receipt_val or "").strip()
            supplier_str = str(supplier_val or "").strip()
            desc_str = str(desc_val or "").strip()
            bayan_val = desc_str

        if not str(bayan_val or "").strip() and credit_val in (None, "") and debit_val in (None, ""):
            continue

        date_str = _bank_parse_date_cell(date_val) or datetime.now().strftime("%Y-%m-%d")
        if month_filter and str(date_str)[:7] != month_filter:
            continue

        try:
            credit_f = float(str(credit_val or "").replace(",", ".") or 0)
        except (ValueError, TypeError):
            credit_f = 0
        try:
            debit_f = float(str(debit_val or "").replace(",", ".") or 0)
        except (ValueError, TypeError):
            debit_f = 0

        if not opening_state["saved"]:
            opening_scanned += 1
            _opening_scan_update(opening_state, balance_val, credit_f, debit_f, bayan_val)
            if opening_only:
                if opening_state["saved"] or opening_scanned >= opening_scan_limit:
                    _commit_opening_scan(table_name, opening_state)
                    return 0, 0, ""
                if credit_f <= 0 and debit_f <= 0:
                    continue
            elif credit_f <= 0 and debit_f <= 0:
                continue
        elif opening_only:
            continue

        if credit_f <= 0 and debit_f <= 0:
            continue

        movement_type = "حركات دائنة" if credit_f > 0 else "حركات مدينة"
        amount = credit_f if credit_f > 0 else debit_f
        bal_after = _parse_excel_balance_val(balance_val)
        key = _bank_movement_row_key(
            date_str, movement_type, amount, receipt_str, desc_str, supplier_str, "", bal_after
        )
        if not month_filter:
            incoming_count = incoming_rows_count.get(key, 0) + 1
            incoming_rows_count[key] = incoming_count
            if existing_rows.get(key, 0) >= incoming_count:
                skipped += 1
                continue
        insert_bank_movement(
            table_name, movement_type, amount, date_str, "",
            supplier_str, receipt_str, desc_str, balance_after=bal_after,
        )
        imported += 1

    if opening_only:
        _commit_opening_scan(table_name, opening_state)
        return 0, 0, ""
    _commit_opening_scan(table_name, opening_state)
    _post_bank_import_finalize(table_name, month_filter)
    return imported, skipped, ""


def _import_bank_from_xlsx(filepath, table_name, opening_only=False, month_filter=None):
    """استيراد حركات البنك من Excel - جدول bank_main_movements أو bank_sub_movements"""
    if not os.path.isfile(filepath):
        return 0, 0, "الملف غير موجود"
    try:
        import openpyxl  # noqa: F401
        return _import_bank_from_xlsx_openpyxl(filepath, table_name, opening_only, month_filter)
    except Exception:
        pass
    try:
        existing_rows = {} if opening_only else _bank_import_existing_keys(table_name, month_filter)
        with zipfile.ZipFile(filepath, 'r') as z:
            sheet_xml = z.read('xl/worksheets/sheet1.xml')
            shared_strings = _read_shared_strings(z)
        ns = {'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

        def get_cell_val(cell_elem):
            t = cell_elem.get('t', '')
            v_el = cell_elem.find('main:v', ns)
            v = v_el.text if v_el is not None else ''
            if t == 's':
                try:
                    idx = int(float(str(v)))
                    return shared_strings[idx] if 0 <= idx < len(shared_strings) else ''
                except (ValueError, TypeError):
                    return ''
            if t == 'inlineStr':
                is_el = cell_elem.find('main:is', ns)
                if is_el is not None:
                    t_el = is_el.find('main:t', ns)
                    if t_el is not None and t_el.text:
                        return t_el.text
                    return ''.join(r.find('main:t', ns).text or '' for r in is_el.findall('main:r', ns))
                return ''
            return str(v).strip() if v else ''

        root = ET.fromstring(sheet_xml)
        sheet_data = root.find('.//main:sheetData', ns)
        if sheet_data is None:
            return 0, 0, "تعذر قراءة البيانات"
        def row_num(elem):
            m = re.search(r'\d+', elem.get('r', '') or '')
            return int(m.group()) if m else 0
        # --- تحديد تنسيق الملف: هل هو تنسيق المحاسب (البيان-التاريخ-دائن-مدين-رصيد) أم التنسيق القديم ---
        # نفحص الصف 2 أو 3 (رؤوس الأعمدة) لتحديد التنسيق
        header_row_vals = {}
        header_row_num = 3  # افتراضي
        for row in sheet_data:
            r_ref = row.get('r', '')
            r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
            if r_num in (2, 3):
                row_vals = {}
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    row_vals[col] = get_cell_val(c)
                # إذا وجدنا 'بيان' أو 'تاريخ' في هذا الصف فهو صف الرؤوس
                if any('بيان' in str(v) or 'تاريخ' in str(v) for v in row_vals.values()):
                    header_row_vals = row_vals
                    header_row_num = r_num
                    break
            if r_num > 3:
                break
        # تنسيق المحاسب: العمود A = البيان، B = التاريخ، C = دائن، D = مدين، E = رصيد
        # التنسيق القديم: العمود B = السند، C = المورد، D = البيان، E = التاريخ، F = دائن، G = مدين
        is_accountant_format = (
            any('بيان' in str(header_row_vals.get(c, '')) for c in ['A', 'B']) and
            any('تاريخ' in str(header_row_vals.get(c, '')) for c in ['B', 'C'])
        ) or (
            # إذا كان العمود A يحتوي على بيانات نصية والعمود B تاريخ
            header_row_vals.get('A', '') and not header_row_vals.get('B', '') == '' and
            'سند' not in str(header_row_vals.get('B', '')) and 'مورد' not in str(header_row_vals.get('C', ''))
        )

        def _extract_receipt_from_bayan(bayan):
            """استخراج رقم السند من نص البيان"""
            if not bayan:
                return ''
            bayan = str(bayan).strip()
            # نمط: سند قبض XXXX ف YYYY → رقم السند = YYYY
            m = re.search(r'سند\s+قبض\s+\d+\s+ف\s+(\d+)', bayan)
            if m:
                return m.group(1)
            # نمط: سند صرف (XXX) أو سند صرف XXX
            m = re.search(r'سند\s+صرف\s*\(?\s*(\d+)', bayan)
            if m:
                return m.group(1)
            # نمط: فيزا سند صرف (XXX)
            m = re.search(r'فيزا\s+سند\s+صرف\s*\(?\s*(\d+)', bayan)
            if m:
                return m.group(1)
            # رقم في بداية النص
            m = re.match(r'^(\d+)\s', bayan)
            if m:
                return m.group(1)
            return ''

        def _extract_supplier_from_bayan(bayan):
            """استخراج اسم الجهة من نص البيان"""
            if not bayan:
                return ''
            bayan = str(bayan).strip()
            # نمط: سند صرف XXX ( اسم الجهة ) → استخراج ما بين القوسين
            m = re.search(r'\(([^)]+)\)', bayan)
            if m:
                return m.group(1).strip()
            # نمط: سند قبض XXXX ف YYYY → لا يوجد اسم جهة واضح
            return ''

        imported, skipped = 0, 0
        opening_state = {"saved": False, "value": None}
        opening_scan_limit = 25
        opening_scanned = 0
        incoming_rows_count = {}  # عداد الحركات الواردة من Excel لكل مفتاح

        if is_accountant_format:
            # تنسيق المحاسب: A=البيان، B=التاريخ، C=دائن، D=مدين، E=رصيد
            col_map = {'A': 0, 'B': 1, 'C': 2, 'D': 3, 'E': 4}
            data_start_row = header_row_num + 1  # البيانات تبدأ بعد صف الرؤوس
            for row in sorted(sheet_data, key=row_num):
                r_ref = row.get('r', '')
                r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
                if r_num < data_start_row:  # تخطي الصفوف الأولى (عنوان + رؤوس)
                    continue
                vals = [''] * 5
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    if col in col_map:
                        vals[col_map[col]] = get_cell_val(c)
                bayan_val, date_val, credit_val, debit_val, balance_val = vals
                # تحويل التاريخ
                if hasattr(date_val, 'strftime'):
                    date_str = date_val.strftime('%Y-%m-%d') if date_val else datetime.now().strftime('%Y-%m-%d')
                else:
                    date_val_s = str(date_val or '').strip()
                    if date_val_s and re.match(r'^\d{4}-\d{2}-\d{2}$', date_val_s):
                        date_str = date_val_s
                    elif date_val_s and re.match(r'^\d{2}/\d{2}/\d{4}$', date_val_s):
                        parts = date_val_s.split('/')
                        date_str = f'{parts[2]}-{parts[1]}-{parts[0]}'
                    elif date_val and str(date_val).replace('.','').replace('-','').isdigit():
                        try:
                            n = float(date_val)
                            date_str = _excel_serial_to_date(date_val) if 1 <= n <= 300000 else (date_val_s or datetime.now().strftime('%Y-%m-%d'))
                        except (ValueError, TypeError):
                            date_str = date_val_s or datetime.now().strftime('%Y-%m-%d')
                    else:
                        date_str = date_val_s or datetime.now().strftime('%Y-%m-%d')
                if month_filter and (not date_str or str(date_str)[:7] != month_filter):
                    continue
                # تحويل المبالغ
                try:
                    credit_f = float(str(credit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    credit_f = 0
                try:
                    debit_f = float(str(debit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    debit_f = 0
                if not opening_state["saved"]:
                    opening_scanned += 1
                    _opening_scan_update(opening_state, balance_val, credit_f, debit_f, bayan_val)
                    if opening_only:
                        if opening_state["saved"] or opening_scanned >= opening_scan_limit:
                            _commit_opening_scan(table_name, opening_state)
                            return 0, 0, ""
                        continue
                    if not opening_state["saved"]:
                        if credit_f <= 0 and debit_f <= 0:
                            continue
                elif opening_only:
                    continue
                if credit_f <= 0 and debit_f <= 0:
                    continue
                movement_type = 'حركات دائنة' if credit_f > 0 else 'حركات مدينة'
                amount = credit_f if credit_f > 0 else debit_f
                # استخراج رقم السند واسم الجهة من البيان
                receipt_str = _extract_receipt_from_bayan(bayan_val)
                supplier_str = _extract_supplier_from_bayan(bayan_val)
                desc_str = str(bayan_val or '').strip()
                bal_after = _parse_excel_balance_val(balance_val)
                key = _bank_movement_row_key(
                    date_str, movement_type, amount, receipt_str, desc_str, supplier_str, "", bal_after
                )
                if not month_filter:
                    incoming_count = incoming_rows_count.get(key, 0) + 1
                    incoming_rows_count[key] = incoming_count
                    if existing_rows.get(key, 0) >= incoming_count:
                        skipped += 1
                        continue
                insert_bank_movement(
                    table_name, movement_type, amount, date_str, "",
                    supplier_str, receipt_str, desc_str, balance_after=bal_after,
                )
                imported += 1
        else:
            # التنسيق القديم: B=السند، C=المورد، D=البيان، E=التاريخ، F=دائن، G=مدين، H=رصيد
            col_map = {'B': 0, 'C': 1, 'D': 2, 'E': 3, 'F': 4, 'G': 5, 'H': 6}
            for row in sorted(sheet_data, key=row_num):
                r_ref = row.get('r', '')
                r_num = int(re.search(r'\d+', r_ref).group()) if re.search(r'\d+', r_ref) else 0
                if r_num < 3:
                    continue
                vals = [''] * 7
                for c in row:
                    ref = c.get('r', '')
                    col = ref[0] if len(ref) >= 1 else ''
                    if col in col_map:
                        vals[col_map[col]] = get_cell_val(c)
                receipt_val, supplier_val, desc_val, date_val, credit_val, debit_val, balance_val = vals
                try:
                    credit_f = float(str(credit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    credit_f = 0
                try:
                    debit_f = float(str(debit_val or '').replace(',', '.') or 0)
                except (ValueError, TypeError):
                    debit_f = 0
                if not opening_state["saved"]:
                    opening_scanned += 1
                    _opening_scan_update(opening_state, balance_val, credit_f, debit_f, desc_val)
                    if opening_only:
                        if opening_state["saved"] or opening_scanned >= opening_scan_limit:
                            _commit_opening_scan(table_name, opening_state)
                            return 0, 0, ""
                        if credit_f <= 0 and debit_f <= 0:
                            continue
                    elif credit_f <= 0 and debit_f <= 0:
                        continue
                elif opening_only:
                    continue
                if credit_f <= 0 and debit_f <= 0:
                    continue
                movement_type = 'حركات دائنة' if credit_f > 0 else 'حركات مدينة'
                amount = credit_f if credit_f > 0 else debit_f
                date_val_s = str(date_val or '').strip()
                if date_val_s and re.match(r'^\d{4}-\d{2}-\d{2}$', date_val_s):
                    date_str = date_val_s
                elif date_val and str(date_val).replace('.', '').replace('-', '').isdigit():
                    try:
                        n = float(date_val)
                        date_str = _excel_serial_to_date(date_val) if 1 <= n <= 300000 else (date_val_s or datetime.now().strftime('%Y-%m-%d'))
                    except (ValueError, TypeError):
                        date_str = date_val_s or datetime.now().strftime('%Y-%m-%d')
                else:
                    date_str = date_val_s or datetime.now().strftime('%Y-%m-%d')
                if month_filter and (not date_str or str(date_str)[:7] != month_filter):
                    continue
                receipt_str = str(receipt_val or '').strip()
                supplier_str = (supplier_val or "").strip()
                desc_str = str(desc_val or "").strip()
                bal_after = _parse_excel_balance_val(balance_val)
                key = _bank_movement_row_key(
                    date_str, movement_type, amount, receipt_str, desc_str, supplier_str, "", bal_after
                )
                if not month_filter:
                    incoming_count = incoming_rows_count.get(key, 0) + 1
                    incoming_rows_count[key] = incoming_count
                    if existing_rows.get(key, 0) >= incoming_count:
                        skipped += 1
                        continue
                insert_bank_movement(
                    table_name, movement_type, amount, date_str, "",
                    supplier_str, receipt_str, desc_str, balance_after=bal_after,
                )
                imported += 1
        if opening_only:
            _commit_opening_scan(table_name, opening_state)
            return 0, 0, ""
        _commit_opening_scan(table_name, opening_state)
        _post_bank_import_finalize(table_name, month_filter)
        return imported, skipped, ""
    except zipfile.BadZipFile:
        return 0, 0, "الملف ليس بصيغة Excel صالحة"
    except Exception as e:
        return 0, 0, str(e)


def _export_bank_to_xlsx(filepath, table_name, opening_balance=0):
    """تصدير حركات البنك إلى Excel"""
    if not filepath or not str(filepath).strip():
        return False, "مسار الملف فارغ"
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute(
            f"""SELECT date, movement_type, amount, invoice_number, customer_name, receipt_number, description, balance_after
            FROM {table_name} ORDER BY date ASC, id ASC"""
        ).fetchall()
        conn.close()
        all_strings = ["السند", "المورد / المصدر", "البيان", "التاريخ", "حركات دائنة", "حركات مدينة", "الرصيد"]
        string_to_idx = {s: i for i, s in enumerate(all_strings)}
        def get_str_idx(s):
            s = str(s or "").strip()
            if s not in string_to_idx:
                string_to_idx[s] = len(all_strings)
                all_strings.append(s)
            return string_to_idx[s]
        for r in rows:
            get_str_idx(r[0])
            get_str_idx(r[4])
            get_str_idx(r[5])
            get_str_idx(_strip_sund_sarf_from_desc(r[6]) if r[6] and table_name == "bank_sub_movements" else (r[6] or ""))
        def esc_xml(t):
            return str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
        shared_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="' + str(len(all_strings)) + '" uniqueCount="' + str(len(all_strings)) + '">'
        for s in all_strings:
            shared_xml += '<si><t>' + esc_xml(s) + '</t></si>'
        shared_xml += '</sst>'
        header_row = '<row r="2"><c r="B2" t="s"><v>0</v></c><c r="C2" t="s"><v>1</v></c><c r="D2" t="s"><v>2</v></c><c r="E2" t="s"><v>3</v></c><c r="F2" t="s"><v>4</v></c><c r="G2" t="s"><v>5</v></c><c r="H2" t="s"><v>6</v></c></row>'
        sheet_rows = header_row
        balance = opening_balance
        if rows:
            amt0 = float(rows[0][2] or 0)
            first_effect = amt0 if (rows[0][1] or "").strip() == "حركات مدينة" else -amt0
            balance = opening_balance - first_effect
        for i, r in enumerate(rows):
            rownum = 3 + i
            date_idx = get_str_idx(r[0] if r[0] else "")
            receipt_idx = get_str_idx(r[5] if r[5] else "")
            supplier_idx = get_str_idx(r[4] if r[4] else "")
            desc_val = _strip_sund_sarf_from_desc(r[6]) if r[6] and table_name == "bank_sub_movements" else (r[6] or "")
            desc_idx = get_str_idx(desc_val)
            amt = float(r[2] or 0)
            if (r[1] or "").strip() == "حركات مدينة":
                credit_val, debit_val = 0, amt
            else:
                credit_val, debit_val = amt, 0
            bal_stored = r[7] if len(r) > 7 else None
            if bal_stored is not None:
                try:
                    balance = float(bal_stored)
                except (ValueError, TypeError):
                    balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            else:
                balance += amt if (r[1] or "").strip() == "حركات مدينة" else -amt
            sheet_rows += f'<row r="{rownum}"><c r="B{rownum}" t="s"><v>{receipt_idx}</v></c><c r="C{rownum}" t="s"><v>{supplier_idx}</v></c><c r="D{rownum}" t="s"><v>{desc_idx}</v></c><c r="E{rownum}" t="s"><v>{date_idx}</v></c><c r="F{rownum}" t="n"><v>{credit_val}</v></c><c r="G{rownum}" t="n"><v>{debit_val}</v></c><c r="H{rownum}" t="n"><v>{balance:.6f}</v></c></row>'
        sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + sheet_rows + '</sheetData><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>'
        with zipfile.ZipFile(filepath, 'r') as z_in:
            skip = ('xl/worksheets/sheet1.xml', 'xl/sharedStrings.xml', 'xl/calcChain.xml')
            other_files = {n: z_in.read(n) for n in z_in.namelist() if n not in skip}
        fd, tmp = tempfile.mkstemp(suffix='.xlsx', dir=os.path.dirname(filepath) or '.')
        try:
            os.close(fd)
            with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as z_out:
                for n, data in other_files.items():
                    z_out.writestr(n, data)
                z_out.writestr('xl/sharedStrings.xml', shared_xml.encode('utf-8'))
                z_out.writestr('xl/worksheets/sheet1.xml', sheet_xml.encode('utf-8'))
            shutil.move(tmp, filepath)
        except (PermissionError, OSError) as e:
            if os.path.exists(tmp):
                try:
                    os.unlink(tmp)
                except Exception:
                    pass
            return False, "الملف مفتوح أو غير متاح للكتابة. أغلق Excel ثم حاول مرة أخرى."
        return True, ""
    except Exception as e:
        return False, str(e)


def sync_bank_main_with_xlsx(filepath):
    """مزامنة البنك الرئيسي مع ملف Excel - استيراد فقط بدون كتابة فوق الملف الأصلي"""
    imp, sk, err = _import_bank_from_xlsx(filepath, "bank_main_movements")
    if err:
        return imp, sk, err
    # لا نُصدِّر فوق الملف الأصلي لتجنب فقدان البيانات (الرصيد الافتتاحي)
    return imp, sk, ""


def _auto_sync_bank_sub_on_page_view():
    """مزامنة البنك الفرعي عند الحاجة فقط (عند تغيّر ملف Excel — لا في كل زيارة)."""
    global _bank_sub_synced_mtime
    if os.environ.get("DISABLE_BANK_AUTO_SYNC", "").strip().lower() in ("1", "true", "yes"):
        return 0, 0, "", 0
    if not os.path.isfile(BANK_SUB_XLSX_PATH):
        return 0, 0, "", 0
    try:
        mtime = os.path.getmtime(BANK_SUB_XLSX_PATH)
    except OSError:
        return 0, 0, "", 0
    if _bank_sub_synced_mtime == mtime:
        return 0, 0, "", 0
    imported, sk, err = sync_bank_sub_with_xlsx(BANK_SUB_XLSX_PATH, replace_from_file=False)
    if not err:
        _bank_sub_synced_mtime = mtime
    return imported, sk, err, 0


def sync_bank_sub_with_xlsx(filepath, replace_from_file=False):
    """مزامنة ثنائية: استيراد حركات الحساب الفرعي من Excel ثم تصدير إليه.
    إذا replace_from_file=True يتم استبدال جدول قاعدة البيانات كاملاً ببيانات الملف (الملف هو المصدر)."""
    # استخدام _import_bank_from_xlsx (المصحح) بدلاً من import_bank_sub_from_xlsx القديمة
    if replace_from_file:
        _conn = sqlite3.connect(DB_PATH)
        _conn.execute("DELETE FROM bank_sub_movements")
        _conn.commit()
        _conn.close()
    imp, sk, err = _import_bank_from_xlsx(filepath, "bank_sub_movements")
    if err:
        return imp, sk, err
    # عند replace_from_file=True لا نُصدِّر فوق الملف الأصلي لتجنب فقدان البيانات
    if not replace_from_file:
        ok, export_err = export_bank_sub_to_xlsx(filepath)
        if not ok and export_err:
            return imp, sk, "استيراد OK، تصدير فشل: " + export_err
    return imp, sk, ""


def get_bank_folder_xlsx_files():
    """جلب جميع ملفات Excel في مجلد Bank والملفات الفرعية (استثناء ملفات القفل ~$)"""
    files = []
    if not os.path.isdir(BANK_DIR):
        return files
    for root, _, names in os.walk(BANK_DIR):
        for name in names:
            if name.lower().endswith(".xlsx") and not name.startswith("~$"):
                files.append(os.path.join(root, name))
    return sorted(files)


def sync_all_bank_files():
    """مزامنة جميع ملفات Excel في مجلد Bank مع قاعدة البيانات - يُرجع (رسائل_نجاح، أخطاء)"""
    messages = []
    errors = []
    files = get_bank_folder_xlsx_files()
    for filepath in files:
        rel_path = os.path.relpath(filepath, BASE_DIR) if filepath.startswith(BASE_DIR) else filepath
        imp, _, err = sync_bank_sub_with_xlsx(filepath)
        if err:
            errors.append(f"{rel_path}: {err}")
        elif imp > 0:
            messages.append(f"{rel_path}: {imp} حركة جديدة")
    return messages, errors


def sync_all_linked_files():
    """مزامنة جميع الملفات المرتبطة بقاعدة البيانات - يُرجع (رسائل_نجاح، أخطاء)"""
    return sync_all_bank_files()


