            f'action="/edit-loan-installment-due-date" style="display:none">'
            f'<input type="hidden" name="installment_id" value="{int(iid)}">'
            f'<input type="hidden" name="loan_id" value="{int(loan_id)}">'
            f'<label class="pl-edit-lbl">الاستحقاق'
            f'<input type="date" name="due_date" value="{_esc(str(due)[:10])}" class="pl-date-inp" required></label>'
            f'<label class="pl-edit-lbl">قيمة القسط'
            f'<input type="number" name="amount" value="{amt:.3f}" '
            f'class="pl-amt-inp" step="0.001" min="0.001" required></label>'
