def ensure_expense_scans_dir():
    os.makedirs(EXPENSE_SCANS_DIR, exist_ok=True)


def _decode_data_url_image(data_url):
    """فك base64 من data URL أو نص base64 خام."""
    import base64
    import re

    s = str(data_url or "").strip()
    if not s:
        return None
    if s.startswith("data:"):
        m = re.match(r"data:image/[^;]+;base64,(.+)", s, re.DOTALL | re.IGNORECASE)
        if m:
            s = m.group(1)
    try:
        return base64.b64decode(s, validate=False)
    except Exception:
        return None


def _scan_order_points(pts):
    import numpy as np

    rect = np.zeros((4, 2), dtype="float32")
    s = pts.sum(axis=1)
    rect[0] = pts[np.argmin(s)]
    rect[2] = pts[np.argmax(s)]
    diff = np.diff(pts, axis=1)
    rect[1] = pts[np.argmin(diff)]
    rect[3] = pts[np.argmax(diff)]
    return rect


def _scan_four_point_transform(image_bgr, pts):
    import cv2
    import numpy as np

    rect = _scan_order_points(pts)
    tl, tr, br, bl = rect
    width_a = np.linalg.norm(br - bl)
    width_b = np.linalg.norm(tr - tl)
    max_width = max(int(width_a), int(width_b))
    height_a = np.linalg.norm(tr - br)
    height_b = np.linalg.norm(tl - bl)
    max_height = max(int(height_a), int(height_b))
    max_width = max(max_width, 100)
    max_height = max(max_height, 100)
    dst = np.array(
        [[0, 0], [max_width - 1, 0], [max_width - 1, max_height - 1], [0, max_height - 1]],
        dtype="float32",
    )
    matrix = cv2.getPerspectiveTransform(rect, dst)
    return cv2.warpPerspective(image_bgr, matrix, (max_width, max_height))


def _scan_find_document_points(image_bgr):
    """اكتشاف حدود المستند (4 نقاط) للتصحيح المنظوري."""
    import cv2
    import numpy as np

    h, w = image_bgr.shape[:2]
    scale = min(1.0, 800.0 / max(h, w))
    small = cv2.resize(image_bgr, None, fx=scale, fy=scale) if scale < 1 else image_bgr.copy()
    gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
    gray = cv2.GaussianBlur(gray, (5, 5), 0)
    edged = cv2.Canny(gray, 75, 200)
    edged = cv2.dilate(edged, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)), iterations=1)
    contours, _ = cv2.findContours(edged, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)
    contours = sorted(contours, key=cv2.contourArea, reverse=True)[:12]
    area_min = small.shape[0] * small.shape[1] * 0.12
    for cnt in contours:
        if cv2.contourArea(cnt) < area_min:
            continue
        peri = cv2.arcLength(cnt, True)
        approx = cv2.approxPolyDP(cnt, 0.02 * peri, True)
        if len(approx) == 4 and cv2.isContourConvex(approx):
            pts = approx.reshape(4, 2).astype("float32") / scale
            return pts
    return None


def _scan_enhance_color(image_bgr):
    """تحسين وضوح المستند مع الحفاظ على الألوان."""
    import cv2
    import numpy as np

    lab = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2LAB)
    l_ch, a_ch, b_ch = cv2.split(lab)
    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
    l_ch = clahe.apply(l_ch)
    enhanced = cv2.merge([l_ch, a_ch, b_ch])
    enhanced = cv2.cvtColor(enhanced, cv2.COLOR_LAB2BGR)
    enhanced = cv2.fastNlMeansDenoisingColored(enhanced, None, 5, 5, 7, 21)
    sharpen = np.array([[0, -1, 0], [-1, 5, -1], [0, -1, 0]], dtype=np.float32)
    enhanced = cv2.filter2D(enhanced, -1, sharpen)
    return enhanced


def _scan_document_pillow_fallback(image_bytes):
    """Fallback when OpenCV unavailable — color enhancement only."""
    import io

    from PIL import Image, ImageEnhance, ImageFilter, ImageOps

    img = Image.open(io.BytesIO(image_bytes))
    img = ImageOps.exif_transpose(img)
    if img.mode != "RGB":
        img = img.convert("RGB")
    w, h = img.size
    if max(w, h) < 1800:
        ratio = 1800 / max(w, h)
        img = img.resize((int(w * ratio), int(h * ratio)), Image.Resampling.LANCZOS)
    img = ImageOps.autocontrast(img, cutoff=1)
    img = ImageEnhance.Contrast(img).enhance(1.15)
    img = ImageEnhance.Color(img).enhance(1.08)
    img = ImageEnhance.Sharpness(img).enhance(1.35)
    img = img.filter(ImageFilter.UnsharpMask(radius=1.0, percent=130, threshold=2))
    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=92, optimize=True)
    return buf.getvalue()


def enhance_image_for_scan(image_bytes):
    """مسح مستند مثل WhatsApp: تصحيح منظور + ألوان واضحة."""
    import io

    try:
        import cv2
        import numpy as np
        from PIL import Image, ImageOps
    except ImportError:
        return _scan_document_pillow_fallback(image_bytes)

    pil = Image.open(io.BytesIO(image_bytes))
    pil = ImageOps.exif_transpose(pil)
    if pil.mode != "RGB":
        pil = pil.convert("RGB")
    image_bgr = cv2.cvtColor(np.array(pil), cv2.COLOR_RGB2BGR)

    pts = _scan_find_document_points(image_bgr)
    if pts is not None:
        warped = _scan_four_point_transform(image_bgr, pts)
    else:
        warped = image_bgr

    enhanced = _scan_enhance_color(warped)
    h, w = enhanced.shape[:2]
    if max(h, w) < 1800:
        sc = 1800 / max(h, w)
        enhanced = cv2.resize(enhanced, (int(w * sc), int(h * sc)), interpolation=cv2.INTER_CUBIC)
    ok, buf = cv2.imencode(".jpg", enhanced, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
    if not ok:
        return _scan_document_pillow_fallback(image_bytes)
    return buf.tobytes()


def image_bytes_to_pdf_file(image_bytes, out_path, skip_enhance=False):
    """تحويل صورة إلى PDF A4 بجودة مسح."""
    import io

    from PIL import Image
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfgen import canvas

    processed = image_bytes if skip_enhance else enhance_image_for_scan(image_bytes)
    img = Image.open(io.BytesIO(processed))
    iw, ih = img.size
    page_w, page_h = A4
    margin = 18
    scale = min((page_w - 2 * margin) / iw, (page_h - 2 * margin) / ih)
    draw_w, draw_h = iw * scale, ih * scale
    x = (page_w - draw_w) / 2
    y = (page_h - draw_h) / 2
    c = canvas.Canvas(out_path, pagesize=A4)
    c.setFillColorRGB(1, 1, 1)
    c.rect(0, 0, page_w, page_h, fill=1, stroke=0)
    c.drawImage(ImageReader(img), x, y, width=draw_w, height=draw_h, preserveAspectRatio=True, anchor="c")
    c.save()


def insert_expense_invoice_scan(
    scan_date,
    invoice_date,
    invoice_number,
    supplier_name,
    description,
    amount,
    voucher_number,
    expense_type,
    pdf_filename,
    ai_json="",
    notes="",
):
    conn = sqlite3.connect(DB_PATH)
    cur = conn.execute(
        """INSERT INTO expense_invoice_scans
           (scan_date, invoice_date, invoice_number, supplier_name, description, amount,
            voucher_number, expense_type, pdf_filename, ai_json, notes)
           VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (
            scan_date or "",
            invoice_date or "",
            invoice_number or "",
            supplier_name or "",
            description or "",
            float(amount or 0),
            voucher_number or "",
            expense_type or "نقدية",
            pdf_filename,
            ai_json or "",
            notes or "",
        ),
    )
    scan_id = cur.lastrowid
    conn.commit()
    conn.close()
    return scan_id


def fetch_expense_invoice_scans(limit=100, month_filter=None):
    conn = sqlite3.connect(DB_PATH)
    m = str(month_filter or "").strip()[:7]
    if m:
        rows = conn.execute(
            """SELECT id, scan_date, invoice_date, invoice_number, supplier_name, description,
                      amount, voucher_number, expense_type, pdf_filename, created_at
               FROM expense_invoice_scans
               WHERE substr(COALESCE(invoice_date, scan_date, created_at), 1, 7) = ?
               ORDER BY id DESC LIMIT ?""",
            (m, int(limit)),
        ).fetchall()
    else:
        rows = conn.execute(
            """SELECT id, scan_date, invoice_date, invoice_number, supplier_name, description,
                      amount, voucher_number, expense_type, pdf_filename, created_at
               FROM expense_invoice_scans ORDER BY id DESC LIMIT ?""",
            (int(limit),),
        ).fetchall()
    conn.close()
    return rows


def fetch_expense_scan_months():
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT DISTINCT substr(COALESCE(invoice_date, scan_date, created_at), 1, 7) AS ym
           FROM expense_invoice_scans
           WHERE ym IS NOT NULL AND ym != ''
           ORDER BY ym DESC"""
    ).fetchall()
    conn.close()
    out = []
    for (ym,) in rows:
        if ym:
            out.append((ym, _month_to_arabic(ym)))
    return out


def get_expense_invoice_scan_by_id(scan_id):
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT id, pdf_filename FROM expense_invoice_scans WHERE id = ?",
        (int(scan_id),),
    ).fetchone()
    conn.close()
    return row


def delete_expense_invoice_scan(scan_id):
    row = get_expense_invoice_scan_by_id(scan_id)
    if not row:
        return False
    pdf_path = os.path.join(EXPENSE_SCANS_DIR, row[1] or "")
    conn = sqlite3.connect(DB_PATH)
    conn.execute("DELETE FROM expense_invoice_scans WHERE id = ?", (int(scan_id),))
    conn.commit()
    conn.close()
    if pdf_path and os.path.isfile(pdf_path):
        try:
            os.remove(pdf_path)
        except OSError:
            pass
    return True


