_ATTENDANCE_WORK_WEEKDAYS = {5, 6, 0, 1, 2, 3}  # السبت → الخميس
_ATTENDANCE_START = (8, 0)
_ATTENDANCE_END = (18, 0)
_ATTENDANCE_BREAK = ((13, 0), (14, 0))
_ATTENDANCE_GRACE_MINUTES = 25
_AR_WEEKDAYS = ("الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد")


def _kuwait_now():
    """الوقت الحالي بتوقيت الكويت GMT+3."""
    return datetime.now(_KUWAIT_TZ).replace(tzinfo=None)


def _attendance_is_work_day(d):
    return d.weekday() in _ATTENDANCE_WORK_WEEKDAYS


def _attendance_ar_weekday(d):
    return _AR_WEEKDAYS[d.weekday()]


def _attendance_calc_late_minutes(t):
    """دقائق التأخير من ٨:٠٠ ص — سماح ٢٥ دقيقة."""
    now_min = t.hour * 60 + t.minute
    start_min = _ATTENDANCE_START[0] * 60 + _ATTENDANCE_START[1]
    grace_end = start_min + _ATTENDANCE_GRACE_MINUTES
    if now_min <= grace_end:
        return 0
    return now_min - start_min


def _attendance_parse_time_hm(time_str):
    s = str(time_str or "").strip()
    m = re.match(r"^(\d{1,2}):(\d{2})", s)
    if not m:
        return None
    hour, minute = int(m.group(1)), int(m.group(2))
    if hour < 0 or hour > 23 or minute < 0 or minute > 59:
        return None
    return hour, minute


def _attendance_late_for_record(work_date, check_in):
    """حساب التأخير من وقت الحضور المسجّل (بعد ٨:٢٥ ص)."""
    if not check_in:
        return 0
    hm = _attendance_parse_time_hm(check_in)
    if not hm:
        return 0
    from datetime import time as _time
    return _attendance_calc_late_minutes(_time(hm[0], hm[1]))


def _attendance_format_time_ampm(time_str):
    """عرض الوقت بنظام 12 ساعة AM/PM."""
    s = str(time_str or "").strip()
    if not s or s == "—":
        return "—"
    m = re.match(r"^(\d{1,2}):(\d{2})(?::\d{2})?$", s)
    if not m:
        return s
    hour = int(m.group(1))
    minute = int(m.group(2))
    if hour < 0 or hour > 23 or minute < 0 or minute > 59:
        return s
    period = "AM" if hour < 12 else "PM"
    hour12 = hour % 12 or 12
    return f"{hour12}:{minute:02d} {period}"


