def _attendance_fetch_month(employee_name, month_ym):
    month_ym = str(month_ym or "").strip()[:7]
    if not month_ym:
        return []
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT work_date, check_in, check_out, late_minutes
           FROM attendance_records
           WHERE employee_name=? AND substr(work_date,1,7)=?
           ORDER BY work_date ASC""",
        (str(employee_name or "").strip(), month_ym),
    ).fetchall()
    conn.close()
    return [
        {
            "work_date": r[0],
            "check_in": r[1] or "",
            "check_out": r[2] or "",
            "late_minutes": int(r[3] or 0),
        }
        for r in rows
    ]


def _attendance_punch(employee_name, action):
    """تسجيل حضور أو انصراف — الوقت لحظة الضغط."""
    name = str(employee_name or "").strip()
    if not name:
        raise ValueError("اسم الموظف مطلوب")
    now = _kuwait_now()
    today = now.strftime("%Y-%m-%d")
    time_str = now.strftime("%H:%M")
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT id, check_in, check_out FROM attendance_records WHERE employee_name=? AND work_date=?",
        (name, today),
    ).fetchone()
    if action == "check_in":
        if row and row[1]:
            conn.close()
            raise ValueError(f"تم تسجيل الحضور مسبقاً ({row[1]})")
        late = _attendance_late_for_record(today, time_str)
        if row:
            conn.execute(
                "UPDATE attendance_records SET check_in=?, late_minutes=? WHERE id=?",
                (time_str, late, row[0]),
            )
        else:
            conn.execute(
                "INSERT INTO attendance_records (employee_name, work_date, check_in, late_minutes) VALUES (?,?,?,?)",
                (name, today, time_str, late),
            )
        msg = f"تم تسجيل الحضور الساعة {time_str}"
        if late > 0:
            msg += f" — تأخير {late} دقيقة"
    elif action == "check_out":
        if not row or not row[1]:
            conn.close()
            raise ValueError("يجب تسجيل الحضور أولاً")
        if row[2]:
            conn.close()
            raise ValueError(f"تم تسجيل الانصراف مسبقاً ({row[2]})")
        conn.execute(
            "UPDATE attendance_records SET check_out=? WHERE id=?",
            (time_str, row[0]),
        )
        msg = f"تم تسجيل الانصراف الساعة {time_str}"
    else:
        conn.close()
        raise ValueError("إجراء غير صالح")
    conn.commit()
    conn.close()
    return msg


def _attendance_month_workdays_count(month_ym):
    try:
        y, m = map(int, month_ym.split("-")[:2])
    except (ValueError, TypeError):
        return 0
    import calendar
    total = 0
    for day in range(1, calendar.monthrange(y, m)[1] + 1):
        if _attendance_is_work_day(datetime(y, m, day)):
            total += 1
    return total


ATT_PHOTOS_DIR = os.path.join(_DATA_DIR, "attendance_photos")
_ATT_EMP_COOKIE = "att_emp_sess"


def _attendance_ensure_photos_dir():
    os.makedirs(ATT_PHOTOS_DIR, exist_ok=True)


def _attendance_photo_filename(employee_name):
    import hashlib
    h = hashlib.sha256(str(employee_name or "").strip().encode("utf-8")).hexdigest()[:24]
    return f"emp_{h}"


def _attendance_photo_url(employee_name, photo_file):
    if photo_file:
        return f"/attendance/photo?e={quote(str(employee_name or '').strip())}"
    return ""


def _attendance_get_profiles():
    """بيانات الموظفين للحضور: الاسم، الصورة، اسم المستخدم، هل له رقم سري."""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT employee_name, COALESCE(att_photo,''), COALESCE(att_username,''), COALESCE(att_pin_hash,'')
           FROM employees ORDER BY employee_name"""
    ).fetchall()
    conn.close()
    profiles = []
    for name, photo, username, pin_hash in rows:
        profiles.append({
            "name": name,
            "photo": photo or "",
            "photo_url": _attendance_photo_url(name, photo),
            "username": username or "",
            "has_pin": bool(pin_hash),
        })
    return profiles


def _attendance_get_profile(employee_name):
    name = str(employee_name or "").strip()
    if not name:
        return None
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        """SELECT employee_name, COALESCE(att_photo,''), COALESCE(att_username,''), COALESCE(att_pin_hash,'')
           FROM employees WHERE employee_name=?""",
        (name,),
    ).fetchone()
    conn.close()
    if not row:
        return None
    return {
        "name": row[0],
        "photo": row[1] or "",
        "photo_url": _attendance_photo_url(row[0], row[1]),
        "username": row[2] or "",
        "pin_hash": row[3] or "",
        "has_pin": bool(row[3]),
    }


def _attendance_save_profile(employee_name, display_name=None, pin=None, photo_bytes=None, photo_ext=None):
    name = str(employee_name or "").strip()
    if not name:
        raise ValueError("اسم الموظف مطلوب")
    new_name = str(display_name or "").strip() if display_name is not None else ""
    if new_name and new_name != name:
        conn = sqlite3.connect(DB_PATH)
        if conn.execute("SELECT 1 FROM employees WHERE employee_name=?", (new_name,)).fetchone():
            conn.close()
            raise ValueError("اسم الموظف موجود مسبقاً")
        conn.close()
        old_photo = _attendance_get_profile(name)
        if not rename_employee(name, new_name):
            raise ValueError("تعذر تغيير اسم الموظف")
        if old_photo and old_photo.get("photo"):
            old_path = os.path.join(ATT_PHOTOS_DIR, old_photo["photo"])
            ext = os.path.splitext(old_photo["photo"])[1] or ".jpg"
            new_fname = f"{_attendance_photo_filename(new_name)}{ext}"
            new_path = os.path.join(ATT_PHOTOS_DIR, new_fname)
            if os.path.isfile(old_path):
                try:
                    os.rename(old_path, new_path)
                except OSError:
                    shutil.copy2(old_path, new_path)
            conn = sqlite3.connect(DB_PATH)
            conn.execute("UPDATE employees SET att_photo=? WHERE employee_name=?", (new_fname, new_name))
            conn.commit()
            conn.close()
        name = new_name
    conn = sqlite3.connect(DB_PATH)
    exists = conn.execute("SELECT 1 FROM employees WHERE employee_name=?", (name,)).fetchone()
    if not exists:
        conn.close()
        raise ValueError("الموظف غير موجود")
    updates = []
    params = []
    if pin is not None and str(pin).strip():
        updates.append("att_pin_hash=?")
        params.append(_hash_password(str(pin).strip()))
    if photo_bytes:
        _attendance_ensure_photos_dir()
        ext = (photo_ext or "jpg").lower().lstrip(".")
        if ext not in ("jpg", "jpeg", "png", "webp", "gif"):
            ext = "jpg"
        fname = f"{_attendance_photo_filename(name)}.{ext}"
        fpath = os.path.join(ATT_PHOTOS_DIR, fname)
        with open(fpath, "wb") as f:
            f.write(photo_bytes)
        updates.append("att_photo=?")
        params.append(fname)
    if updates:
        params.append(name)
        conn.execute(f"UPDATE employees SET {', '.join(updates)} WHERE employee_name=?", params)
        conn.commit()
    conn.close()


def _attendance_verify_pin(employee_name, pin):
    prof = _attendance_get_profile(employee_name)
    if not prof or not prof.get("pin_hash"):
        return False
    return prof["pin_hash"] == _hash_password(str(pin or "").strip())


_ATT_ADMIN_EMP_MARKER = "__att_admin__"


def _make_att_emp_cookie(employee_name, pin_hash):
    raw = (str(employee_name).strip() + ":" + (pin_hash or "")).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii")


def _att_emp_cookie_header(cookie_val, handler=None):
    parts = [f"{_ATT_EMP_COOKIE}={cookie_val}", "Path=/", "HttpOnly", "SameSite=Lax", "Max-Age=43200"]
    if handler:
        proto = (handler.headers.get("X-Forwarded-Proto") or "").lower()
        if proto == "https" or os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"):
            parts.append("Secure")
    return "; ".join(parts)


def _clear_att_emp_cookie_header(handler=None):
    parts = [f"{_ATT_EMP_COOKIE}=", "Path=/", "HttpOnly", "Max-Age=0", "SameSite=Lax"]
    if handler:
        proto = (handler.headers.get("X-Forwarded-Proto") or "").lower()
        if proto == "https" or os.environ.get("RAILWAY_ENVIRONMENT") or os.environ.get("PORT"):
            parts.append("Secure")
    return "; ".join(parts)


def _get_att_emp_session(handler):
    cookie_header = handler.headers.get("Cookie") or ""
    for part in cookie_header.split(";"):
        part = part.strip()
        if not part.startswith(_ATT_EMP_COOKIE + "="):
            continue
        val = part[len(_ATT_EMP_COOKIE) + 1:].strip()
        if not val:
            return None
        try:
            raw = base64.urlsafe_b64decode(val.encode("ascii")).decode("utf-8")
            if ":" not in raw:
                return None
            emp_name, stored_hash = raw.split(":", 1)
            prof = _attendance_get_profile(emp_name)
            if not prof:
                return None
            if stored_hash == _ATT_ADMIN_EMP_MARKER:
                return emp_name.strip()
            if prof.get("pin_hash") == stored_hash:
                return emp_name.strip()
        except Exception:
            return None
    return None


