_DEFAULT_EMPLOYEE_NAMES = (
    "أحمد المضيان", "وليد علي حسني", "محمد عثمان", "علي أصغر", "حسين إمام", "حسن حازم",
    "شفيق الله خورشيد", "عارف حسين", "مقبول شيخ", "إسلام حمدي",
)
_employee_name_keys_cache = None


def _normalize_name_key(name):
    """مفتاح مقارنة موحّد: قصّ، إزالة تشكيل، توحيد أشكال الألف والياء."""
    if not name:
        return ""
    s = str(name).strip()
    s = "".join(c for c in s if not (0x064B <= ord(c) <= 0x065F or ord(c) == 0x0670))
    s = s.replace("\u0640", "")
    for ch in ("أ", "إ", "آ", "ٱ"):
        s = s.replace(ch, "ا")
    s = s.replace("ى", "ي")
    s = " ".join(s.split())
    return s.casefold()


def _get_employee_name_keys():
    """مجموعة مفاتيح أسماء الموظفين (جدول employees + الرواتب + القائمة الافتراضية)."""
    global _employee_name_keys_cache
    if _employee_name_keys_cache is not None:
        return _employee_name_keys_cache
    keys = {_normalize_name_key(n) for n in _DEFAULT_EMPLOYEE_NAMES if n}
    conn = sqlite3.connect(DB_PATH)
    for table in ("employees", "salaries", "employee_salary_defaults", "absences"):
        try:
            rows = conn.execute(
                f"SELECT DISTINCT employee_name FROM {table} "
                "WHERE employee_name IS NOT NULL AND trim(employee_name) != ''"
            ).fetchall()
            for row in rows:
                keys.add(_normalize_name_key(row[0]))
        except Exception:
            pass
    conn.close()
    _employee_name_keys_cache = keys
    return keys


def _invalidate_employee_name_keys_cache():
    global _employee_name_keys_cache
    _employee_name_keys_cache = None


def is_employee_company_name(company_name):
    """هل الاسم يطابق موظفاً؟ (تصفية عرض كشوف الشركات — لا يحذف من قاعدة البيانات)"""
    if not company_name or not str(company_name).strip():
        return False
    key = _normalize_name_key(company_name)
    if not key:
        return False
    emp_keys = _get_employee_name_keys()
    if key in emp_keys:
        return True
    # اسم مختصر في Excel (مثل «عارف» بدل «عارف حسين»)
    if len(key) >= 3:
        for emp_key in emp_keys:
            if emp_key == key or emp_key.startswith(key + " "):
                return True
    return False


def add_employee(name, profession=""):
    if not name or not name.strip():
        return False
    name = name.strip()
    if _employee_is_deleted(name):
        return False
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute(
            "INSERT OR IGNORE INTO employees (employee_name, profession) VALUES (?, ?)",
            (name, (profession or "").strip()),
        )
        if (profession or "").strip():
            conn.execute(
                "UPDATE employees SET profession = ? WHERE employee_name = ?",
                ((profession or "").strip(), name.strip()),
            )
        conn.commit()
        conn.close()
        _invalidate_employee_name_keys_cache()
        return True
    except Exception:
        return False


def get_all_employee_professions():
    """استرجاع مهنة كل موظف {الاسم: المهنة}"""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("SELECT employee_name, profession FROM employees").fetchall()
    conn.close()
    return {row[0]: (row[1] or "") for row in rows}


def save_employee_profession(employee_name, profession):
    conn = sqlite3.connect(DB_PATH)
    conn.execute("UPDATE employees SET profession = ? WHERE employee_name = ?", ((profession or "").strip(), employee_name.strip()))
    conn.commit()
    conn.close()


def delete_employee(name):
    if not name or not name.strip():
        return False
    name = name.strip()
    try:
        conn = sqlite3.connect(DB_PATH)
        photo_row = conn.execute(
            "SELECT att_photo FROM employees WHERE employee_name = ?", (name,)
        ).fetchone()
        for table in ("attendance_records", "salaries", "absences", "employee_salary_defaults", "employees"):
            try:
                conn.execute(f"DELETE FROM {table} WHERE employee_name = ?", (name,))
            except Exception:
                pass
        conn.execute(
            "INSERT OR REPLACE INTO employee_deletions (employee_name, deleted_at) VALUES (?, datetime('now'))",
            (name,),
        )
        conn.commit()
        conn.close()
        if photo_row and photo_row[0]:
            fpath = os.path.join(ATT_PHOTOS_DIR, photo_row[0])
            if os.path.isfile(fpath):
                try:
                    os.remove(fpath)
                except OSError:
                    pass
        _invalidate_employee_name_keys_cache()
        return True
    except Exception:
        return False


def _employee_is_deleted(name):
    n = str(name or "").strip()
    if not n:
        return False
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT 1 FROM employee_deletions WHERE employee_name=?", (n,)).fetchone()
    conn.close()
    return bool(row)


def _ensure_employee_from_import(name, profession=""):
    """إضافة موظف من استيراد الرواتب إن لم يُحذف سابقاً."""
    name = str(name or "").strip()
    if not name or _employee_is_deleted(name):
        return
    conn = sqlite3.connect(DB_PATH)
    exists = conn.execute("SELECT COUNT(*) FROM employees WHERE employee_name=?", (name,)).fetchone()[0]
    if not exists:
        conn.execute(
            "INSERT INTO employees (employee_name, profession) VALUES (?,?)",
            (name, (profession or "").strip()),
        )
        conn.commit()
    elif (profession or "").strip():
        conn.execute("UPDATE employees SET profession=? WHERE employee_name=?", ((profession or "").strip(), name))
        conn.commit()
    conn.close()


def rename_employee(old_name, new_name):
    """تحديث اسم الموظف في كل الجداول المرتبطة."""
    old_name = (old_name or "").strip()
    new_name = (new_name or "").strip()
    if not old_name or not new_name or old_name == new_name:
        return True
    try:
        conn = sqlite3.connect(DB_PATH)
        for table in ("employees", "employee_salary_defaults", "salaries", "absences", "attendance_records"):
            try:
                conn.execute(
                    f"UPDATE {table} SET employee_name=? WHERE employee_name=?",
                    (new_name, old_name),
                )
            except Exception:
                pass
        conn.commit()
        conn.close()
        _invalidate_employee_name_keys_cache()
        return True
    except Exception:
        return False


def delete_by_id(table, id_val, redirect_path="/"):
    """حذف سجل بالمعرف وإرجاع (نجاح، رسالة، مسار_الرجوع)"""
    try:
        rid = int(id_val)
        if rid <= 0:
            return False, "معرف غير صالح", redirect_path
        conn = sqlite3.connect(DB_PATH)
        conn.execute(f"DELETE FROM {table} WHERE id = ?", (rid,))
        conn.commit()
        conn.close()
        return True, "تم الحذف بنجاح", redirect_path
    except (ValueError, Exception):
        return False, "حدث خطأ أثناء الحذف", redirect_path


_INVOICE_ACTIVE_SQL = "COALESCE(cancelled, 0) = 0"


def _invoice_is_cancelled(row):
    """هل الفاتورة ملغاة؟ (عمود cancelled قبل cancelled_at في نهاية الصف)."""
    if len(row) < 2:
        return False
    try:
        return int(row[-2] or 0) == 1
    except (TypeError, ValueError):
        return False


def cancel_invoice(invoice_id):
    """إلغاء فاتورة مع الإبقاء على رقمها في قاعدة البيانات."""
    try:
        rid = int(invoice_id)
        if rid <= 0:
            return False, "معرف غير صالح"
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute(
            "SELECT id, COALESCE(cancelled, 0) FROM invoices WHERE id = ?", (rid,)
        ).fetchone()
        if not row:
            conn.close()
            return False, "الفاتورة غير موجودة"
        if int(row[1] or 0):
            conn.close()
            return False, "الفاتورة ملغاة مسبقاً"
        cancelled_at = datetime.now().strftime("%Y-%m-%d")
        conn.execute(
            "UPDATE invoices SET cancelled = 1, cancelled_at = ? WHERE id = ?",
            (cancelled_at, rid),
        )
        conn.commit()
        conn.close()
        return True, "تم إلغاء الفاتورة — الرقم محفوظ ولن يُستخدم مجدداً"
    except (ValueError, Exception):
        return False, "حدث خطأ أثناء إلغاء الفاتورة"


