def _employee_name_match_key(emp_key, candidate_key):
    """مطابقة أسماء الموظفين — لا يدمج «عارف حسين» مع «عارف أبو جاهر»."""
    if not emp_key or not candidate_key:
        return False
    if emp_key == candidate_key:
        return True
    if emp_key.startswith(candidate_key + " ") or candidate_key.startswith(emp_key + " "):
        return True
    ew = emp_key.split()
    cw = candidate_key.split()
    # اسم مختصر فقط (مثل «عارف» في Excel) يطابق الاسم الكامل لموظف واحد
    if len(ew) == 1 and len(cw) > 1 and len(ew[0]) >= 2 and ew[0] == cw[0]:
        return True
    if len(cw) == 1 and len(ew) > 1 and len(cw[0]) >= 2 and cw[0] == ew[0]:
        return True
    return False


def _pick_canonical_employee_name(names):
    """الاسم الأنسب من مجموعة أسماء متطابقة (القائمة الرسمية ثم الأطول)."""
    names = [str(n).strip() for n in names if n and str(n).strip()]
    if not names:
        return ""
    if len(names) == 1:
        return _prefer_default_employee_name(names[0])
    default_by_key = {_normalize_name_key(n): n for n in _DEFAULT_EMPLOYEE_NAMES}
    for n in names:
        if _normalize_name_key(n) in default_by_key:
            return default_by_key[_normalize_name_key(n)]
    for default_name in _DEFAULT_EMPLOYEE_NAMES:
        dk = _normalize_name_key(default_name)
        for n in names:
            if _employee_name_match_key(dk, _normalize_name_key(n)):
                return default_name
    best = max(names, key=lambda x: (len(x.split()), len(x)))
    return _prefer_default_employee_name(best)


def _prefer_default_employee_name(name):
    """توسيع الاسم المختصر إلى الاسم الكامل من القائمة الرسمية إن وُجد."""
    name = (name or "").strip()
    if not name:
        return name
    key = _normalize_name_key(name)
    for default_name in _DEFAULT_EMPLOYEE_NAMES:
        if _employee_name_match_key(key, _normalize_name_key(default_name)):
            return default_name
    return name


def resolve_canonical_employee_name(name, profession=None):
    """إرجاع اسم موظف موجود إن وُجد تطابق — لتجنب التكرار عند الاستيراد."""
    name = (name or "").strip()
    if not name:
        return name
    key = _normalize_name_key(name)
    matches = []
    for existing in get_employees_list():
        if _employee_name_match_key(key, _normalize_name_key(existing)):
            matches.append(existing)
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        if profession and str(profession).strip():
            prof_key = _normalize_name_key(profession)
            prof_map = get_all_employee_professions()
            for m in matches:
                if _normalize_name_key(prof_map.get(m, "")) == prof_key:
                    return m
        for m in matches:
            if _normalize_name_key(m) == key:
                return m
        return name
    return name


def _merge_employee_alias_into(canonical_name, alias_name):
    """دمج سجل مكرر في الاسم الرسمي ثم حذف المكرر."""
    if not canonical_name or not alias_name or canonical_name == alias_name:
        return
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT profession FROM employees WHERE employee_name=?", (alias_name,)
    ).fetchone()
    if row and row[0] and str(row[0]).strip():
        canon_prof = conn.execute(
            "SELECT profession FROM employees WHERE employee_name=?", (canonical_name,)
        ).fetchone()
        if not canon_prof or not str(canon_prof[0] or "").strip():
            conn.execute(
                "UPDATE employees SET profession=? WHERE employee_name=?",
                (str(row[0]).strip(), canonical_name),
            )
    sal_row = conn.execute(
        "SELECT default_salary FROM employee_salary_defaults WHERE employee_name=?", (alias_name,)
    ).fetchone()
    if sal_row and float(sal_row[0] or 0) > 0:
        conn.execute(
            """INSERT OR REPLACE INTO employee_salary_defaults (employee_name, default_salary)
               VALUES (?,?)""",
            (canonical_name, float(sal_row[0])),
        )
    for table in ("salaries", "absences"):
        conn.execute(
            f"UPDATE {table} SET employee_name=? WHERE employee_name=?",
            (canonical_name, alias_name),
        )
    conn.execute("DELETE FROM employee_salary_defaults WHERE employee_name=?", (alias_name,))
    conn.execute("DELETE FROM employees WHERE employee_name=?", (alias_name,))
    conn.commit()
    conn.close()


def dedupe_employees_list():
    """دمج الموظفين المكررين (حسين إمام / حسين امام ...) في سجل واحد."""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("SELECT employee_name FROM employees ORDER BY employee_name").fetchall()
    conn.close()
    names = [r[0] for r in rows]
    used = set()
    groups = []
    for i, n1 in enumerate(names):
        if n1 in used:
            continue
        group = [n1]
        used.add(n1)
        k1 = _normalize_name_key(n1)
        for n2 in names[i + 1:]:
            if n2 in used:
                continue
            if _employee_name_match_key(k1, _normalize_name_key(n2)):
                group.append(n2)
                used.add(n2)
        groups.append(group)

    merged = 0
    for group in groups:
        if len(group) < 2:
            continue
        canonical = _pick_canonical_employee_name(group)
        for alias in group:
            if alias != canonical:
                _merge_employee_alias_into(canonical, alias)
                merged += 1
    _invalidate_employee_name_keys_cache()
    return merged


def _lookup_by_employee_name(emp_name, data_map):
    """data_map: normalized_key -> value. إرجاع القيمة الأنسب لاسم الموظف."""
    key = _normalize_name_key(emp_name)
    if not key:
        return None
    if key in data_map:
        return data_map[key]
    for dk, val in data_map.items():
        if _employee_name_match_key(key, dk):
            return val
    return None


def sync_employee_list_from_salaries():
    """ملء المسمى والراتب في قائمة الموظفين من ملفات الرواتب المستوردة."""
    conn = sqlite3.connect(DB_PATH)
    sal_rows = conn.execute(
        """SELECT employee_name, actual_salary, month, id FROM salaries
           WHERE employee_name IS NOT NULL AND TRIM(employee_name) != ''
           ORDER BY month DESC, id DESC"""
    ).fetchall()
    prof_rows = conn.execute(
        """SELECT employee_name, profession FROM employees
           WHERE profession IS NOT NULL AND TRIM(COALESCE(profession, '')) != ''"""
    ).fetchall()
    conn.close()

    sal_map = {}
    for name, actual, _month, _rid in sal_rows:
        k = _normalize_name_key(name)
        if k and k not in sal_map and float(actual or 0) > 0:
            sal_map[k] = float(actual)

    prof_map = {}
    for name, prof in prof_rows:
        k = _normalize_name_key(name)
        if k and prof and str(prof).strip():
            prof_map[k] = str(prof).strip()

    updated = 0
    for emp_name in get_employees_list():
        sal = _lookup_by_employee_name(emp_name, sal_map)
        prof = _lookup_by_employee_name(emp_name, prof_map)
        changed = False
        if prof:
            save_employee_profession(emp_name, prof)
            changed = True
        if sal is not None and sal > 0:
            save_employee_default_salary(emp_name, sal)
            changed = True
        if changed:
            updated += 1
    _invalidate_employee_name_keys_cache()
    return updated


def get_employee_absences_for_month(employee_name, month_val):
    """استرجاع إجمالي أيام الغياب للموظف في الشهر المحدد (YYYY-MM)."""
    if not employee_name or not month_val:
        return 0
    ym = normalize_salary_month(month_val)
    if not ym or len(ym) < 7 or "-" not in ym:
        return 0
    y, m = ym[:4], ym[5:7]
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            """SELECT COALESCE(SUM(days), 0) FROM absences
               WHERE employee_name = ? AND strftime('%Y', date) = ? AND strftime('%m', date) = ?""",
            (employee_name.strip(), y, m),
        ).fetchone()
        total = int(row[0] or 0) if row else 0
    except Exception:
        total = 0
    conn.close()
    return total


def insert_absence(employee_name, date, days, details):
    conn = sqlite3.connect(DB_PATH)
    conn.execute("""INSERT INTO absences (employee_name, date, days, details)
        VALUES (?,?,?,?)""", (employee_name or "", date or "", int(days or 0), details or ""))
    conn.commit()
    conn.close()


def get_employee_paid_for_month(employee_name, month_val, exclude_id=None):
    """استرجاع إجمالي المبلغ المدفوع للموظف في الشهر المحدد (دفعات سابقة)."""
    if not employee_name or not month_val:
        return 0
    ym = normalize_salary_month(month_val)
    if not ym:
        return 0
    conn = sqlite3.connect(DB_PATH)
    try:
        sql = """SELECT COALESCE(SUM(amount_paid), 0) FROM salaries
               WHERE employee_name = ? AND month = ?"""
        args = [employee_name.strip(), ym]
        if exclude_id:
            sql += " AND id != ?"
            args.append(int(exclude_id))
        row = conn.execute(sql, args).fetchone()
        return float(row[0] or 0)
    except Exception:
        return 0
    finally:
        conn.close()


def _salary_note_entry(date_str, note_str):
    """صيغة ملاحظة واحدة مع تاريخ الدفع."""
    d = str(date_str or "").strip()[:10]
    n = str(note_str or "").strip()
    if d and n:
        return f"{d}: {n}"
    return d or n


def _salary_payment_dates_display(dates_str):
    """عرض تواريخ الدفع (دفعات الإيداع) بشكل موحّد."""
    raw = str(dates_str or "").strip()
    if not raw:
        return ""
    parts = re.split(r"\s*[|+]\s*", raw)
    out = []
    for p in parts:
        p = p.strip()
        if not p:
            continue
        if re.match(r"^\d{4}-\d{2}-\d{2}$", p[:10]):
            out.append(p[:10])
            continue
        m = re.match(r"^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$", p)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                out.append(datetime(y, mo, d).strftime("%Y-%m-%d"))
                continue
            except ValueError:
                pass
        out.append(p)
    return " | ".join(dict.fromkeys(out))


def _salary_date_to_input(date_str):
    """تحويل التاريخ إلى YYYY-MM-DD لحقل type=date."""
    s = str(date_str or "").strip()
    if not s:
        return ""
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s[:10]):
        return s[:10]
    m = re.match(r"^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$", s)
    if m:
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return datetime(y, mo, d).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return s[:10]


def _salary_date_display(date_str):
    """عرض التاريخ بصيغة DD/MM/YYYY."""
    iso = _salary_date_to_input(date_str)
    if not iso or not re.match(r"^\d{4}-\d{2}-\d{2}$", iso):
        return str(date_str or "").strip()
    y, mo, d = iso.split("-")
    return f"{d}/{mo}/{y}"


def _salary_notes_text_only(notes, dates_str=""):
    """نص الملاحظات فقط بدون تواريخ الدفع."""
    notes_s = str(notes or "").strip()
    if not notes_s:
        return ""
    if re.search(r"\d{4}-\d{2}-\d{2}\s*:", notes_s):
        parts = []
        for seg in notes_s.split("|"):
            seg = seg.strip()
            m = re.match(r"^\d{4}-\d{2}-\d{2}\s*:\s*(.*)$", seg)
            if m and m.group(1).strip():
                parts.append(m.group(1).strip())
            elif seg and not re.match(r"^\d{4}-\d{2}-\d{2}$", seg[:10]):
                parts.append(seg)
        return " | ".join(parts)
    dates_norm = _salary_payment_dates_display(dates_str)
    if dates_norm and notes_s.replace(" ", "") == dates_norm.replace(" ", ""):
        return ""
    if re.fullmatch(r"[\d/\-\+\|\s]+", notes_s.replace(" ", "")):
        return ""
    return notes_s


def _salary_notes_with_dates(notes, dates_str):
    """عرض الملاحظات مرتبطة بتواريخ الدفع (للجدول والتعديل)."""
    notes_s = str(notes or "").strip()
    dates_s = str(dates_str or "").strip()
    if not notes_s and not dates_s:
        return ""
    if notes_s and re.search(r"\d{4}-\d{2}-\d{2}\s*:", notes_s):
        return notes_s
    if not dates_s:
        return notes_s
    if not notes_s:
        return dates_s
    date_parts = [d.strip()[:10] for d in dates_s.split("|") if d.strip()]
    note_parts = [n.strip() for n in notes_s.split("|") if n.strip()]
    if date_parts and note_parts and len(date_parts) == len(note_parts):
        return " | ".join(_salary_note_entry(d, n) for d, n in zip(date_parts, note_parts))
    if len(date_parts) == 1 and len(note_parts) == 1:
        return _salary_note_entry(date_parts[0], note_parts[0])
    return f"{notes_s} ({dates_s})"


def _salary_payment_dates_list(dates_str):
    """قائمة تواريخ الدفع من حقل date (تواريخ ISO صالحة فقط)."""
    disp = _salary_payment_dates_display(dates_str)
    if not disp:
        return []
    return [
        d.strip()[:10]
        for d in disp.split("|")
        if d.strip() and _salary_is_valid_payment_date(d.strip()[:10])
    ]


def _salary_is_valid_payment_date(d):
    """تاريخ دفعة بصيغة YYYY-MM-DD."""
    ds = str(d or "").strip()[:10]
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", ds):
        return False
    try:
        datetime.strptime(ds, "%Y-%m-%d")
        return True
    except ValueError:
        return False


def _salary_payments_effective_entries(log_entries, amount_paid=0):
    """الدفعات الفعلية للعرض والعد — تاريخ صالح ومبلغ أو وضع قديم مع إجمالي."""
    if not log_entries:
        return []
    paid_total = float(amount_paid or 0)
    has_null = any(e.get("amount") is None for e in log_entries)
    has_positive = any(
        e.get("amount") is not None and float(e.get("amount") or 0) > 0.0005
        for e in log_entries
    )
    if has_null and not has_positive and paid_total > 0.0005:
        return _salary_payments_log_sort(
            [e for e in log_entries if _salary_is_valid_payment_date(e.get("date"))]
        )
    out = []
    for e in log_entries:
        d = (e.get("date") or "").strip()[:10]
        if not _salary_is_valid_payment_date(d):
            continue
        amt = e.get("amount")
        if amt is not None:
            if float(amt or 0) > 0.0005:
                out.append(e)
        elif paid_total > 0.0005:
            out.append(e)
    return _salary_payments_log_sort(out)


def _salary_payments_log_parse(log_json):
    if not log_json or not str(log_json).strip():
        return []
    try:
        data = json.loads(log_json)
        if isinstance(data, list):
            return data
    except (json.JSONDecodeError, TypeError, ValueError):
        pass
    return []


def _salary_payments_log_serialize(log):
    if not log:
        return ""
    return json.dumps(log, ensure_ascii=False)


def _salary_payments_log_from_legacy(date_str, amount_paid, notes=""):
    """بناء سجل الدفعات من الحقول القديمة (للترحيل)."""
    dates = _salary_payment_dates_list(date_str)
    note_text = _salary_notes_text_only(notes, date_str)
    paid = float(amount_paid or 0)
    if not dates:
        if paid > 0.0005:
            return [{"date": "", "amount": paid, "note": note_text}]
        return []
    if len(dates) == 1:
        if paid > 0.0005:
            return [{"date": dates[0], "amount": paid, "note": note_text}]
        return []
    if paid <= 0.0005:
        return []
    note_by_date = {}
    notes_s = str(notes or "").strip()
    if notes_s and re.search(r"\d{4}-\d{2}-\d{2}\s*:", notes_s):
        for seg in notes_s.split("|"):
            seg = seg.strip()
            m = re.match(r"^(\d{4}-\d{2}-\d{2})\s*:\s*(.*)$", seg)
            if m:
                note_by_date[m.group(1)] = m.group(2).strip()
    return [{"date": d, "amount": None, "note": note_by_date.get(d, "")} for d in sorted(dates)]


def _salary_payments_log_sort(log):
    """ترتيب الدفعات من الأقدم إلى الأحدث."""
    if not log:
        return []
    return sorted(log, key=lambda e: str(e.get("date") or "")[:10])


def _salary_payments_log_append(log, date_str, amount, note=""):
    log = list(log or [])
    d = str(date_str or "").strip()[:10]
    if not d:
        return _salary_payments_log_sort(log)
    log.append({"date": d, "amount": float(amount or 0), "note": str(note or "").strip()})
    return _salary_payments_log_sort(log)


def _salary_payments_log_merge(entries):
    return _salary_payments_log_sort(entries)


def _salary_payments_log_matches(log, date_str, total_paid):
    if not log:
        return False
    dates = _salary_payment_dates_list(date_str)
    log_dates = [(e.get("date") or "")[:10] for e in log if e.get("date")]
    if dates and log_dates and dates != log_dates:
        return False
    amounts = [e.get("amount") for e in log if e.get("amount") is not None]
    if not amounts:
        return True
    log_sum = sum(float(a) for a in amounts)
    return abs(log_sum - float(total_paid or 0)) < 0.001


