def _salary_payment_card_html(date, amount=None, note="", date_only=False):
    """بطاقة دفعة واحدة (عرض فقط): تاريخ مقابل المبلغ."""
    d = str(date or "").strip()
    n = str(note or "").strip()
    if amount is not None and d:
        parts = [
            f'<div class="sal-pay-card sal-pay-row-readonly">',
            f'<span class="sal-pay-card-date">{_esc(_salary_date_display(d))}</span>',
            f'<span class="sal-pay-card-amt">{_fmt_salary_amount(amount)} {CURRENCY}</span>',
            f"</div>",
        ]
        if n:
            parts.insert(-1, f'<div class="sal-pay-card-note">{_esc(n)}</div>')
        return "".join(parts)
    cls = "sal-pay-card sal-pay-card-date-only" if date_only else "sal-pay-card"
    parts = [f'<div class="{cls}">']
    if d:
        parts.append(f'<div class="sal-pay-card-date">{_esc(_salary_date_display(d))}</div>')
    if n:
        parts.append(f'<div class="sal-pay-card-note">{_esc(n)}</div>')
    parts.append("</div>")
    return "".join(parts)


def _salary_payments_total_card_html(total):
    return (
        f'<div class="sal-pay-card sal-pay-card-total">'
        f'<div class="sal-pay-card-amt">الإجمالي: {_fmt_salary_amount(total)} {CURRENCY}</div>'
        f"</div>"
    )


def _salary_payments_detail_html(log_json, date_str, total):
    """عرض تفصيلي كبطاقات: مبلغ+تاريخ لكل دفعة، أو تواريخ+إجمالي للبيانات القديمة."""
    log = _salary_payments_log_for_display(log_json, date_str, total)
    if not log:
        return ""
    cards = []
    has_null = any(e.get("amount") is None for e in log)
    has_amount = any(e.get("amount") is not None for e in log)
    if has_null and not has_amount:
        for e in log:
            d = (e.get("date") or "").strip()
            if d:
                cards.append(_salary_payment_card_html(d, date_only=True))
        tot = float(total or 0)
        if tot > 0:
            cards.append(_salary_payments_total_card_html(tot))
    else:
        for e in log:
            d = (e.get("date") or "").strip()
            amt = e.get("amount")
            note = e.get("note") or ""
            if amt is not None and d:
                cards.append(_salary_payment_card_html(d, amt, note))
            elif d:
                cards.append(_salary_payment_card_html(d, date_only=True))
        if has_null and float(total or 0) > 0:
            cards.append(_salary_payments_total_card_html(total))
    return f'<div class="sal-pay-cards">{"".join(cards)}</div>'


def _salary_payments_log_for_display(log_json, date_str, total):
    """تحضير سجل الدفعات للعرض أو التعديل (مرتب زمنياً)."""
    log = _salary_payments_log_parse(log_json)
    if not log:
        log = _salary_payments_log_from_legacy(date_str, total, "")
    return _salary_payments_log_sort(log)


