def _invoice_effective_remaining_sql():
    """تعبير SQL للمتبقي الفعلي (يدعم السجلات ذات remaining الفارغ)."""
    return "COALESCE(remaining, total_amount - COALESCE(down_payment, 0), total_amount, 0)"


def fetch_invoices(limit=100, invoice_filter=None, month_filter=None, paid_filter=None):
    """استرجاع فواتير المبيعات - إن وُجد invoice_filter أو month_filter أو paid_filter يُفلتر بها"""
    conn = sqlite3.connect(DB_PATH)
    conditions, args = [], []
    if invoice_filter and str(invoice_filter).strip():
        inv_q = str(invoice_filter).strip()
        conditions.append("TRIM(invoice_number) LIKE ?")
        args.append("%" + inv_q + "%")
    if month_filter and str(month_filter).strip():
        conditions.append("substr(date, 1, 7) = ?")
        args.append(str(month_filter).strip())
    pf = _normalize_paid_filter(paid_filter)
    rem_sql = _invoice_effective_remaining_sql()
    if pf == "paid":
        conditions.append(f"({rem_sql}) <= 0")
        conditions.append(_INVOICE_ACTIVE_SQL)
    elif pf == "unpaid":
        conditions.append(f"({rem_sql}) > 0")
        conditions.append(_INVOICE_ACTIVE_SQL)
    where = " AND ".join(conditions) if conditions else "1=1"
    q = f"""SELECT id, date, invoice_number, customer_name, total_amount, down_payment, remaining, receipt_number, payment_method, notes,
        COALESCE(cancelled, 0), COALESCE(cancelled_at, '')
        FROM invoices WHERE {where} ORDER BY {INVOICES_ORDER_BY} LIMIT ?"""
    rows = conn.execute(q, args + [limit]).fetchall()
    conn.close()
    return rows


def _customer_summary_cards_html(rows):
    """بطاقات ملخّص عن العميل من قائمة فواتيره الكاملة."""
    if not rows:
        return ""
    rows = [r for r in rows if not _invoice_is_cancelled(r)]
    if not rows:
        return ""
    import datetime as _dt

    count = len(rows)
    total = sum(float(r[4] or 0) for r in rows)
    remaining = sum(float(r[6] or 0) for r in rows)
    paid = total - remaining
    avg = total / count if count else 0.0
    paid_count = sum(1 for r in rows if float(r[6] or 0) <= 0.001)

    dates = []
    for r in rows:
        ds = str(r[1] or "").strip().split(" ")[0].split("T")[0]
        for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%Y/%m/%d"):
            try:
                dates.append(_dt.datetime.strptime(ds, fmt).date())
                break
            except (ValueError, TypeError):
                continue
    span_label = "—"
    freq_label = "—"
    freq_hint = "متوسط الفترة بين الطلبات"
    if len(dates) >= 2:
        dates.sort()
        first_d, last_d = dates[0], dates[-1]
        span_days = (last_d - first_d).days
        months = max(1.0, span_days / 30.4375)
        per_month = count / months
        avg_gap = span_days / (count - 1) if count > 1 else 0
        span_label = f"{first_d.isoformat()} ← {last_d.isoformat()}"
        if avg_gap >= 1:
            freq_label = f"كل {avg_gap:.0f} يوم"
        else:
            freq_label = "متكرر يومياً"
        freq_hint = f"بمعدّل {per_month:.1f} طلب/شهر"
    elif len(dates) == 1:
        span_label = dates[0].isoformat()
        freq_label = "طلب واحد"

    repeat_label = "عميل متكرر" if count > 1 else "عميل لمرة واحدة"
    repeat_hint = f"{count} طلب — {paid_count} مدفوعة بالكامل"

    cards = [
        ("fa-file-invoice", "#2d5a87", "عدد الفواتير", f"{count}", "إجمالي عدد الطلبات"),
        ("fa-coins", "#28a745", "إجمالي قيمة الفواتير", f"{total:,.3f} {CURRENCY}", "مجموع قيمة كل الفواتير"),
        ("fa-scale-balanced", "#6f42c1", "متوسط قيمة الفاتورة", f"{avg:,.3f} {CURRENCY}", "إجمالي القيمة ÷ عدد الفواتير"),
        ("fa-hand-holding-dollar", "#17a2b8", "إجمالي المدفوع", f"{paid:,.3f} {CURRENCY}", "ما تم تحصيله من العميل"),
        ("fa-clock", "#dc3545", "إجمالي المتبقي", f"{remaining:,.3f} {CURRENCY}", "المبالغ غير المسدّدة"),
        ("fa-rotate", "#fd7e14", "تكرار الطلب", freq_label, freq_hint),
        ("fa-user-check", "#20c997", repeat_label, f"{paid_count}/{count}", repeat_hint),
        ("fa-calendar-days", "#e83e8c", "فترة التعامل", span_label, "من أول فاتورة إلى آخر فاتورة"),
    ]
    out = [
        '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px;margin-bottom:18px">'
    ]
    for icon, color, label, value, hint in cards:
        out.append(
            f'<div style="background:#fff;border:1px solid #e3e8ef;border-right:4px solid {color};'
            f'border-radius:10px;padding:13px 15px;box-shadow:0 2px 8px rgba(0,0,0,.06)">'
            f'<div style="display:flex;align-items:center;gap:9px;margin-bottom:7px">'
            f'<i class="fa-solid {icon}" style="color:{color};font-size:18px"></i>'
            f'<span style="font-size:12.5px;color:#667085;font-weight:600">{_esc(label)}</span></div>'
            f'<div style="font-size:1.12em;font-weight:800;color:#1e3a5f;direction:rtl;line-height:1.3">{_esc(value)}</div>'
            f'<div style="font-size:11px;color:#9aa3b2;margin-top:4px">{_esc(hint)}</div>'
            f'</div>'
        )
    out.append("</div>")
    return "".join(out)


def fetch_invoices_by_customer(customer_name, limit=2000):
    """استرجاع جميع فواتير عميل معيّن (مطابقة جزئية لاسم العميل)."""
    name = str(customer_name or "").strip()
    if not name:
        return []
    conn = sqlite3.connect(DB_PATH)
    q = f"""SELECT id, date, invoice_number, customer_name, total_amount, down_payment,
                   {_invoice_effective_remaining_sql()} AS eff_remaining, receipt_number, payment_method,
                   COALESCE(cancelled, 0), COALESCE(cancelled_at, '')
            FROM invoices
            WHERE TRIM(LOWER(customer_name)) LIKE ?
            ORDER BY {INVOICES_ORDER_BY} LIMIT ?"""
    rows = conn.execute(q, ("%" + name.lower() + "%", limit)).fetchall()
    conn.close()
    return rows


