def _sync_invoice_amounts_from_payments(invoice_number, *, allow_reduce=False):
    """مزامنة المقدم والمتبقي وتاريخ الدفع من جدول payments.

    افتراضياً لا نخفّض المبلغ المدفوع المسجّل على الفاتورة إذا كان جدول الدفعات ناقصاً،
    حتى لا تُمسَح حالة «مدفوعة» للفواتير القديمة بدون صفوف payments.
    """
    inv_no = str(invoice_number or "").strip()
    if not inv_no:
        return
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT id, total_amount, COALESCE(down_payment, 0), COALESCE(remaining, 0), COALESCE(payment_date, '') "
        "FROM invoices WHERE TRIM(invoice_number)=? LIMIT 1",
        (inv_no,),
    ).fetchone()
    if not row:
        conn.close()
        return
    inv_id, total = row[0], float(row[1] or 0)
    cur_down, cur_rem = float(row[2] or 0), float(row[3] or 0)
    cur_pdate = str(row[4] or "")
    pays = conn.execute(
        "SELECT date, amount FROM payments WHERE TRIM(invoice_number)=? ORDER BY date ASC, id ASC",
        (inv_no,),
    ).fetchall()
    paid_from_pays = sum(float(p[1] or 0) for p in pays)
    if not allow_reduce and paid_from_pays + 0.001 < cur_down:
        conn.close()
        return
    paid = paid_from_pays
    remaining = max(0.0, total - paid)
    dates = ", ".join(str(p[0]).strip() for p in pays if p[0])
    if not dates and cur_pdate and abs(paid - cur_down) <= 0.001:
        dates = cur_pdate
    conn.execute(
        "UPDATE invoices SET down_payment=?, remaining=?, payment_date=? WHERE id=?",
        (paid, remaining, dates, inv_id),
    )
    conn.commit()
    conn.close()


def _invoice_paid_restore_map_path():
    return os.path.join(_app_base_dir(), "invoice_paid_restore_map.json")


def _invoice_paid_restore_flag_path():
    return os.path.join(_DATA_DIR, ".invoice_paid_restore_v1_done")


def restore_wiped_invoice_paid_amounts():
    """استعادة حالة المدفوع للفواتير التي مُسحت خطأً عبر مزامنة payments الناقصة."""
    flag = _invoice_paid_restore_flag_path()
    if os.path.isfile(flag):
        return 0
    map_path = _invoice_paid_restore_map_path()
    if not os.path.isfile(map_path):
        return 0
    try:
        import json
        with open(map_path, "r", encoding="utf-8") as f:
            mapping = json.load(f)
    except Exception:
        return 0
    if not isinstance(mapping, dict) or not mapping:
        return 0
    conn = sqlite3.connect(DB_PATH)
    fixed = 0
    try:
        for inv_no, data in mapping.items():
            inv_no = str(inv_no or "").strip()
            if not inv_no or not isinstance(data, dict):
                continue
            map_down = float(data.get("down") or 0)
            map_rem = float(data.get("remaining") or 0)
            if map_down <= 0.001 and map_rem > 0.001:
                continue
            row = conn.execute(
                "SELECT id, COALESCE(total_amount,0), COALESCE(down_payment,0), COALESCE(remaining,0), "
                "COALESCE(payment_method,''), COALESCE(receipt_number,''), COALESCE(payment_date,'') "
                "FROM invoices WHERE TRIM(invoice_number)=? AND COALESCE(cancelled,0)=0 LIMIT 1",
                (inv_no,),
            ).fetchone()
            if not row:
                continue
            inv_id = row[0]
            total = float(row[1] or 0)
            cur_down = float(row[2] or 0)
            cur_rem = float(row[3] or 0)
            looks_wiped = (
                cur_down <= 0.001
                and cur_rem > 0.001
                and abs(cur_rem - total) <= 0.001
            )
            under_paid = cur_down + 0.001 < map_down
            if not (looks_wiped or under_paid):
                continue
            new_down = map_down
            new_rem = map_rem if map_rem >= 0 else max(0.0, total - map_down)
            # لا نرفع المتبقي فوق القيمة الحالية إن كانت أقل (أدق)
            if cur_rem + 0.001 < new_rem and cur_down >= map_down - 0.001:
                continue
            pdate = str(data.get("payment_date") or row[6] or "")
            pmethod = str(data.get("payment_method") or "").strip() or str(row[4] or "")
            receipt = str(data.get("receipt_number") or "").strip() or str(row[5] or "")
            conn.execute(
                "UPDATE invoices SET down_payment=?, remaining=?, payment_date=?, "
                "payment_method=COALESCE(NULLIF(TRIM(payment_method),''), ?), "
                "receipt_number=COALESCE(NULLIF(TRIM(receipt_number),''), ?) WHERE id=?",
                (new_down, new_rem, pdate, pmethod, receipt, inv_id),
            )
            fixed += 1
        conn.commit()
    finally:
        conn.close()
    try:
        os.makedirs(_DATA_DIR, exist_ok=True)
        with open(flag, "w", encoding="utf-8") as f:
            f.write(f"fixed={fixed}\n")
    except Exception:
        pass
    return fixed


def _sync_invoice_payment_date_from_payments(invoice_number):
    """مزامنة تاريخ الدفع (يستدعي المزامنة الكاملة)."""
    _sync_invoice_amounts_from_payments(invoice_number)


def _invoice_payments_detail_html(
    entries, *, invoice_id=None, back="", force_edit=False, edit_page=False
):
    """عرض تواريخ ومبالغ الدفعات — التعديل في صفحة تعديل الفاتورة فقط."""
    if not entries:
        return '<span class="inv-pay-empty">—</span>'
    pay_with_id = [e for e in entries if e.get("id")]
    can_edit = (
        edit_page
        and pay_with_id
        and invoice_id
        and back
        and (force_edit or len(entries) >= 2)
    )
    if can_edit:
        rows_html = []
        idx = 0
        for e in entries:
            pid = e.get("id")
            iso = _salary_date_to_input(e.get("date") or "") or str(e.get("date") or "").strip()[:10]
            amt = float(e.get("amount") or 0)
            if pid:
                cancel_href = f"/delete-payment?id={int(pid)}&from={quote(back)}"
                rows_html.append(
                    f'<div class="inv-pay-edit-row">'
                    f'<input type="hidden" name="pay_id_{idx}" value="{int(pid)}">'
                    f'<input type="date" name="pay_date_{idx}" value="{_esc(iso)}" '
                    f'class="inv-pay-date-inp" required>'
                    f'<input type="number" step="0.001" min="0.001" name="pay_amt_{idx}" '
                    f'value="{amt:.3f}" class="inv-pay-amt-inp" required>'
                    f'<a href="{cancel_href}" class="inv-pay-cancel-btn" title="إلغاء دفعة" '
                    f'aria-label="إلغاء دفعة" '
                    f"onclick=\"return confirm('إلغاء هذه الدفعة؟');\">"
                    f'<i class="fa-solid fa-xmark"></i> إلغاء</a>'
                    f"</div>"
                )
                idx += 1
            else:
                disp = _salary_date_display(e.get("date") or "") or "—"
                rows_html.append(
                    f'<div class="sal-pay-card sal-pay-row-readonly inv-pay-legacy-row">'
                    f'<span class="sal-pay-card-date">{_esc(disp)}</span>'
                    f'<span class="sal-pay-card-amt">{amt:.3f} {CURRENCY}</span></div>'
                )
        save_btn = (
            '<button type="submit" class="inv-pay-save-btn-full">'
            '<i class="fa-solid fa-floppy-disk"></i> حفظ الدفعات</button>'
        )
        return (
            f'<form class="inv-pay-dates-form inv-pay-dates-form--page" '
            f'method="POST" action="/edit-invoice-payment-dates">'
            f'<input type="hidden" name="invoice_id" value="{int(invoice_id)}">'
            f'<input type="hidden" name="pay_count" value="{idx}">'
            f'<input type="hidden" name="back" value="{_esc(back)}">'
            + "".join(rows_html)
            + save_btn
            + "</form>"
        )
    cards = []
    for e in entries:
        d = (e.get("date") or "").strip()
        amt = e.get("amount")
        if d and amt is not None:
            cards.append(_salary_payment_card_html(d, amt))
        elif d:
            cards.append(_salary_payment_card_html(d, date_only=True))
        elif amt is not None and float(amt) > 0:
            cards.append(
                f'<div class="sal-pay-card sal-pay-card-date-only">'
                f'<div class="sal-pay-card-amt">{float(amt):.3f} {CURRENCY}</div></div>'
            )
    if not cards:
        return '<span class="inv-pay-empty">—</span>'
    return f'<div class="sal-pay-cards inv-pay-dates">{"".join(cards)}</div>'


def _invoice_edit_payments_section_html(invoice_id, invoice_number, down_payment, back):
    """قسم الدفعات في صفحة تعديل الفاتورة."""
    inv_no = str(invoice_number or "").strip()
    pay_map = fetch_payments_by_invoices([inv_no])
    legacy_map = fetch_invoice_legacy_pay_meta([inv_no])
    entries = _invoice_payments_entries_for(inv_no, down_payment, pay_map, legacy_map)
    db_rows = pay_map.get(inv_no, [])
    pay_url = f"/pay-invoice?id={int(invoice_id)}&back={quote(back)}"

    if not entries:
        return (
            '<div class="form-group inv-edit-payments">'
            '<label><i class="fa-solid fa-money-bill-wave"></i> الدفعات</label>'
            f'<p class="inv-edit-payments-hint">لا توجد دفعات مسجلة. '
            f'<a href="{pay_url}">سجّل دفعة</a></p></div>'
        )

    body = _invoice_payments_detail_html(
        entries,
        invoice_id=invoice_id,
        back=back,
        force_edit=bool(db_rows),
        edit_page=True,
    )
    hint = (
        '<p class="inv-edit-payments-hint">عدّل تاريخ ومبلغ كل دفعة ثم اضغط «حفظ الدفعات»، '
        "أو ألغِ دفعة. يُحدَّث المقدم والمتبقي تلقائياً.</p>"
        if db_rows
        else ""
    )
    add_link = (
        f'<p class="inv-edit-payments-add"><a href="{pay_url}">'
        f'<i class="fa-solid fa-plus"></i> إضافة دفعة</a></p>'
        if db_rows
        else ""
    )
    return (
        f'<div class="form-group inv-edit-payments">'
        f'<label><i class="fa-solid fa-money-bill-wave"></i> الدفعات ({len(entries)})</label>'
        f"{hint}{body}{add_link}</div>"
    )


def fetch_expenses(limit=100, expense_type=None, month_filter=None):
    """استرجاع المصروفات (id, date, ...) - يمكن تحديد النوع والشهر"""
    conn = sqlite3.connect(DB_PATH)
    month_filter = str(month_filter or "").strip() or None
    if expense_type and month_filter:
        rows = conn.execute(
            """SELECT id, date, voucher_number, expense_type, description, amount, invoice_number, supplier_name
               FROM expenses WHERE COALESCE(expense_type,'') = ? AND substr(date,1,7) = ?
               ORDER BY date ASC, id ASC LIMIT ?""",
            (expense_type, month_filter, limit),
        ).fetchall()
    elif expense_type:
        rows = conn.execute(
            """SELECT id, date, voucher_number, expense_type, description, amount, invoice_number, supplier_name
               FROM expenses WHERE COALESCE(expense_type,'') = ?
               ORDER BY date ASC, id ASC LIMIT ?""",
            (expense_type, limit),
        ).fetchall()
    elif month_filter:
        rows = conn.execute(
            """SELECT id, date, voucher_number, expense_type, description, amount, invoice_number, supplier_name
               FROM expenses WHERE COALESCE(expense_type,'') IN ('نقدية','آجلة') AND substr(date,1,7) = ?
               ORDER BY date ASC, id ASC LIMIT ?""",
            (month_filter, limit),
        ).fetchall()
    else:
        rows = conn.execute(
            """SELECT id, date, voucher_number, expense_type, description, amount, invoice_number, supplier_name
               FROM expenses WHERE COALESCE(expense_type,'') IN ('نقدية','آجلة')
               ORDER BY date ASC, id ASC LIMIT ?""",
            (limit,),
        ).fetchall()
    conn.close()
    return rows


def fetch_deferred_expenses_unpaid(limit=100, month_filter=None):
    """المصروفات الآجلة: غير المدفوعة بالكامل، أو كل آجلة في شهر محدد."""
    conn = sqlite3.connect(DB_PATH)
    month_filter = str(month_filter or "").strip() or None
    base_sql = """SELECT e.id, e.date, e.voucher_number, e.expense_type, e.description, e.amount,
        e.invoice_number, e.supplier_name, COALESCE(i.total_amount, e.amount) as invoice_value,
        COALESCE(e.paid_amount, 0) as paid_amount,
        COALESCE(e.remaining_amount, COALESCE(i.total_amount, e.amount)) as remaining_amount
        FROM expenses e
        LEFT JOIN invoices i ON e.invoice_number = i.invoice_number
        WHERE COALESCE(e.expense_type,'') = 'آجلة'"""
    if month_filter:
        rows = conn.execute(
            base_sql + " AND substr(e.date,1,7) = ? ORDER BY e.date ASC, e.id ASC LIMIT ?",
            (month_filter, limit),
        ).fetchall()
    else:
        rows = conn.execute(
            base_sql + " AND COALESCE(e.remaining_amount, 1) > 0 ORDER BY e.date ASC, e.id ASC LIMIT ?",
            (limit,),
        ).fetchall()
    conn.close()
    return rows

