def update_invoice(invoice_id, date, invoice_number, customer_name, total_amount, down_payment, receipt_number, payment_method="", notes="", payment_date=""):
    """تحديث بيانات فاتورة"""
    inv_no = str(invoice_number or "").strip()
    if _invoice_number_taken(inv_no, exclude_id=invoice_id):
        raise ValueError(f"رقم الفاتورة {inv_no} مستخدم مسبقاً")
    remaining = total_amount - down_payment
    conn = sqlite3.connect(DB_PATH)
    conn.execute("""UPDATE invoices SET date = ?, invoice_number = ?, customer_name = ?, 
        total_amount = ?, down_payment = ?, remaining = ?, receipt_number = ?, payment_method = ?, payment_date = ?, notes = ?
        WHERE id = ? AND COALESCE(cancelled, 0) = 0""", (date, inv_no, customer_name, total_amount, down_payment, remaining, receipt_number, payment_method or "", payment_date or "", notes or "", invoice_id))
    if conn.total_changes == 0:
        conn.close()
        raise ValueError("لا يمكن تعديل فاتورة ملغاة")
    conn.commit()
    conn.close()

def update_payment(payment_id, date, invoice_number, customer_name, amount, receipt_number):
    """تحديث بيانات دفعة"""
    conn = sqlite3.connect(DB_PATH)
    conn.execute("""UPDATE payments SET date = ?, invoice_number = ?, customer_name = ?, 
        amount = ?, receipt_number = ? WHERE id = ?""", 
        (date, invoice_number, customer_name, amount, receipt_number, payment_id))
    conn.commit()
    conn.close()

def convert_cash_expense_to_deferred(expense_id):
    """تحويل مصروف نقدي إلى مصروف آجل."""
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        """SELECT id, date, amount, description, invoice_number, supplier_name, COALESCE(expense_type,'')
           FROM expenses WHERE id = ?""",
        (expense_id,),
    ).fetchone()
    if not row:
        conn.close()
        return False, "المصروف غير موجود"
    exp_type = str(row[6] or "").strip()
    if exp_type == "آجلة":
        conn.close()
        return False, "المصروف مسجل بالفعل كمصروف آجل"
    if exp_type and exp_type != "نقدية":
        conn.close()
        return False, "لا يمكن تحويل هذا النوع من المصروف"
    amount = float(row[2] or 0)
    conn.execute(
        """UPDATE expenses SET expense_type = 'آجلة', paid_amount = 0, remaining_amount = ?,
           payment_date = '', payment_method = '' WHERE id = ?""",
        (amount, expense_id),
    )
    conn.commit()
    conn.close()
    try:
        upsert_company_statement_from_expense(
            row[5], row[4], row[1], amount, paid_amount=0.0, description=row[3] or ""
        )
    except Exception:
        pass
    return True, "تم تحويل المصروف إلى مصروف آجل"


def update_expense(expense_id, date, voucher_number, description, amount, invoice_number, supplier_name, expense_type, payment_method="", payment_date=""):
    """تحديث بيانات مصروف"""
    conn = sqlite3.connect(DB_PATH)
    # للمصروفات الآجلة، تحديث remaining_amount بناءً على الفرق في المبلغ
    if expense_type == "آجلة":
        old_row = conn.execute("SELECT amount, paid_amount FROM expenses WHERE id = ?", (expense_id,)).fetchone()
        old_amount = float(old_row[0] or 0) if old_row else amount
        paid_amount = float(old_row[1] or 0) if old_row and old_row[1] else 0
        new_remaining = amount - paid_amount
        conn.execute("""UPDATE expenses SET date = ?, voucher_number = ?, description = ?, amount = ?,
            invoice_number = ?, supplier_name = ?, expense_type = ?, payment_method = ?, payment_date = ?,
            remaining_amount = ?
            WHERE id = ?""", (date, voucher_number, description, amount, invoice_number, supplier_name, expense_type, payment_method, payment_date, max(0, new_remaining), expense_id))
    else:
        conn.execute("""UPDATE expenses SET date = ?, voucher_number = ?, description = ?, amount = ?,
            invoice_number = ?, supplier_name = ?, expense_type = ?, payment_method = ?, payment_date = ?
            WHERE id = ?""", (date, voucher_number, description, amount, invoice_number, supplier_name, expense_type, payment_method, payment_date, expense_id))
    conn.commit()
    conn.close()

def update_expense_payment(expense_id, payment_amount):
    """تحديث المبلغ المدفوع والمتبقي للمصروف"""
    conn = sqlite3.connect(DB_PATH)
    # الحصول على المبلغ وقيمة الفاتورة من جدول الفواتير
    row = conn.execute("""SELECT e.amount, COALESCE(e.paid_amount, 0), 
        COALESCE(i.total_amount, e.amount) as invoice_value
        FROM expenses e
        LEFT JOIN invoices i ON e.invoice_number = i.invoice_number
        WHERE e.id = ?""", (expense_id,)).fetchone()
    if row:
        invoice_value = float(row[2] or row[0] or 0)  # استخدام قيمة الفاتورة أو المبلغ
        current_paid = float(row[1] or 0)
        new_paid = current_paid + float(payment_amount)
        remaining = max(0, invoice_value - new_paid)
        conn.execute("UPDATE expenses SET paid_amount = ?, remaining_amount = ? WHERE id = ?", 
                    (new_paid, remaining, expense_id))
        conn.commit()
        conn.close()
        return True
    conn.close()
    return False


_BANK_MOVEMENT_COLS = (
    "id, date, movement_type, amount, invoice_number, customer_name, "
    "receipt_number, description, balance_after"
)

_BANK_CREDIT_COLS = (
    "id, date, movement_type, amount, invoice_number, customer_name, "
    "receipt_number, description"
)


def _fetch_bank_movements(table_name, limit=80, offset=0, month_filter=None):
    """جلب كل حركات البنك كما في الملف (بدون دمج صفوف متشابهة جزئياً)."""
    conn = sqlite3.connect(DB_PATH)
    if month_filter:
        sql = f"""SELECT {_BANK_MOVEMENT_COLS} FROM {table_name}
            WHERE substr(date, 1, 7) = ?
            ORDER BY date ASC, id ASC LIMIT ?"""
        args = [month_filter, limit]
        if offset:
            sql += " OFFSET ?"
            args.append(offset)
    else:
        sql = f"""SELECT {_BANK_MOVEMENT_COLS} FROM {table_name}
            ORDER BY date ASC, id ASC LIMIT ?"""
        args = [limit]
        if offset:
            sql += " OFFSET ?"
            args.append(offset)
    rows = conn.execute(sql, tuple(args)).fetchall()
    conn.close()
    return rows


def fetch_bank_main(limit=80, month_filter=None):
    return _fetch_bank_movements("bank_main_movements", limit=limit, month_filter=month_filter)


def fetch_bank_sub(limit=80, offset=0, month_filter=None):
    return _fetch_bank_movements(
        "bank_sub_movements", limit=limit, offset=offset, month_filter=month_filter
    )


def fetch_bank_sub_count(month_filter=None):
    """عدد حركات الحساب الفرعي (كل الصفوف)."""
    conn = sqlite3.connect(DB_PATH)
    if month_filter:
        n = conn.execute(
            "SELECT COUNT(*) FROM bank_sub_movements WHERE substr(date, 1, 7) = ?",
            (month_filter,),
        ).fetchone()[0]
    else:
        n = conn.execute("SELECT COUNT(*) FROM bank_sub_movements").fetchone()[0]
    conn.close()
    return n


def get_bank_main_opening_balance():
    """الرصيد الافتتاحي للحساب الرئيسي - من جدول bank_main_settings"""
    try:
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute("SELECT value FROM bank_main_settings WHERE key = 'opening_balance' LIMIT 1").fetchone()
        conn.close()
        if row and row[0] is not None and str(row[0]).strip() != "":
            v = float(str(row[0]).replace(",", "."))
            if abs(v) >= 1e-9:
                return v
    except Exception:
        pass
    return None


def ensure_bank_main_opening_from_xlsx():
    """قراءة الرصيد الافتتاحي من Excel فقط عند وجود حركات ولم يُحفظ الرصيد بعد."""
    if get_bank_main_opening_balance() is not None:
        return
    conn = sqlite3.connect(DB_PATH)
    n = conn.execute("SELECT COUNT(*) FROM bank_main_movements").fetchone()[0]
    conn.close()
    if n == 0:
        return
    if os.path.isfile(BANK_MAIN_XLSX_PATH):
        refresh_bank_opening_from_xlsx(BANK_MAIN_XLSX_PATH, "bank_main_movements")


