def fetch_bank_sub_balance_before_offset(offset):
    """حساب الرصيد التراكمي قبل الصف رقم offset (للترقيم عند التصفح)"""
    opening = get_bank_sub_opening_balance()
    base = (
        _bank_balance_value(opening)
        if opening is not None
        else _bank_balance_value(OPENING_BALANCE_BANK_SUB)
    )
    if offset <= 0:
        return base
    rows = _fetch_bank_movements("bank_sub_movements", limit=offset, offset=0, month_filter=None)
    balance = base
    for r in rows:
        _, balance = _bank_balance_for_display_row(r, balance)
    return balance


def fetch_bank_credit(limit=80, month_filter=None):
    conn = sqlite3.connect(DB_PATH)
    if month_filter:
        sql = f"""SELECT {_BANK_CREDIT_COLS} FROM bank_credit_movements
            WHERE substr(date, 1, 7) = ?
            ORDER BY date ASC, id ASC LIMIT ?"""
        rows = conn.execute(sql, (month_filter, limit)).fetchall()
    else:
        sql = f"""SELECT {_BANK_CREDIT_COLS} FROM bank_credit_movements
            ORDER BY date ASC, id ASC LIMIT ?"""
