def build_company_statement_template_bytes(company_name):
    """نموذج Excel لشركة واحدة: اسم الشركة في العنوان + أعمدة الفواتير فقط."""
    import io
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side

    company_name = (company_name or "").strip()
    if not company_name:
        raise ValueError("يجب تحديد اسم الشركة")
    if is_employee_company_name(company_name):
        raise ValueError("اسم الشركة غير صالح")

    wb = openpyxl.Workbook()
    ws = wb.active
    safe_title = company_name[:31].replace("/", "-").replace("\\", "-")
    ws.title = safe_title or "كشف الشركة"
    ws.sheet_view.rightToLeft = True

    title_fill = PatternFill(start_color="1E3A5F", end_color="1E3A5F", fill_type="solid")
    header_fill = PatternFill(start_color="2D5A87", end_color="2D5A87", fill_type="solid")
    hint_fill = PatternFill(start_color="EEF4FB", end_color="EEF4FB", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF", size=12)
    title_font = Font(bold=True, size=14, color="FFFFFF")
    hint_font = Font(size=10, color="555555", italic=True)
    thin = Side(style="thin", color="CCCCCC")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    ws.merge_cells("A1:G1")
    title_cell = ws.cell(row=1, column=1, value=f"كشف حساب الشركة: {company_name}")
    title_cell.fill = title_fill
    title_cell.font = title_font
    title_cell.alignment = Alignment(horizontal="center", vertical="center")
    ws.row_dimensions[1].height = 32

    ws.merge_cells("A2:G2")
    hint_cell = ws.cell(
        row=2,
        column=1,
        value="املأ الفواتير من الصف 4 — لا تغيّر صف العناوين. مدين=المدفوع، دائن=مبلغ الفاتورة، سند الصرف اختياري.",
    )
    hint_cell.fill = hint_fill
    hint_cell.font = hint_font
    hint_cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    ws.row_dimensions[2].height = 22

    headers = [
        "رقم الفاتورة",
        "التاريخ",
        "مدين (مدفوع)",
        "دائن (فاتورة)",
        "تاريخ الدفع",
        "سند الصرف",
        "ملاحظات",
    ]
    header_row = 3
    for col, h in enumerate(headers, 1):
        cell = ws.cell(row=header_row, column=col, value=h)
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal="center", vertical="center")
        cell.border = border
    ws.row_dimensions[header_row].height = 26

    example_rows = [
        ["INV-001", "2026-05-01", 500.125, 1200.0, "2026-05-15", "612", "دفعة جزئية"],
        ["INV-002", "2026-05-10", 0, 1200.5, "", "", "غير مدفوعة"],
        ["INV-003", "2026-06-01", 800.0, 800.0, "2026-06-10", "620", "مدفوعة كاملاً"],
    ]
    for r_off, example in enumerate(example_rows, header_row + 1):
        for col, val in enumerate(example, 1):
            cell = ws.cell(row=r_off, column=col, value=val)
            cell.alignment = Alignment(horizontal="center")
            cell.border = border
            if col in (3, 4):
                cell.number_format = "0.000"

    ws.column_dimensions["A"].width = 20
    ws.column_dimensions["B"].width = 14
    ws.column_dimensions["C"].width = 16
    ws.column_dimensions["D"].width = 16
    ws.column_dimensions["E"].width = 14
    ws.column_dimensions["F"].width = 14
    ws.column_dimensions["G"].width = 26

    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def _company_name_from_stmt_title(ws, max_row=8):
    """استخراج اسم الشركة من عنوان الملف (مثل: كشف حساب الشركة: UNICO)."""
    import re
    for r in range(1, max_row + 1):
        for c in range(1, 5):
            val = ws.cell(row=r, column=c).value
            if val is None:
                continue
            s = str(val).strip()
            if not s or "كشف" not in s:
                continue
            for sep in (":", "："):
                if "شركة" in s and sep in s:
                    name = s.split(sep, 1)[-1].strip()
                    if name:
                        return name
            m = re.search(r"كشف\s+حساب[^:：]*[:：]\s*(.+)", s)
            if m and m.group(1).strip():
                return m.group(1).strip()
    return ""


def _first_company_name_in_stmt_column(ws, idx_company, header_row_idx):
    """أول اسم شركة في عمود «اسم الشركة»."""
    if idx_company is None:
        return ""
    for row in ws.iter_rows(min_row=header_row_idx + 1, values_only=True):
        if not row or not any(row):
            continue
        cells = list(row) + [None] * 10
        name = str(cells[idx_company] or "").strip()
        if name and not is_employee_company_name(name):
            return name
    return ""


def parse_company_statement_xlsx(filepath, company_name=None):
    """قراءة ملف كشف شركة (نموذج شركة واحدة أو النموذج القديم متعدد الشركات)."""
    import openpyxl

    company_name = (company_name or "").strip()

    wb = openpyxl.load_workbook(filepath, data_only=True)
    ws = wb.active

    header_row_idx = None
    header_vals = []
    for r in range(1, 12):
        row_vals = []
        for c in range(1, 12):
            v = ws.cell(row=r, column=c).value
            row_vals.append(str(v).strip() if v is not None else "")
        joined = " ".join(row_vals)
        if ("رقم الفاتورة" in joined) or (
            any(v for v in row_vals if v and "invoice" in v.lower() and "رقم" not in v)
        ):
            header_row_idx = r
            header_vals = row_vals
            break
    if not header_row_idx:
        raise ValueError("لم يتم العثور على صف العناوين (رقم الفاتورة، التاريخ، ...)")

    def _col_idx(*keys):
        for i, h in enumerate(header_vals):
            if not h:
                continue
            hl = h.lower()
            if any(k in h or k in hl for k in keys):
                return i
        return None

    idx_company = _col_idx("اسم الشركة", "company")
    idx_inv = _col_idx("رقم الفاتورة", "invoice")
    idx_date = _col_idx("التاريخ", "date")
    idx_debit = _col_idx("مدين", "debit", "مدفوع")
    idx_credit = _col_idx("دائن", "credit")
    idx_amt = _col_idx("القيمة", "amount", "مبلغ")
    idx_pay = _col_idx("تاريخ الدفع", "pay")
    idx_voucher = _col_idx("سند الصرف", "سند", "voucher")
    idx_notes = _col_idx("ملاحظات", "notes")

    if idx_inv is None:
        raise ValueError("عمود «رقم الفاتورة» غير موجود في الملف")
    if idx_credit is None and idx_amt is None:
        raise ValueError("عمود «دائن» أو «القيمة» غير موجود في الملف")

    title_company = _company_name_from_stmt_title(ws, header_row_idx)
    if not company_name:
        company_name = title_company or _first_company_name_in_stmt_column(ws, idx_company, header_row_idx)
    if not company_name:
        raise ValueError(
            "لم يُعثر على اسم الشركة في الملف. ضعه في عنوان الملف (كشف حساب الشركة: ...) "
            "أو في عمود «اسم الشركة»، أو اكتبه في الحقل أعلاه."
        )
    if is_employee_company_name(company_name):
        raise ValueError("اسم الشركة غير صالح")
    if title_company and title_company != company_name:
        raise ValueError(
            f"الملف يخص شركة «{title_company}» بينما اخترت «{company_name}». صحّح الاسم أو اترك الحقل فارغاً."
        )

    def _cell_float(idx):
        if idx is None:
            return 0.0
        v = cells[idx]
        if v in (None, ""):
            return 0.0
        try:
            return float(v)
        except (TypeError, ValueError):
            return 0.0

    rows = []
    skipped_employees = 0
    data_start = header_row_idx + 1
    for row in ws.iter_rows(min_row=data_start, values_only=True):
        if not row or not any(row):
            continue
        cells = list(row) + [None] * 10

        row_company = company_name
        if idx_company is not None:
            file_company = str(cells[idx_company] or "").strip()
            if file_company:
                if is_employee_company_name(file_company):
                    skipped_employees += 1
                    continue
                if file_company != company_name:
                    raise ValueError(
                        f"صف يخص شركة «{file_company}» بينما الكشف لـ «{company_name}». "
                        "وحّد اسم الشركة في الملف."
                    )
                row_company = file_company

        inv_n = str(cells[idx_inv] or "").strip() if idx_inv is not None else ""
        if not inv_n:
            continue
        inv_d = str(cells[idx_date] or "").strip() if idx_date is not None else ""
        if idx_credit is not None:
            credit = _cell_float(idx_credit)
        else:
            credit = _cell_float(idx_amt)
        debit = _cell_float(idx_debit)
        pay_d = str(cells[idx_pay] or "").strip() if idx_pay is not None else ""
        voucher = str(cells[idx_voucher] or "").strip() if idx_voucher is not None else ""
        nts = str(cells[idx_notes] or "").strip() if idx_notes is not None else ""
        if debit <= 0 and pay_d and credit > 0:
            debit = credit
        rows.append((row_company, inv_n, inv_d, credit, debit, pay_d, voucher, nts))

    return rows, skipped_employees


def insert_company_statement_rows(rows):
    """إدراج صفوف كشف حساب الشركة من Excel"""
    conn = sqlite3.connect(DB_PATH)
    for row in rows:
        if len(row) >= 8:
            company_n, inv_n, inv_d, credit, debit, pay_d, voucher, nts = row[:8]
        elif len(row) >= 7:
            company_n, inv_n, inv_d, credit, debit, pay_d, nts = row[:7]
            voucher = ""
        else:
            company_n, inv_n, inv_d, credit, pay_d, nts = row
            debit = 0.0
            voucher = ""
        credit = float(credit or 0)
        debit = float(debit or 0)
        pay_d = str(pay_d or "").strip()
        voucher = str(voucher or "").strip()
        if debit <= 0 and pay_d and credit > 0:
            debit = credit
        remaining = max(0.0, credit - debit)
        conn.execute(
            """INSERT INTO company_statements
               (company_name, invoice_number, invoice_date, amount, payment_date, notes,
                paid_amount, remaining_amount, voucher_number)
               VALUES (?,?,?,?,?,?,?,?,?)""",
            (company_n, inv_n, inv_d, credit, pay_d or None, nts or None, debit, remaining, voucher or None),
        )
    conn.commit()
    conn.close()

def fetch_company_statements():
    """جلب جميع سجلات كشوف حسابات الشركات"""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        "SELECT id, company_name, invoice_number, invoice_date, amount, payment_date, notes, uploaded_at FROM company_statements ORDER BY id DESC"
    ).fetchall()
    conn.close()
    return rows

def get_company_statements_grouped():
    """تجميع كشوف الشركات: المتبقي الحقيقي، إجمالي الفواتير، وعدد الفواتير."""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT company_name, amount, payment_date, paid_amount, remaining_amount
           FROM company_statements
           WHERE company_name IS NOT NULL AND company_name != ''"""
    ).fetchall()
    conn.close()
    totals = {}
    for company_name, amount, pay_date, paid_db, rem_db in rows:
        if is_employee_company_name(company_name):
            continue
        key = company_name
        if key not in totals:
            totals[key] = {"rem": 0.0, "total": 0.0, "cnt": 0}
        _, _, rem, _ = _company_statement_row_amounts(amount, pay_date, paid_db, rem_db)
        totals[key]["rem"] += rem
        totals[key]["total"] += float(amount or 0)
        totals[key]["cnt"] += 1
    return sorted(
        [(name, data["rem"], data["total"], data["cnt"]) for name, data in totals.items()],
        key=lambda x: x[0],
    )

def resolve_company_statement_name(company_name):
    """تطابق اسم الشركة مع السجلات (TRIM) لتفادي اختلاف المسافات."""
    name = (company_name or "").strip()
    if not name:
        return ""
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT company_name FROM company_statements WHERE TRIM(company_name)=TRIM(?) LIMIT 1",
        (name,),
    ).fetchone()
    conn.close()
    return row[0] if row else name


def _company_statement_row_amounts(amount, pay_date, paid_db, remaining_db):
    """مدين=المدفوع، دائن=قيمة الفاتورة، متبقي=دائن−مدين (يُحسب دائماً ولا يعتمد على متبقي قديم في DB)."""
    amt = float(amount or 0)
    paid = float(paid_db or 0)
    pay = _normalize_stmt_date(pay_date)
    if not pay and paid <= 0:
        return 0.0, amt, amt, ""
    if pay and paid <= 0:
        rem_db = float(remaining_db if remaining_db is not None else amt)
        if 0 <= rem_db < amt:
            paid = max(0.0, amt - rem_db)
        elif rem_db <= 0 and amt > 0:
            paid = amt
    paid = max(0.0, min(paid, amt))
    rem = max(0.0, amt - paid)
    return paid, amt, rem, pay


def _company_statement_apply_payment(invoice_amount, old_paid, payment_input):
    """جمع دفعة جديدة على المدفوع السابق (payment_input = مبلغ هذه الدفعة)."""
    inv = float(invoice_amount or 0)
    prev = max(0.0, float(old_paid or 0))
    add = max(0.0, float(payment_input or 0))
    new_paid = min(inv, prev + add) if add > 0 else prev
    return new_paid, max(0.0, inv - new_paid)


def _normalize_stmt_date(d):
    s = str(d or "").strip()
    if not s:
        return ""
    return s.split(" ")[0].split("T")[0]


def _merge_company_statement_payment_notes(existing_notes, old_pay_date, new_pay_date, pay_notes="", voucher_number=""):
    """عند دفعة جديدة بتاريخ أحدث: إضافة تاريخ الدفعة السابقة إلى الملاحظات."""
    parts = []
    existing = (existing_notes or "").strip()
    old_d = _normalize_stmt_date(old_pay_date)
    new_d = _normalize_stmt_date(new_pay_date)
    if old_d and new_d and old_d != new_d and old_d < new_d:
        prior_line = f"دفعة سابقة: {old_d}"
        if prior_line not in existing:
            parts.append(prior_line)
    if existing:
        parts.append(existing)
    if voucher_number:
        parts.append(f"سند: {voucher_number}")
    if pay_notes:
        parts.append(pay_notes.strip())
    return " | ".join(parts) if parts else None


def backfill_company_statement_descriptions():
    """نسخ البيان من المصروفات الآجلة إلى كشوف الموردين الفارغة (مرة واحدة)."""
    flag = os.path.join(_DATA_DIR, ".company_stmt_desc_backfill_v1_done")
    if os.path.isfile(flag):
        return 0
    conn = sqlite3.connect(DB_PATH)
    try:
        cols = {r[1] for r in conn.execute("PRAGMA table_info(company_statements)").fetchall()}
        if "description" not in cols:
            return 0
        cur = conn.execute(
            """UPDATE company_statements
               SET description = (
                   SELECT TRIM(e.description)
                   FROM expenses e
                   WHERE TRIM(e.invoice_number)=TRIM(company_statements.invoice_number)
                     AND TRIM(COALESCE(e.supplier_name,''))=TRIM(COALESCE(company_statements.company_name,''))
                     AND COALESCE(e.expense_type,'')='آجلة'
                     AND TRIM(COALESCE(e.description,''))!=''
                   ORDER BY e.id DESC
                   LIMIT 1
               )
               WHERE TRIM(COALESCE(description,''))=''
                 AND EXISTS (
                   SELECT 1 FROM expenses e
                   WHERE TRIM(e.invoice_number)=TRIM(company_statements.invoice_number)
                     AND TRIM(COALESCE(e.supplier_name,''))=TRIM(COALESCE(company_statements.company_name,''))
                     AND COALESCE(e.expense_type,'')='آجلة'
                     AND TRIM(COALESCE(e.description,''))!=''
                 )"""
        )
        fixed = cur.rowcount if cur.rowcount and cur.rowcount > 0 else 0
        conn.commit()
    finally:
        conn.close()
    try:
        os.makedirs(_DATA_DIR, exist_ok=True)
        with open(flag, "w", encoding="utf-8") as f:
            f.write(f"fixed={fixed}\n")
    except Exception:
        pass
    return fixed


def get_company_statements_by_name(company_name):
    """جلب جميع فواتير شركة محددة (مدفوعة وغير مدفوعة)."""
    company_name = resolve_company_statement_name(company_name)
    if not company_name:
        return []
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT id, invoice_number, invoice_date, amount, payment_date, notes, voucher_number,
                  COALESCE(description, '')
           FROM company_statements
           WHERE TRIM(company_name)=TRIM(?)
           ORDER BY id ASC""",
        (company_name,),
    ).fetchall()
    conn.close()
    return rows


def get_company_statements_full(company_name):
    """كل عمليات الشركة مع المدفوع والمتبقي (للـ PDF والتقارير)."""
    company_name = resolve_company_statement_name(company_name)
    if not company_name:
        return [], company_name
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT id, invoice_number, invoice_date, amount, payment_date, notes,
                  paid_amount, remaining_amount, voucher_number, COALESCE(description, '')
           FROM company_statements
           WHERE TRIM(company_name)=TRIM(?)
           ORDER BY id ASC""",
        (company_name,),
    ).fetchall()
    conn.close()
    return rows, company_name

def delete_company_statement(row_id):
    """حذف سجل من كشوف حسابات الشركات"""
    conn = sqlite3.connect(DB_PATH)
    conn.execute("DELETE FROM company_statements WHERE id=?", (row_id,))
    conn.commit()
    conn.close()

def clear_company_statements(company_name=None):
    """مسح كشوف الشركات — شركة واحدة أو الكل."""
    conn = sqlite3.connect(DB_PATH)
    if company_name:
        conn.execute("DELETE FROM company_statements WHERE company_name=?", (company_name.strip(),))
    else:
        conn.execute("DELETE FROM company_statements")
    conn.commit()
    conn.close()


def upsert_company_statement_from_expense(
    company_name,
    invoice_number,
    invoice_date,
    invoice_amount,
    paid_amount=0.0,
    payment_date=None,
    voucher_number=None,
    notes=None,
    description=None,
    merge_payment_notes=False,
):
    """إضافة/تحديث فاتورة في كشف حساب الشركة من مصروف آجل (عند التسجيل أو الدفع أو التعديل)."""
    company_name = (company_name or "").strip()
    invoice_number = (invoice_number or "").strip()
    if not company_name or not invoice_number or is_employee_company_name(company_name):
        return False
    inv_amt = float(invoice_amount or 0)
    paid = max(0.0, min(float(paid_amount or 0), inv_amt)) if inv_amt > 0 else max(0.0, float(paid_amount or 0))
    remaining = max(0.0, inv_amt - paid)
    pay_d = _normalize_stmt_date(payment_date) or None
    if paid <= 0:
        pay_d = None
    voucher_number = (voucher_number or "").strip() or None
    inv_date = str(invoice_date or "").strip().split(" ")[0].split("T")[0] if invoice_date else ""

    conn = sqlite3.connect(DB_PATH)
    existing = conn.execute(
        """SELECT id, payment_date, notes, COALESCE(description, '') FROM company_statements
           WHERE TRIM(company_name)=TRIM(?) AND TRIM(invoice_number)=TRIM(?)""",
        (company_name, invoice_number),
    ).fetchone()
    if merge_payment_notes and pay_d and existing:
        notes_final = _merge_company_statement_payment_notes(
            existing[2], existing[1], pay_d, voucher_number=voucher_number or ""
        )
    else:
        notes_final = notes if notes is not None else (existing[2] if existing else None)
    if description is not None:
        desc_final = str(description or "").strip()
    else:
        desc_final = (existing[3] if existing else "") or ""

    if existing:
        conn.execute(
            """UPDATE company_statements
               SET invoice_date=?, amount=?, payment_date=?, paid_amount=?, remaining_amount=?,
                   notes=?, voucher_number=?, description=?
               WHERE id=?""",
            (
                inv_date or None,
                inv_amt,
                pay_d,
                paid,
                remaining,
                notes_final,
                voucher_number,
                desc_final or None,
                existing[0],
            ),
        )
    else:
        conn.execute(
            """INSERT INTO company_statements
               (company_name, invoice_number, invoice_date, amount, payment_date, notes,
                paid_amount, remaining_amount, voucher_number, description)
               VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                company_name,
                invoice_number,
                inv_date or None,
                inv_amt,
                pay_d,
                notes_final,
                paid,
                remaining,
                voucher_number,
                desc_final or None,
            ),
        )
    conn.commit()
    conn.close()
    return True


def sync_deferred_expense_from_company_statement(stmt_id):
    """مزامنة المصروف الآجل المطابق عند دفع أو تعديل كشف المورد."""
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        """SELECT company_name, invoice_number, amount, paid_amount, remaining_amount,
                  payment_date, voucher_number, COALESCE(description, '')
           FROM company_statements WHERE id=?""",
        (stmt_id,),
    ).fetchone()
    conn.close()
    if not row:
        return False
    _desc = str(row[7] or "").strip()
    return _apply_statement_payment_to_deferred_expense(
        row[0],
        row[1],
        row[2],
        row[3],
        row[4],
        row[5],
        row[6],
        description=_desc if _desc else None,
    )


def _apply_statement_payment_to_deferred_expense(
    company_name,
    invoice_number,
    amount,
    paid_amount,
    remaining_amount,
    payment_date=None,
    voucher_number=None,
    description=None,
):
    """تحديث paid_amount و remaining_amount في المصروف الآجل من كشف المورد."""
    company_name = (company_name or "").strip()
    invoice_number = (invoice_number or "").strip()
    if not invoice_number:
        return False
    paid = max(0.0, float(paid_amount or 0))
    inv_amt = float(amount or 0)
    remaining = (
        float(remaining_amount)
        if remaining_amount is not None
        else max(0.0, inv_amt - paid)
    )
    pay_d = _normalize_stmt_date(payment_date) or None
    voucher = (voucher_number or "").strip() or None
    conn = sqlite3.connect(DB_PATH)
    exp = conn.execute(
        """SELECT id FROM expenses
           WHERE COALESCE(expense_type,'')='آجلة'
           AND TRIM(invoice_number)=TRIM(?)
           AND (TRIM(supplier_name)=TRIM(?) OR ?='')
           ORDER BY CASE WHEN TRIM(supplier_name)=TRIM(?) THEN 0 ELSE 1 END, id DESC
           LIMIT 1""",
        (invoice_number, company_name, company_name, company_name),
    ).fetchone()
    if not exp:
        conn.close()
        return False
    if description is not None:
        conn.execute(
            """UPDATE expenses SET paid_amount=?, remaining_amount=?, payment_date=?,
               voucher_number=?, description=? WHERE id=?""",
            (paid, remaining, pay_d, voucher, str(description or "").strip(), exp[0]),
        )
    else:
        conn.execute(
            """UPDATE expenses SET paid_amount=?, remaining_amount=?, payment_date=?, voucher_number=?
               WHERE id=?""",
            (paid, remaining, pay_d, voucher, exp[0]),
        )
    conn.commit()
    conn.close()
    return True


def reconcile_deferred_expenses_from_statements():
    """مزامنة المصروفات الآجلة مع كشوف الموردين عند اختلاف حالة الدفع."""
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute(
        """SELECT cs.company_name, cs.invoice_number, cs.amount, cs.paid_amount, cs.remaining_amount,
                  cs.payment_date, cs.voucher_number, e.id,
                  COALESCE(e.paid_amount, 0), COALESCE(e.remaining_amount, e.amount, 0)
           FROM company_statements cs
           INNER JOIN expenses e
             ON TRIM(e.invoice_number)=TRIM(cs.invoice_number)
            AND TRIM(e.supplier_name)=TRIM(cs.company_name)
            AND COALESCE(e.expense_type,'')='آجلة'
           WHERE ABS(COALESCE(e.paid_amount, 0) - COALESCE(cs.paid_amount, 0)) > 0.001
              OR ABS(COALESCE(e.remaining_amount, e.amount, 0) - COALESCE(cs.remaining_amount, 0)) > 0.001"""
    ).fetchall()
    for row in rows:
        conn.execute(
            """UPDATE expenses SET paid_amount=?, remaining_amount=?, payment_date=?, voucher_number=?
               WHERE id=?""",
            (
                float(row[3] or 0),
                float(row[4] if row[4] is not None else max(0.0, float(row[2] or 0) - float(row[3] or 0))),
                _normalize_stmt_date(row[5]) or None,
                (row[6] or "").strip() or None,
                row[7],
            ),
        )
    conn.commit()
    conn.close()
    return len(rows)


