def fetch_salaries(limit=80):
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("""SELECT id, employee_name, month, actual_salary, month_share, amount_paid, date, absences
        FROM salaries ORDER BY date ASC, id ASC LIMIT ?""", (limit,)).fetchall()
    conn.close()
    return rows


def fetch_absences(limit=80, month_filter=None):
    conn = sqlite3.connect(DB_PATH)
    conditions, args = [], []
    if month_filter and str(month_filter).strip():
        ym = normalize_salary_month(str(month_filter).strip())
        if ym and len(ym) >= 7 and "-" in ym:
            y, m = ym[:4], ym[5:7]
            conditions.append("strftime('%Y', date) = ? AND strftime('%m', date) = ?")
            args.extend([y, m])
    where = (" WHERE " + " AND ".join(conditions)) if conditions else ""
    rows = conn.execute(
        f"""SELECT id, employee_name, date, days, details FROM absences{where}
            ORDER BY date ASC, id ASC LIMIT ?""",
        args + [limit],
    ).fetchall()
    conn.close()
    return rows


def _read_shared_strings(z):
    """قراءة النصوص المشتركة من ملف xlsx - يعيد قائمة فارغة إن لم يوجد الملف"""
    empty_sst = b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="0" uniqueCount="0"/>'
    shared_raw = z.read('xl/sharedStrings.xml') if 'xl/sharedStrings.xml' in z.namelist() else empty_sst
    ns = {'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    root = ET.fromstring(shared_raw)
    shared_strings = []
    for si in root.findall('.//main:si', ns):
        t = si.find('main:t', ns)
        if t is not None and t.text:
            shared_strings.append(t.text)
        else:
            texts = [r.find('main:t', ns).text if r.find('main:t', ns) is not None else '' for r in si.findall('main:r', ns)]
            shared_strings.append(''.join(t if t else '' for t in texts) if texts else '')
        if not shared_strings[-1]:
            shared_strings[-1] = ''
    return shared_strings


def _esc(s):
    """تهريب نص للـ HTML"""
    if s is None:
        return ""
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def _format_invoice_payment_method(pm):
    """عرض طريقة الدفع: نقدي → نقدي / رابط (القيمة المحفوظة تبقى نقدي)."""
    p = str(pm or "").strip()
    if p in ("نقدي", "رابط"):
        return "نقدي / رابط"
    return p


