def _invoice_payment_method_options(selected=""):
    """خيارات طريقة الدفع مع تحديد القيمة المحفوظة."""
    pm = str(selected or "").strip()
    if pm in ("نقدي", "رابط"):
        pm = "نقدي"
    choices = (
        ("", "اختر طريقة الدفع"),
        ("نقدي", "نقدي / رابط"),
        ("تحويل بنكي", "تحويل بنكي"),
        ("شيك", "شيك"),
        ("ماي فاتورة", "ماي فاتورة"),
        ("تابي", "تابي"),
        ("ديمة", "ديمة"),
    )
    parts = []
    for val, label in choices:
        sel = ' selected="selected"' if pm and val == pm else ""
        parts.append(f'<option value="{_esc(val)}"{sel}>{_esc(label)}</option>')
    return "".join(parts)


def _fmt_mv_words(s):
    """تلوين «مدينة» بالأخضر و«دائنة» بالأحمر مع مسافة واضحة بعد «حركات»."""
    if s is None:
        return ""
    text = _esc(str(s))
    text = re.sub(
        r"حركات\s*مدينة",
        'حركات&nbsp;<span class="mv-word-debit">مدينة</span>',
        text,
    )
    text = re.sub(
        r"حركات\s*دائنة",
        'حركات&nbsp;<span class="mv-word-credit">دائنة</span>',
        text,
    )
    if "mv-word-debit" not in text and "mv-word-credit" not in text:
        text = text.replace("دائنة", '<span class="mv-word-credit">دائنة</span>')
        text = text.replace("مدينة", '<span class="mv-word-debit">مدينة</span>')
    return text


