def get_dashboard_stats():
    """إحصائيات لوحة التحكم الرئيسية"""
    conn = sqlite3.connect(DB_PATH)
    try:
        # إجمالي الإيرادات (مبالغ الفواتير)
        total_revenue = conn.execute("SELECT COALESCE(SUM(total_amount),0) FROM invoices").fetchone()[0]
        # إجمالي المقبوضات الفعلية
        total_collected = conn.execute("SELECT COALESCE(SUM(down_payment),0) FROM invoices").fetchone()[0]
        # إجمالي المتبقي من الفواتير
        total_remaining_invoices = conn.execute("SELECT COALESCE(SUM(remaining),0) FROM invoices").fetchone()[0]
        # إجمالي المصروفات
        total_expenses = conn.execute("SELECT COALESCE(SUM(amount),0) FROM expenses").fetchone()[0]
        # المصروفات الآجلة غير المدفوعة
        deferred_unpaid = conn.execute("SELECT COALESCE(SUM(remaining_amount),0) FROM expenses WHERE COALESCE(expense_type,'')='آجلة' AND COALESCE(remaining_amount,1)>0").fetchone()[0]
        # عدد الفواتير
        invoice_count = conn.execute("SELECT COUNT(*) FROM invoices").fetchone()[0]
        # عدد الموظفين
        employee_count = conn.execute("SELECT COUNT(*) FROM employees").fetchone()[0]
        # إجمالي الرواتب المدفوعة
        total_salaries = conn.execute("SELECT COALESCE(SUM(amount_paid),0) FROM salaries").fetchone()[0]
        # إجمالي الإيجارات المدفوعة
        total_rents = conn.execute("SELECT COALESCE(SUM(amount),0) FROM rents").fetchone()[0]
        # صافي الربح التقريبي
        net_profit = total_collected - total_expenses
        # آخر 5 فواتير
        last_invoices = conn.execute("SELECT date, invoice_number, customer_name, total_amount, remaining FROM invoices ORDER BY id DESC LIMIT 5").fetchall()
        # آخر 5 مصروفات
        last_expenses = conn.execute("SELECT date, description, supplier_name, amount, expense_type FROM expenses ORDER BY id DESC LIMIT 5").fetchall()
        # إحصائيات الشهر الحالي
        current_month = datetime.now().strftime('%Y-%m')
        month_revenue = conn.execute("SELECT COALESCE(SUM(total_amount),0) FROM invoices WHERE substr(date,1,7)=?", (current_month,)).fetchone()[0]
        month_expenses = conn.execute("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE substr(date,1,7)=?", (current_month,)).fetchone()[0]
        return {
            'total_revenue': total_revenue,
            'total_collected': total_collected,
            'total_remaining_invoices': total_remaining_invoices,
            'total_expenses': total_expenses,
            'deferred_unpaid': deferred_unpaid,
            'invoice_count': invoice_count,
            'employee_count': employee_count,
            'total_salaries': total_salaries,
            'total_rents': total_rents,
            'net_profit': net_profit,
            'last_invoices': last_invoices,
            'last_expenses': last_expenses,
            'month_revenue': month_revenue,
            'month_expenses': month_expenses,
        }
    finally:
        conn.close()


