def _strip_sund_sarf_from_desc(text):
    """إزالة ( سند صرف ) ورقمه من بداية البيان في حركة الحساب الفرعي"""
    if not text or not str(text).strip():
        return text or ""
    s = str(text).strip()
    s = re.sub(r'^سند\s*الصرف\s*\d+\s*\(\s*', '', s)
    s = re.sub(r'^سند\s*الصرف\s*\d+\s*', '', s)
    s = re.sub(r'^سند صرف\s*\d+\s*\(\s*', '', s)
    s = re.sub(r'^سند صرف\s*\d+\s*', '', s)
    return s.strip()


