def _invoice_bulk_select_js():
    """JavaScript لتحديد الفواتير والإجراءات الجماعية."""
    return """<script>
(function(){
  function invSelected(){return Array.from(document.querySelectorAll('.inv-sel-cb:checked'));}
  function invUpdateBulk(){
    var cbs=invSelected();
    var n=cbs.length;
    var bar=document.getElementById('invBulkBar');
    var tbl=document.querySelector('.rev-table');
    if(bar) bar.style.display=n?'flex':'none';
    var cnt=document.getElementById('invBulkN');
    if(cnt) cnt.textContent=n;
    if(tbl) tbl.classList.toggle('rev-multi-select',n>1);
  }
  window.invBulkAction=function(act){
    var cbs=invSelected();
    if(!cbs.length) return;
    var bar=document.getElementById('invBulkBar');
    var back=(bar&&bar.getAttribute('data-back'))||'/revenues';
    var ids=cbs.map(function(c){return c.value;});
    if(act==='pay'){
      var payables=cbs.filter(function(c){
        return c.dataset.cancelled!=='1'&&parseFloat(c.dataset.remaining||0)>0.0005;
      });
      if(!payables.length){alert('لا توجد فواتير قابلة للدفع في التحديد');return;}
      ids=payables.map(function(c){return c.value;});
      window.location='/pay-invoices-bulk?ids='+encodeURIComponent(ids.join(','))
        +'&back='+encodeURIComponent(back);
      return;
    }
    var labels={cancel:'إلغاء',delete:'حذف'};
    if(!confirm('تأكيد '+labels[act]+' '+ids.length+' فاتورة؟')) return;
    var f=document.createElement('form');
    f.method='POST';
    f.action='/bulk-invoices';
    var a=document.createElement('input');a.type='hidden';a.name='action';a.value=act;f.appendChild(a);
    var b=document.createElement('input');b.type='hidden';b.name='ids';b.value=ids.join(',');f.appendChild(b);
    var c=document.createElement('input');c.type='hidden';c.name='back';c.value=back;f.appendChild(c);
    document.body.appendChild(f);
    f.submit();
  };
  document.addEventListener('change',function(e){
    if(e.target.classList.contains('inv-sel-cb')||e.target.id==='invSelAll') invUpdateBulk();
  });
  var sa=document.getElementById('invSelAll');
  if(sa) sa.addEventListener('change',function(){
    document.querySelectorAll('.inv-sel-cb').forEach(function(cb){cb.checked=sa.checked;});
    invUpdateBulk();
  });
})();
</script>"""


def _pay_invoices_bulk_page_html(invoices, back, ids_csv):
    """صفحة دفع عدة فواتير دفعة واحدة."""
    rows_html = ""
    total_rem = 0.0
    for inv in invoices:
        rem = float(inv[6] or 0)
        total_rem += rem
        rows_html += (
            f"<tr><td>{_esc(inv[2])}</td><td>{_esc(inv[3])}</td>"
            f'<td style="text-align:center;font-weight:700">{rem:.3f}</td></tr>'
        )
    pm_opts = INVOICE_PAYMENT_METHOD_SELECT_OPTIONS
    return f"""<!DOCTYPE html>
<html lang="ar" dir="rtl"><head><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" crossorigin="anonymous"><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>دفع فواتير متعددة - المحاسب الذكي</title>
<style>
body{{font-family:"Droid Arabic Kufi",Tahoma,Arial;background:linear-gradient(135deg,#1e3a5f,#2d5a87);min-height:100vh;margin:0;padding:20px;color:#333}}
.container{{max-width:640px;margin:0 auto;background:#fff;border-radius:16px;padding:32px;box-shadow:0 10px 40px rgba(0,0,0,.2)}}
h1{{text-align:center;margin-bottom:16px;color:#1e3a5f;font-size:1.35em}}
.bulk-table{{width:100%;border-collapse:collapse;margin:16px 0;font-size:14px}}
.bulk-table th,.bulk-table td{{padding:8px 10px;border-bottom:1px solid #edf0f3;text-align:right}}
.bulk-table th{{background:#1e3a5f;color:#fff}}
.total-bar{{background:#f0f4fa;border-radius:10px;padding:14px;margin:16px 0;font-size:16px;text-align:center}}
.total-bar strong{{color:#c00;font-size:1.2em}}
.form-group{{margin:14px 0}}
.form-group label{{display:block;margin-bottom:5px;font-weight:bold}}
.form-group input,.form-group select{{width:100%;padding:12px;border:2px solid #ddd;border-radius:8px;box-sizing:border-box;font-family:inherit;font-size:15px}}
.btn{{display:inline-block;padding:14px 24px;margin:10px 5px 10px 0;border:none;border-radius:10px;font-size:16px;cursor:pointer;text-decoration:none;text-align:center}}
.btn-save{{background:#28a745;color:#fff}}.btn-back{{background:#6c757d;color:#fff}}
</style></head><body><div class="container">
<h1><i class="fa-solid fa-circle-dollar-to-slot" style="color:#28a745"></i> دفع {len(invoices)} فاتورة</h1>
<p style="text-align:center;color:#666;margin:0">سيتم دفع المتبقي بالكامل لكل فاتورة محددة</p>
<table class="bulk-table"><thead><tr><th>رقم الفاتورة</th><th>العميل</th><th>المتبقي</th></tr></thead><tbody>
{rows_html}
</tbody></table>
<div class="total-bar">إجمالي المبلغ: <strong>{total_rem:.3f}</strong></div>
<form method="POST" action="/pay-invoices-bulk">
<input type="hidden" name="invoice_ids" value="{_esc(ids_csv)}">
<input type="hidden" name="back" value="{_esc(back)}">
<div class="form-group"><label>تاريخ الدفع</label><input type="date" name="payment_date" id="payDate" required></div>
<div class="form-group"><label>رقم سند القبض (اختياري)</label><input type="text" name="receipt_number"></div>
<div class="form-group"><label>طريقة الدفع</label><select name="payment_method" required>{pm_opts}</select></div>
<button type="submit" class="btn btn-save"><i class="fa-solid fa-check"></i> تأكيد الدفع</button>
</form>
<a href="{_esc(back)}" class="btn btn-back"><i class="fa-solid fa-arrow-right"></i> رجوع</a>
<script>document.addEventListener('DOMContentLoaded',function(){{
  document.getElementById('payDate').value=new Date().toISOString().split('T')[0];
}});</script>
</div></body></html>"""


def _invoice_row_actions(row, back_path):
    """أزرار إجراءات صف الفاتورة (دفع / تعديل / إلغاء / حذف)."""
    if _invoice_is_cancelled(row):
        cancelled_at = str(row[-1] or "").strip()
        hint = f" — {cancelled_at}" if cancelled_at else ""
        return (
            f'<span style="color:#999;font-size:12px;font-weight:700;white-space:nowrap">'
            f'<i class="fa-solid fa-ban" style="margin-left:4px"></i> ملغاة{hint}</span> '
            f'{_del_link("delete-invoice", row[0], back_path)}'
        )
    remaining = float(row[6] or 0)
    pay_btn = _pay_link("pay-invoice", row[0], back_path) if remaining > 0 else ""
    return (
        f"{pay_btn} <span class=\"inv-act-edit\">{_edit_link('edit-invoice', row[0], back_path)}</span> "
        f"{_cancel_link('cancel-invoice', row[0], back_path)} "
        f"{_del_link('delete-invoice', row[0], back_path)}"
    )

def _pay_link(action, rid, back_path):
    """رابط الدفع"""
    return (
        f'<a href="/{action}?id={rid}&back={quote(back_path)}" class="btn-pay" title="دفع" '
        f'aria-label="دفع"><span class="btn-act-icon" aria-hidden="true">{_BTN_ICON_PAY}</span></a>'
    )


def _convert_deferred_link(action, rid, back_path):
    """رابط تحويل مصروف نقدي إلى آجل"""
    href = f"/{action}?id={rid}&from={quote(back_path)}"
    return (
        f'<a href="{href}" class="btn-defer" title="تحويل إلى مصروف آجل" '
        f'aria-label="تحويل إلى مصروف آجل" data-confirm-convert="1">'
        f'<span class="btn-act-icon" aria-hidden="true">⏱</span></a>'
    )

