_DIELINE_JS = """
window.DL=(function(){
var NS='http://www.w3.org/2000/svg';
function S(id){return document.getElementById(id);}
function num(v){var n=parseFloat(v);return isNaN(n)?0:n;}
function el(p,a){var e=document.createElementNS(NS,p);for(var k in a)e.setAttribute(k,a[k]);return e;}
function r(v){return Math.round(v*100)/100;}
function rect(cuts,x,y,w,h){cuts.push([x,y,x+w,y],[x+w,y,x+w,y+h],[x+w,y+h,x,y+h],[x,y+h,x,y]);}
function render(svgId,m){
  var s=S(svgId);while(s.firstChild)s.removeChild(s.firstChild);
  if(!m){s.removeAttribute('viewBox');return;}
  var pad=20,bag=m.theme==='bag',red='#e2334b',cutStroke=bag?red:'#16243a',creaseStroke=red,cutW=bag?1.4:1.9,creaseW=bag?1.4:1.4,dash=bag?'none':'8 5';
  s.setAttribute('viewBox',(-pad)+' '+(-pad)+' '+(m.w+2*pad)+' '+(m.h+2*pad));
  (m.creases||[]).forEach(function(c){s.appendChild(el('line',{x1:c[0],y1:c[1],x2:c[2],y2:c[3],stroke:creaseStroke,'stroke-width':creaseW,'stroke-dasharray':dash}));});
  (m.cuts||[]).forEach(function(c){s.appendChild(el('line',{x1:c[0],y1:c[1],x2:c[2],y2:c[3],stroke:cutStroke,'stroke-width':cutW}));});
  (m.holes||[]).forEach(function(h){s.appendChild(el('circle',{cx:h.x,cy:h.y,r:h.r,fill:'none',stroke:cutStroke,'stroke-width':cutW}));});
  (m.labels||[]).forEach(function(l){var t=el('text',{x:l.x,y:l.y,'text-anchor':'middle','dominant-baseline':'middle','font-size':(l.fs||13),fill:'#1e3a5f','font-weight':'700','font-family':'Cairo,Tahoma,Arial'});if(l.rot){t.setAttribute('transform','rotate('+l.rot+' '+l.x+' '+l.y+')');}t.textContent=l.t;s.appendChild(t);});
}
function exportSVG(m,filename){
  if(!m){alert('أدخل المقاسات أولاً');return;}
  var body='';
  (m.cuts||[]).forEach(function(c){body+='<line x1="'+r(c[0])+'" y1="'+r(c[1])+'" x2="'+r(c[2])+'" y2="'+r(c[3])+'" stroke="#000000" stroke-width="0.1"/>';});
  (m.creases||[]).forEach(function(c){body+='<line x1="'+r(c[0])+'" y1="'+r(c[1])+'" x2="'+r(c[2])+'" y2="'+r(c[3])+'" stroke="#ff0000" stroke-width="0.1" stroke-dasharray="2 1.5"/>';});
  (m.holes||[]).forEach(function(h){body+='<circle cx="'+r(h.x)+'" cy="'+r(h.y)+'" r="'+r(h.r)+'" fill="none" stroke="#000000" stroke-width="0.1"/>';});
  var W=r(m.w),H=r(m.h);
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'mm" height="'+H+'mm" viewBox="0 0 '+W+' '+H+'">'+body+'</svg>';
  var b=new Blob([svg],{type:'image/svg+xml'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},200);
}
function exportPDF(m,filename){
  if(!m){alert('أدخل المقاسات أولاً');return;}
  var W=r(m.w),H=r(m.h);
  if(W<=0||H<=0){alert('أبعاد غير صالحة');return;}
  fetch('/api/template-export-pdf',{method:'POST',headers:{'Content-Type':'application/json;charset=utf-8'},body:JSON.stringify({model:m,filename:filename||'template.pdf'})})
  .then(function(resp){
    if(!resp.ok)return resp.text().then(function(t){throw new Error(t||'pdf');});
    var ct=(resp.headers.get('Content-Type')||'').toLowerCase();
    if(ct.indexOf('application/pdf')<0)throw new Error('type');
    return resp.arrayBuffer();
  })
  .then(function(buf){
    if(!buf||buf.byteLength<5)throw new Error('empty');
    var head=new Uint8Array(buf,0,5),sig='';
    for(var i=0;i<head.length;i++){sig+=String.fromCharCode(head[i]);}
    if(sig.indexOf('%PDF')!==0)throw new Error('bad');
    return new Blob([buf],{type:'application/pdf'});
  })
  .then(function(blob){
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=filename||'template.pdf';
    document.body.appendChild(a);
    a.click();
    setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},200);
  })
  .catch(function(){alert('تعذر إنشاء PDF');});
}
return {render:render,exportSVG:exportSVG,exportPDF:exportPDF,num:num,S:S,rect:rect};
})();
"""


def _dieline_model_to_pdf_bytes(model):
    """تحويل نموذج القالب (mm) إلى PDF بحجم الصفحة = أبعاد القالب."""
    import io
    import math

    from reportlab.lib.units import mm
    from reportlab.pdfgen import canvas

    if not isinstance(model, dict):
        return b""
    try:
        w = float(model.get("w") or 0)
        h = float(model.get("h") or 0)
    except (TypeError, ValueError):
        return b""
    if not math.isfinite(w) or not math.isfinite(h) or w <= 0 or h <= 0:
        return b""

    pw, ph = w * mm, h * mm
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(pw, ph))
    c.setLineWidth(0.1 * mm)

    def _coord(v):
        try:
            n = float(v)
        except (TypeError, ValueError):
            return None
        return n if math.isfinite(n) else None

    def _x(v):
        n = _coord(v)
        return None if n is None else n * mm

    def _y(v):
        n = _coord(v)
        return None if n is None else ph - n * mm

    def _line(seg):
        if not isinstance(seg, (list, tuple)) or len(seg) < 4:
            return
        x1, y1, x2, y2 = _x(seg[0]), _y(seg[1]), _x(seg[2]), _y(seg[3])
        if None in (x1, y1, x2, y2):
            return
        c.line(x1, y1, x2, y2)

    c.setStrokeColorRGB(0.89, 0.14, 0.18)
    c.setDash(2 * mm, 1.5 * mm)
    for seg in model.get("creases") or []:
        _line(seg)

    c.setDash(1, 0)
    c.setStrokeColorRGB(0, 0, 0)
    for seg in model.get("cuts") or []:
        _line(seg)

    for hole in model.get("holes") or []:
        if not isinstance(hole, dict):
            continue
        hx, hy, hr = _x(hole.get("x")), _y(hole.get("y")), _coord(hole.get("r"))
        if hx is None or hy is None or hr is None or hr <= 0:
            continue
        c.circle(hx, hy, hr * mm, stroke=1, fill=0)

    c.save()
    return buf.getvalue()


def _template_standalone(title, body):
    """قالب صفحة مستقلة لصانع القوالب (يعيد استخدام ستايلات حاسبة التكاليف)."""
    return (
        '<!DOCTYPE html>\n<html lang="ar" dir="rtl"><head>'
        '<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" crossorigin="anonymous">'
        '<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">'
        f'<title>{title}</title>'
        f'<style>{_COST_CALCULATOR_STYLES}{_DIELINE_STYLES}{_TEMPLATE_MAKER_THEME}</style></head>'
        f'<body class="cc-standalone">{body}</body></html>'
    )


