def _kwd_to_kd_fils(amount):
    """تقسيم المبلغ إلى دينار وفلس (1000 فلس = 1 د.ك)."""
    try:
        n = float(str(amount or "0").replace(",", "."))
    except (ValueError, TypeError):
        n = 0.0
    kd = int(n)
    fils = int(round((n - kd) * 1000))
    if fils >= 1000:
        kd += 1
        fils = 0
    return kd, fils


def _parse_cei_items(data):
    """تحليل بنود فاتورة المصروف النقدي."""
    items = []
    for row in (data or {}).get("items") or []:
        if not isinstance(row, dict):
            continue
        desc = str(row.get("description") or "").strip()
        try:
            qty = float(str(row.get("qty") or "1").replace(",", "."))
        except (ValueError, TypeError):
            qty = 1.0
        amount = None
        if row.get("amount") not in (None, ""):
            try:
                amount = float(str(row.get("amount") or "0").replace(",", "."))
            except (ValueError, TypeError):
                amount = None
        try:
            unit = float(str(row.get("unit_price") or "0").replace(",", "."))
        except (ValueError, TypeError):
            unit = 0.0
        if amount is not None:
            unit = amount / qty if qty else amount
            line_total = amount
        else:
            line_total = qty * unit
        if desc or line_total:
            items.append(
                {
                    "description": desc,
                    "qty": qty,
                    "unit_price": unit,
                    "amount": line_total,
                }
            )
    return items


CEI_SEQ_KEY = "cash_expense_invoice_seq"
CEI_DEFAULT_CUSTOMER_NAME = "شركة كرييتف ستيديو للدعاية والاعلان"
# نسب أعمدة جدول الفاتورة — مصدر واحد للمعاينة و PDF (يمين→يسار: البيان، الكمية، سعر د.ك، سعر فلس، إجمالي د.ك، إجمالي فلس)
CEI_TABLE_COL_FR = (0.30, 0.14, 0.12, 0.12, 0.16, 0.16)
CEI_TABLE_COL_FR_LTR = tuple(reversed(CEI_TABLE_COL_FR))  # ترتيب PDF/معاينة: إجمالي فلس … البيان


def _cei_col_widths(usable_w):
    """تحويل نسب الأعمدة إلى عرض بالنقاط (يسار→يمين في PDF)."""
    return [f * usable_w for f in CEI_TABLE_COL_FR_LTR]


def _format_cei_invoice_no(n):
    try:
        return str(int(n)).zfill(4)
    except (ValueError, TypeError):
        return "0001"


def peek_next_cash_expense_invoice_no():
    """رقم الفاتورة التالي دون حجزه."""
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = ? LIMIT 1", (CEI_SEQ_KEY,)
        ).fetchone()
        last = int(row[0] or 0) if row and row[0] not in (None, "") else 0
        return _format_cei_invoice_no(last + 1)
    finally:
        conn.close()


def allocate_cash_expense_invoice_no():
    """حجز رقم فاتورة مصروف نقدي جديد."""
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = ? LIMIT 1", (CEI_SEQ_KEY,)
        ).fetchone()
        last = int(row[0] or 0) if row and row[0] not in (None, "") else 0
        nxt = last + 1
        conn.execute(
            "INSERT OR REPLACE INTO app_settings (key, value) VALUES (?, ?)",
            (CEI_SEQ_KEY, str(nxt)),
        )
        conn.commit()
        return _format_cei_invoice_no(nxt)
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def save_cash_expense_invoice_record(payload, invoice_no):
    """حفظ سجل الفاتورة الصادرة."""
    import json

    items = _parse_cei_items(payload)
    total = sum(float(i.get("amount") or 0) for i in items)
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """INSERT INTO cash_expense_invoices (invoice_no, date, name, total, payload)
               VALUES (?, ?, ?, ?, ?)""",
            (
                invoice_no,
                str(payload.get("date") or "").strip(),
                CEI_DEFAULT_CUSTOMER_NAME,
                total,
                json.dumps(payload, ensure_ascii=False),
            ),
        )
        conn.commit()
    finally:
        conn.close()


def generate_cash_expense_invoice_pdf(data):
    """إنشاء PDF لفاتورة نقداً / بالحساب — تخطيط A4 عمودي."""
    try:
        import io
        import datetime as _dt
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors as _rl_colors
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import cm, mm
    except ImportError as e:
        raise RuntimeError("مكتبة reportlab غير مثبتة على السيرفر.") from e

    data = data if isinstance(data, dict) else {}
    _FN, _FN_B = pdf_font_names()

    # A4: 210 × 297 مم — هوامش طباعة قياسية
    _MARGIN = 12 * mm
    _PAGE_W, _PAGE_H = A4
    _USABLE_W = _PAGE_W - 2 * _MARGIN
    _COL_W = _cei_col_widths(_USABLE_W)

    def _xml_esc(s):
        s = str(s) if s is not None else ""
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def _para(text, size=9, bold=False, align=1, color=None, leading=None, markup=False):
        st = ParagraphStyle(
            f"cei_{size}_{'b' if bold else 'r'}_{align}",
            fontName=_FN_B if bold else _FN,
            fontSize=size,
            alignment=align,
            textColor=color or _rl_colors.black,
            leading=leading or size + 2,
            wordWrap="CJK",
        )
        body = text if markup else _xml_esc(_shape_pdf_text(text))
        return Paragraph(body, st)

    def _cell(txt, bold=False, align=1, size=11):
        return _para(str(txt) if txt not in (None, "") else "", size=size, bold=bold, align=align)

    def _hdr_cell(en, ar, bold=True, align=1, size=10):
        en_s = _xml_esc(_shape_pdf_text(en))
        ar_s = _xml_esc(_shape_pdf_text(ar))
        return _para(f"{en_s}<br/>{ar_s}", size=size, bold=bold, align=align, leading=size + 5, markup=True)

    def _hdr_cell_small(en, ar):
        return _hdr_cell(en, ar, bold=False, size=9)

    real_items = _parse_cei_items(data)
    _MIN_BODY_ROWS = max(4, len(real_items) + 2)
    items = list(real_items)
    while len(items) < _MIN_BODY_ROWS:
        items.append({"description": "", "qty": "", "unit_price": 0.0, "amount": 0.0})

    total = sum(float(i.get("amount") or 0) for i in real_items)
    total_kd, total_fils = _kwd_to_kd_fils(total)
    name = CEI_DEFAULT_CUSTOMER_NAME
    seller = str(data.get("seller") or "").strip()
    date_s = str(data.get("date") or _dt.date.today().isoformat()).strip().replace("-", "/")
    invoice_no = _format_cei_invoice_no(data.get("invoice_no") or "0001")

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf,
        pagesize=A4,
        rightMargin=_MARGIN,
        leftMargin=_MARGIN,
        topMargin=_MARGIN,
        bottomMargin=_MARGIN,
        title="Cash/Credit Invoice",
    )
    story = []

    story.append(_para("فاتورة نقداً / بالحساب", size=17, bold=True, align=1, leading=20))
    story.append(_para("Cash/Credit Invoice", size=12, align=1, leading=14))
    story.append(Spacer(1, 4 * mm))

    hdr_tbl = Table(
        [
            [_cell(f"No. : {invoice_no}", align=2, size=12)],
            [_cell(f"التاريخ : {date_s}", align=2, size=12)],
            [_cell(f"البائع / Seller : {seller or '................................'}", align=2, size=12)],
            [_cell(f"المطلوب من السيد / السادة : {name or '................................'}", align=2, size=12)],
        ],
        colWidths=[_USABLE_W],
    )
    hdr_tbl.setStyle(
        TableStyle(
            [
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
                ("LINEBELOW", (0, 0), (-1, 0), 0.4, _rl_colors.HexColor("#cccccc")),
            ]
        )
    )
    story.append(hdr_tbl)
    story.append(Spacer(1, 3 * mm))

    tbl_data = [
        [
            _hdr_cell("Total Amount", "المبلغ الإجمالي", size=10),
            "",
            _hdr_cell("Unit Price", "سعر الوحدة", size=10),
            "",
            _hdr_cell("Qty.", "الكمية", size=10),
            _hdr_cell("Description", "البيان", size=10),
        ],
        [
            _hdr_cell_small("K.D", "دينار"),
            _hdr_cell_small("Fils", "فلس"),
            _hdr_cell_small("K.D", "دينار"),
            _hdr_cell_small("Fils", "فلس"),
            "",
            "",
        ],
    ]
    for row in items:
        ukd, uf = _kwd_to_kd_fils(row.get("unit_price") or 0)
        tkd, tf = _kwd_to_kd_fils(row.get("amount") or 0)
        qty_txt = row.get("qty")
        qty_disp = ""
        if qty_txt not in ("", None):
            try:
                qf = float(qty_txt)
                qty_disp = int(qf) if qf == int(qf) else qf
            except (ValueError, TypeError):
                qty_disp = qty_txt
        tbl_data.append(
            [
                _cell(tkd if tkd or tf else "", align=1),
                _cell(tf if tf else "", align=1),
                _cell(ukd if ukd or uf else "", align=1),
                _cell(uf if uf else "", align=1),
                _cell(qty_disp, align=1),
                _cell(row.get("description") or "", align=2),
            ]
        )
    tbl_data.append(
        [
            _cell(total_kd, bold=True, align=1, size=12),
            _cell(total_fils, bold=True, align=1, size=12),
            "",
            "",
            _cell("المجموع : / Total :", bold=True, align=2, size=12),
            "",
        ]
    )

    items_tbl = Table(tbl_data, colWidths=_COL_W, repeatRows=2)
    _last_row = len(tbl_data) - 1
    items_tbl.setStyle(
        TableStyle(
            [
                ("GRID", (0, 0), (-1, -1), 0.4, _rl_colors.HexColor("#444444")),
                ("BOX", (0, 0), (-1, -1), 1.2, _rl_colors.black),
                ("LINEBELOW", (0, 1), (-1, 1), 0.8, _rl_colors.black),
                ("SPAN", (0, 0), (1, 0)),
                ("SPAN", (2, 0), (3, 0)),
                ("SPAN", (4, 0), (4, 1)),
                ("SPAN", (5, 0), (5, 1)),
                ("SPAN", (4, _last_row), (5, _last_row)),
                ("BACKGROUND", (0, 0), (-1, 1), _rl_colors.HexColor("#f5f5f5")),
                ("FONTNAME", (0, 0), (-1, 1), _FN_B),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("ALIGN", (0, 0), (-1, -1), "CENTER"),
                ("ALIGN", (5, 0), (5, -1), "RIGHT"),
                ("TOPPADDING", (0, 0), (-1, 1), 9),
                ("BOTTOMPADDING", (0, 0), (-1, 1), 9),
                ("TOPPADDING", (0, 2), (-1, _last_row - 1), 8),
                ("BOTTOMPADDING", (0, 2), (-1, _last_row - 1), 8),
                ("LEFTPADDING", (0, 0), (-1, -1), 4),
                ("RIGHTPADDING", (0, 0), (-1, -1), 4),
                ("LEFTPADDING", (5, 0), (5, -1), 8),
                ("RIGHTPADDING", (5, 0), (5, -1), 8),
                ("TOPPADDING", (0, _last_row), (-1, _last_row), 10),
                ("BOTTOMPADDING", (0, _last_row), (-1, _last_row), 10),
                ("BACKGROUND", (0, _last_row), (-1, _last_row), _rl_colors.HexColor("#ececec")),
                ("FONTNAME", (0, _last_row), (-1, _last_row), _FN_B),
            ]
        )
    )
    story.append(items_tbl)

    doc.build(story)
    return buf.getvalue()


