RV_SEQ_KEY = "receipt_voucher_seq"
PV_COMPANY_AR = "شركة كريتيف ستوديو سوليوشنز للدعاية والإعلان ذ.م.م"
PV_COMPANY_EN = "Creative Studio Solutions Advertising Company W.L.L."
PV_ADDR_AR = "غرب أبو فطيرة الحرفية - شارع 25 - قسيمة 172\nمبنى بلوك كيو 1 - الدور الأول - مكتب رقم 3"
PV_ADDR_EN = "West Abu Fateera Handicraft area - Street 25\nBuilding 172 - Bloq Q1 - 1st Floor - Office 3"
PV_PHONE = "+965 98973651"
PV_IG = "cskwt"
PV_EMAIL = "info@cskwt.com"

VOUCHER_KINDS = {
    "payment": {
        "seq_key": PV_SEQ_KEY,
        "table": "payment_vouchers",
        "path": "/payment-vouchers",
        "api": "/api/payment-voucher",
        "title": "سندات الصرف",
        "one": "سند صرف",
        "badge_ar": "سند ص&#x200c;رف",
        "badge_en": "Payment Voucher",
        "payee_label": "صرفنا للسيد / للسادة",
        "payee_sheet": "صرفنا للسيد / للسادة :",
        "payee_en": "Received from",
        "payee_placeholder": "اسم المستلم / الجهة",
        "being_placeholder": "سبب الصرف / البيان",
        "icon": "fa-receipt",
        "back_menu": "/expenses-menu",
    },
    "receipt": {
        "seq_key": RV_SEQ_KEY,
        "table": "receipt_vouchers",
        "path": "/receipt-vouchers",
        "api": "/api/receipt-voucher",
        "title": "سندات القبض",
        "one": "سند قبض",
        "badge_ar": "سند قبض",
        "badge_en": "Receipt Voucher",
        "payee_label": "استلمنا من",
        "payee_sheet": "استلمنا من :",
        "payee_en": "Received from",
        "payee_placeholder": "اسم الدافع / الجهة",
        "being_placeholder": "سبب القبض / البيان",
        "icon": "fa-file-invoice-dollar",
        "back_menu": "/revenues",
    },
}


def _voucher_cfg(kind):
    return VOUCHER_KINDS.get(kind) or VOUCHER_KINDS["payment"]


def _format_pv_no(n):
    try:
        return str(int(n)).zfill(4)
    except (ValueError, TypeError):
        return "0001"


def peek_next_voucher_no(kind="payment"):
    """رقم السند التالي دون حجزه."""
    cfg = _voucher_cfg(kind)
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = ? LIMIT 1", (cfg["seq_key"],)
        ).fetchone()
        last = int(row[0] or 0) if row and row[0] not in (None, "") else 0
        return _format_pv_no(last + 1)
    finally:
        conn.close()


def allocate_voucher_no(kind="payment", preferred=None):
    """حجز رقم سند جديد. إذا مُرّر رقم أكبر أو يساوي التالي يُعتمد."""
    cfg = _voucher_cfg(kind)
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = ? LIMIT 1", (cfg["seq_key"],)
        ).fetchone()
        last = int(row[0] or 0) if row and row[0] not in (None, "") else 0
        nxt = last + 1
        try:
            pref = int(str(preferred).strip()) if preferred not in (None, "") else None
        except (ValueError, TypeError):
            pref = None
        if pref is not None and pref >= nxt:
            nxt = pref
        conn.execute(
            "INSERT OR REPLACE INTO app_settings (key, value) VALUES (?, ?)",
            (cfg["seq_key"], str(nxt)),
        )
        conn.commit()
        return _format_pv_no(nxt)
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def save_voucher(kind, payload):
    """حفظ السند (إدراج أو تحديث حسب رقم السند)."""
    import json

    cfg = _voucher_cfg(kind)
    table = cfg["table"]
    payload = payload if isinstance(payload, dict) else {}
    raw_no = str(payload.get("no") or payload.get("voucher_no") or "").strip()
    date_s = str(payload.get("date") or "").strip()
    payee = str(payload.get("payee") or "").strip()
    try:
        amount = float(payload.get("amount") or 0)
    except (ValueError, TypeError):
        amount = 0.0
    amount_words = str(payload.get("amount_words") or "").strip()
    pay_method = str(payload.get("pay_method") or payload.get("method") or "نقداً").strip()
    cheque_ref = str(payload.get("cheque") or payload.get("cheque_ref") or "").strip()
    being = str(payload.get("being") or "").strip()
    invoice_number = str(
        payload.get("invoice_number") or payload.get("invoice") or payload.get("invoice_no") or ""
    ).strip()

    candidates = []
    if raw_no:
        candidates.append(raw_no)
        try:
            candidates.append(_format_pv_no(raw_no))
        except Exception:
            pass

    conn = sqlite3.connect(DB_PATH)
    try:
        existing_no = None
        for cand in candidates:
            row = conn.execute(
                f"SELECT voucher_no FROM {table} WHERE voucher_no=? LIMIT 1", (cand,)
            ).fetchone()
            if row:
                existing_no = row[0]
                break

        if existing_no:
            voucher_no = existing_no
        else:
            voucher_no = allocate_voucher_no(kind, raw_no)

        store = {
            "no": voucher_no,
            "date": date_s,
            "payee": payee,
            "amount": amount,
            "amount_words": amount_words,
            "pay_method": pay_method,
            "cheque": cheque_ref,
            "being": being,
            "invoice_number": invoice_number,
        }
        blob = json.dumps(store, ensure_ascii=False)
        if existing_no:
            try:
                conn.execute(
                    f"""UPDATE {table} SET date=?, payee=?, amount=?, amount_words=?,
                       pay_method=?, cheque_ref=?, being=?, invoice_number=?, payload=?, updated_at=datetime('now')
                       WHERE voucher_no=?""",
                    (
                        date_s,
                        payee,
                        amount,
                        amount_words,
                        pay_method,
                        cheque_ref,
                        being,
                        invoice_number,
                        blob,
                        voucher_no,
                    ),
                )
            except sqlite3.OperationalError:
                conn.execute(
                    f"""UPDATE {table} SET date=?, payee=?, amount=?, amount_words=?,
                       pay_method=?, cheque_ref=?, being=?, payload=?, updated_at=datetime('now')
                       WHERE voucher_no=?""",
                    (date_s, payee, amount, amount_words, pay_method, cheque_ref, being, blob, voucher_no),
                )
        else:
            try:
                conn.execute(
                    f"""INSERT INTO {table}
                       (voucher_no, date, payee, amount, amount_words, pay_method, cheque_ref, being, invoice_number, payload)
                       VALUES (?,?,?,?,?,?,?,?,?,?)""",
                    (
                        voucher_no,
                        date_s,
                        payee,
                        amount,
                        amount_words,
                        pay_method,
                        cheque_ref,
                        being,
                        invoice_number,
                        blob,
                    ),
                )
            except sqlite3.OperationalError:
                conn.execute(
                    f"""INSERT INTO {table}
                       (voucher_no, date, payee, amount, amount_words, pay_method, cheque_ref, being, payload)
                       VALUES (?,?,?,?,?,?,?,?,?)""",
                    (voucher_no, date_s, payee, amount, amount_words, pay_method, cheque_ref, being, blob),
                )
        conn.commit()
        return voucher_no
    finally:
        conn.close()


def fetch_voucher_months(kind="payment"):
    """شهور السندات مع أرقامها: [(ym, label, [(voucher_no, payee, amount), ...]), ...]"""
    cfg = _voucher_cfg(kind)
    table = cfg["table"]
    conn = sqlite3.connect(DB_PATH)
    try:
        try:
            rows = conn.execute(
                f"""SELECT voucher_no, date, payee, amount FROM {table}
                   WHERE date IS NOT NULL AND length(date) >= 7
                   ORDER BY date DESC, voucher_no DESC"""
            ).fetchall()
        except sqlite3.OperationalError:
            conn.close()
            init_db()
            conn = sqlite3.connect(DB_PATH)
            rows = conn.execute(
                f"""SELECT voucher_no, date, payee, amount FROM {table}
                   WHERE date IS NOT NULL AND length(date) >= 7
                   ORDER BY date DESC, voucher_no DESC"""
            ).fetchall()
    finally:
        conn.close()
    months = {}
    order = []
    for voucher_no, date_s, payee, amount in rows:
        ym = str(date_s or "")[:7]
        if len(ym) < 7:
            continue
        if ym not in months:
            months[ym] = []
            order.append(ym)
        months[ym].append(
            (
                str(voucher_no or ""),
                str(payee or ""),
                float(amount or 0),
            )
        )
    result = []
    for ym in order:
        parts = ym.split("-")
        label = ym
        if len(parts) >= 2:
            try:
                year, month = int(parts[0]), int(parts[1])
                if 1 <= month <= 12:
                    label = f"{ARABIC_MONTHS[month - 1]} {year}"
            except (ValueError, IndexError):
                pass
        result.append((ym, label, months[ym]))
    return result


def get_voucher_by_no(kind, voucher_no):
    """جلب سند بالرقم."""
    cfg = _voucher_cfg(kind)
    table = cfg["table"]
    no = str(voucher_no or "").strip()
    if not no:
        return None
    candidates = [no]
    try:
        candidates.append(_format_pv_no(no))
    except Exception:
        pass
    conn = sqlite3.connect(DB_PATH)
    try:
        for cand in candidates:
            row = None
            try:
                row = conn.execute(
                    f"""SELECT voucher_no, date, payee, amount, amount_words, pay_method, cheque_ref, being, payload, invoice_number
                       FROM {table} WHERE voucher_no=? LIMIT 1""",
                    (cand,),
                ).fetchone()
            except sqlite3.OperationalError:
                row = conn.execute(
                    f"""SELECT voucher_no, date, payee, amount, amount_words, pay_method, cheque_ref, being, payload
                       FROM {table} WHERE voucher_no=? LIMIT 1""",
                    (cand,),
                ).fetchone()
            if row:
                inv = ""
                if len(row) > 9 and row[9]:
                    inv = str(row[9] or "")
                elif row[8]:
                    try:
                        import json as _json_pv_get

                        blob = _json_pv_get.loads(row[8] or "{}")
                        if isinstance(blob, dict):
                            inv = str(blob.get("invoice_number") or blob.get("invoice") or "")
                    except Exception:
                        inv = ""
                return {
                    "no": row[0] or "",
                    "date": row[1] or "",
                    "payee": row[2] or "",
                    "amount": float(row[3] or 0),
                    "amount_words": row[4] or "",
                    "pay_method": row[5] or "نقداً",
                    "cheque": row[6] or "",
                    "being": row[7] or "",
                    "invoice_number": inv,
                }
    finally:
        conn.close()
    return None


def peek_next_payment_voucher_no():
    return peek_next_voucher_no("payment")


def allocate_payment_voucher_no(preferred=None):
    return allocate_voucher_no("payment", preferred)


def save_payment_voucher(payload):
    return save_voucher("payment", payload)


def fetch_payment_voucher_months():
    return fetch_voucher_months("payment")


def get_payment_voucher_by_no(voucher_no):
    return get_voucher_by_no("payment", voucher_no)


