def _expense_invoice_scan_page_html():
    return f"""<!DOCTYPE html>
<html lang="ar" dir="rtl"><head><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" crossorigin="anonymous"><style>.btn i,.btn-save i,.btn-back i{{margin-left:8px;opacity:0.9}}</style><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1"><meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate">
<title>مسح مستند - المحاسب الذكي</title>
<style>{_EIS_PAGE_STYLES}</style></head><body>
<div class="eis-page">
<h1><i class="fa-solid fa-file-lines"></i> مسح مستند</h1>
<p class="eis-sub">مثل WhatsApp — يصحّح المنظور تلقائياً ويُبقي المستند مستقيماً وواضحاً بالألوان.</p>
<!--MSG-->
<div class="eis-card">
<div class="eis-scan-shell" id="eisScanShell">
<div class="eis-camera-view" id="eisCameraView">
<video id="eisVideo" autoplay playsinline muted></video>
<div class="eis-overlay"><div class="eis-doc-frame"><span class="eis-corner-bl"></span><span class="eis-corner-br"></span></div></div>
<div class="eis-top-bar">
<a href="/expenses-menu" class="eis-top-btn" id="eisCloseBtn" title="إغلاق"><i class="fa-solid fa-xmark"></i></a>
<span class="eis-top-title">Scan Document</span>
<button type="button" class="eis-top-btn ok" id="eisConfirmBtn" style="visibility:hidden" title="تأكيد"><i class="fa-solid fa-check"></i></button>
</div>
<div class="eis-bottom-bar" id="eisBottomBar">
<label class="eis-side-btn" title="معرض الصور"><i class="fa-solid fa-image"></i><input type="file" id="eisFile" accept="image/*"></label>
<button type="button" class="eis-shutter" id="eisShutter" title="التقاط"></button>
<label class="eis-side-btn" title="التقاط بالكاميرا"><i class="fa-solid fa-camera"></i><input type="file" id="eisFileCapture" accept="image/*" capture="environment"></label>
</div>
</div>
<div class="eis-camera-fallback" id="eisCameraFallback">
<p>تعذّر فتح الكاميرا — اختر صورة من المعرض أو التقط صورة.</p>
<label class="eis-btn eis-btn-save" style="cursor:pointer"><i class="fa-solid fa-image"></i> اختيار / التقاط صورة<input type="file" id="eisFileFallback" accept="image/*" capture="environment" style="display:none"></label>
</div>
<div class="eis-result" id="eisResult">
<div class="eis-preview-wrap"><img id="eisPreview" class="eis-preview" alt="معاينة المسح"></div>
<div class="eis-status" id="eisStatus"></div>
<div class="eis-actions">
<button type="button" class="eis-btn eis-btn-save" id="eisSaveBtn" disabled><i class="fa-solid fa-file-pdf"></i> حفظ PDF</button>
<button type="button" class="eis-btn eis-btn-retake" id="eisRetakeBtn"><i class="fa-solid fa-rotate-left"></i> إعادة المسح</button>
</div>
<p class="eis-hint">يمكنك إعادة المسح أو حفظ المستند كـ PDF في الأرشيف.</p>
</div>
</div>
</div>
</div>
<script>
(function(){{
var imageB64='';
var stream=null;
var video=document.getElementById('eisVideo');
var cameraView=document.getElementById('eisCameraView');
var cameraFallback=document.getElementById('eisCameraFallback');
var resultPanel=document.getElementById('eisResult');
var preview=document.getElementById('eisPreview');
var saveBtn=document.getElementById('eisSaveBtn');
var retakeBtn=document.getElementById('eisRetakeBtn');
var shutter=document.getElementById('eisShutter');
var statusEl=document.getElementById('eisStatus');
function setStatus(msg,type){{statusEl.className='eis-status '+(type||'info');statusEl.textContent=msg||'';}}
function stopCamera(){{if(stream){{stream.getTracks().forEach(function(t){{t.stop();}});stream=null;}}}}
function startCamera(){{
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){{showFallback();return;}}
  navigator.mediaDevices.getUserMedia({{video:{{facingMode:{{ideal:'environment'}},width:{{ideal:1920}},height:{{ideal:2560}}}},audio:false}})
    .then(function(s){{stream=s;video.srcObject=s;cameraView.style.display='flex';cameraFallback.classList.remove('active');}})
    .catch(function(){{showFallback();}});
}}
function showFallback(){{stopCamera();cameraView.style.display='none';cameraFallback.classList.add('active');}}
function showResult(){{
  cameraView.style.display='none';
  cameraFallback.classList.remove('active');
  resultPanel.classList.add('active');
  stopCamera();
}}
function showCamera(){{
  resultPanel.classList.remove('active');
  imageB64='';
  saveBtn.disabled=true;
  setStatus('');
  startCamera();
}}
function applyScanPreview(b64){{
  if(!b64){{return;}}
  imageB64=b64;
  preview.src=b64;
  saveBtn.disabled=false;
  showResult();
}}
function processDataUrl(dataUrl){{
  saveBtn.disabled=true;
  setStatus('جاري مسح المستند وتصحيح المنظور...','info');
  fetch('/api/expense-invoice-scan-preview',{{method:'POST',headers:{{'Content-Type':'application/json;charset=utf-8'}},body:JSON.stringify({{image:dataUrl}})}})
    .then(function(r){{return r.json().then(function(j){{return {{ok:r.ok,data:j}};}});}})
    .then(function(res){{
      if(!res.ok||!res.data.ok){{throw new Error((res.data&&res.data.error)||'تعذر المعالجة');}}
      applyScanPreview(res.data.image);
      setStatus('المستند جاهز — مستقيم وواضح بالألوان','ok');
    }})
    .catch(function(err){{setStatus(err.message||'تعذر المعالجة','err');saveBtn.disabled=true;}});
}}
function captureFromVideo(){{
  if(!video.videoWidth){{setStatus('الكاميرا غير جاهزة','err');return;}}
  var canvas=document.createElement('canvas');
  canvas.width=video.videoWidth;
  canvas.height=video.videoHeight;
  canvas.getContext('2d').drawImage(video,0,0);
  processDataUrl(canvas.toDataURL('image/jpeg',0.92));
}}
function readFile(file){{
  if(!file){{return;}}
  var reader=new FileReader();
  reader.onload=function(e){{processDataUrl(e.target.result);}};
  reader.readAsDataURL(file);
}}
function bindFileInput(el){{if(el)el.addEventListener('change',function(){{if(el.files&&el.files[0])readFile(el.files[0]);}});}}
bindFileInput(document.getElementById('eisFile'));
bindFileInput(document.getElementById('eisFileCapture'));
bindFileInput(document.getElementById('eisFileFallback'));
shutter.addEventListener('click',captureFromVideo);
retakeBtn.addEventListener('click',showCamera);
saveBtn.addEventListener('click',function(){{
  if(!imageB64){{setStatus('يرجى مسح مستند أولاً','err');return;}}
  saveBtn.disabled=true;
  setStatus('جاري حفظ PDF...','info');
  fetch('/expense-invoice-scan-save',{{method:'POST',headers:{{'Content-Type':'application/json;charset=utf-8'}},body:JSON.stringify({{image:imageB64}})}})
    .then(function(r){{return r.json().then(function(j){{return {{ok:r.ok,data:j}};}});}})
    .then(function(res){{
      if(!res.ok||!res.data.ok){{throw new Error((res.data&&res.data.error)||'تعذر الحفظ');}}
      setStatus('تم حفظ المسح PDF بنجاح','ok');
      setTimeout(function(){{window.location='/expense-invoice-scan?msg='+encodeURIComponent('تم حفظ المسح PDF')+'&type=ok';}},600);
    }})
    .catch(function(err){{setStatus(err.message||'تعذر الحفظ','err');saveBtn.disabled=false;}});
}});
startCamera();
}})();
</script>
</body></html>"""


