            if "multipart/form-data" not in _content_type_hdr:
                msg, msg_type = "يرجى اختيار ملف ZIP", "err"
            else:
                file_data = None
                boundary = None
                if "boundary=" in _content_type_hdr:
                    boundary = _content_type_hdr.split("boundary=")[-1].strip()
                if boundary:
                    delimiter = ("--" + boundary).encode()
                    for part in _raw_body.split(delimiter):
                        if b"filename=" not in part:
                            continue
                        headers_raw = part.split(b"\r\n\r\n", 1)[0].decode("utf-8", errors="ignore")
                        if 'name="backup_file"' not in headers_raw:
                            continue
                        body_part = part.split(b"\r\n\r\n", 1)[-1]
                        if body_part.endswith(b"\r\n"):
                            body_part = body_part[:-2]
                        if body_part:
                            file_data = body_part
                        break
                if not file_data:
                    msg, msg_type = "لم يتم اختيار ملف النسخة الاحتياطية", "err"
                else:
                    ok_restore, restore_msg = restore_app_backup_zip(file_data)
                    msg, msg_type = restore_msg, ("ok" if ok_restore else "err")
            self.send_response(303)
            self.send_header("Location", f"/restore-backup?msg={quote(msg)}&type={msg_type}")
            self.end_headers()
            return

